SELECT 'moj-all-verified-judgments-review-002-chunk-071' AS batch_name,
       (SELECT count(*) FROM public.legal_documents WHERE id IN (
          SELECT (x->>'id')::uuid FROM jsonb_array_elements($archive_payload$[{"id":"d7dc568f-ce1c-5a1b-bfe5-739ccb6655e5","document_type":"judgment","category":"judicial","subcategory":"general","title":"مخدرات -ترويج الهيروين املخدر -تستر -شروع يف تسليم الهيروين املخدر -حيازة الهيروين املخدر -تعزير بالسجن واجللد ومصادرة اجلوال والشريحة املستخدمني يف اجلرمية -إبعاد .","document_number":"3433171","case_number":"33476048","judgment_number":null,"decision_number":null,"circular_number":null,"court":"محكمة الاستئناف","circuit":null,"issuing_authority":"وزارة العدل السعودية","document_date":null,"hijri_date":"1434/2/9","year":"1434","subject":"مخدرات -ترويج الهيروين املخدر -تستر -شروع يف تسليم الهيروين املخدر -حيازة الهيروين املخدر -تعزير بالسجن واجللد ومصادرة اجلوال والشريحة املستخدمني يف اجلرمية -إبعاد .","summary":null,"facts":null,"claims":null,"reasoning":null,"ruling":null,"principle_text":null,"full_text":"  ‫رقم الصك‪ 3433171:‬تاريخه‪1434/2/9 :‬هـ‬\n                  ‫رقم الدعوى‪33476048 :‬‬\n   ‫رقم قرار التصديق من محكمة االستئناف‪:‬‬\n          ‫‪ 34221172‬تاريخه‪1434/5/25 :‬هـ‬\n\n\n‫مخدرات ‪ -‬ترويج الهيروين املخدر‪ -‬تســتر‪ -‬شــروع يف تســليم الهيروين‬\n‫املخــدر‪ -‬حيــازة الهيرويــن املخــدر‪ -‬تعزيــر بالســجن واجللــد ومصــادرة‬\n                ‫اجلــوال والشــريحة املســتخدمني يف اجلرميــة ‪ -‬إبعــاد ‪.‬‬\n\n\n\n     ‫ال يف تهمة رواه أبو داود ‪.‬‬\n                             ‫‪ -1‬حبس النبي صلى اهلل عليه وسلم رج ً‬\n‫‪ -2‬املــواد (‪ )38‬و (‪ )56‬و (‪ )53‬مــن نظــام مكافحــة املخــدرات واملؤثــرات‬\n                                                              ‫العقليــة‪.‬‬\n\n\n\n‫ادعــى املدعــي العــام ضــد املدعــى عليــه بتســليم وحيــازة الهيرويــن لغرض‬\n‫الترويــج والشــروع يف ترويــج الهيرويــن وطلــب املدعــي العــام إثبــات مــا‬\n‫أســند إليــه واحلكــم عليــه بالســجن واجللــد والغرامــة املاليــة وإبعــاده عــن‬\n‫البــاد بعــد انتهــاء عقوبــة الســجن وعــدم الســماح لــه بالعــودة مــرة أخــرى‬\n‫ومصــادرة املبلــغ املضبــوط بحــوزة املدعــى عليــه ومصــادرة اجلوالــن‬\n‫املضبوطــن وإلغــاء شــريحتيهما كونهمــا مســتخدمتان يف اجلرميــة وعــدم‬\n‫صــرف الشــريحتني لنفــس املشــترك‪ ،‬حيــث أنــه مت القبــض علــى املدعــى‬\n‫ـاء علــى إخباريــة مــن أحــد املصــادر الســرية عــن وجــود شــخص‬    ‫عليــه بنـ ً‬\n‫وافــد يقــوم بترويــج كبســوالت الهيرويــن املخــدر ويعاونــه شــخص آخــر‬\n\n\n                                                                                      ‫‪208‬‬\n\f      ‫عــن طريــق متريــر بطاقــات شــحن اجلــوال حيث يقــوم املــروج بالتفاوض مع‬\n      ‫املشــتري للمــادة املخــدرة ويقــوم بأخــذ بطاقــات الشــحن مســبقة الدفــع‬\n      ‫عوض ـ ًا عــن النقــد ثــم يقــوم بعــد ذلــك بإرســال أحــد معاونيــه ليرمــي‬\n      ‫الهيرويــن املخــدر للمتعاطــي واتضــح أن املعــاون هــو املدعــى عليــه‪ ،‬أقــر‬\n      ‫املدعــى عليــه بالتســليم والشــروع يف التســليم وأنكــر علمــه أن احلبــوب‬\n      ‫( الكبســوالت ) هــي الهيرويــن املخــدر‪ ،‬ثبتــت إدانــة املدعــى عليــه‬\n      ‫‪ ،‬بنــاء علــى مــا تقــدم حكمــت احملكمــة بتعزيــره بالســجن واجللــد‬\n      ‫والغرامــة واألبعــاد ومصــادرة اجلــوال والشــريحة ‪ ،‬قنــع املدعــى عليــه‬\n      ‫وصــدق احلكــم‬ ‫باحلكــم وقــرر املدعــي العــام االعتــراض بغيــر الئحــة ُ‬\n                                                       ‫مــن محكمــة االســتئناف‪.‬‬\n\n\n\n      ‫احلمــد هلل وحــده وبعــد فلــدي أنــا ‪ ........‬القاضــي يف احملكمــة اجلزائيــة‬\n      ‫بالريــاض وبنــاء علــى املعاملــة احملالــة لنــا مــن فضيلــة رئيــس احملكمــة‬\n      ‫اجلزائيــة بالريــاض برقــم ‪ ......‬وتاريــخ ‪ .....‬ه ـ املقيــدة باحملكمــة برقــم‬\n      ‫‪ .....‬وتاريــخ ‪ ........‬ه ـ ففــي يــوم الثالثــاء املوافــق‪ ......‬ه ـ افتتحــت اجللســة‬\n      ‫الســاعة الثامنــة وفيهــا قــدم املدعــي العــام ‪ .........‬الئحــة دعــوى عامــة‬\n      ‫ضــد ‪ ....... /‬يحمــل رخصــة إقامــة رقــم ( ‪ )......‬باكســتاني اجلنســية‬\n      ‫جــاء فيهــا بتاريــخ ‪.......‬ه ـ قبــض علــى املذكــور مــن قبــل إحــدى فــرق‬\n      ‫شــعبة املكافحــة و البحــث و التحــري بــإدارة مكافحــة املخــدرات‬\n      ‫الســرية عــن وجــود‬ ‫مبنطقــة الريــاض بنــاء إلخباريــة مــن أحــد املصــادر ّ‬\n      ‫شــخص باكســتاني يدعــى‪ .....‬يتواجــد علــى اجلــوال رقــم ( ‪ ) .......‬يقــوم‬\n      ‫بترويــج كبســوالت الهيرويــن املخــدر و يعاونــه شــخص يدعــى ‪ ....‬وهــو‬\n\n‫‪209‬‬\n\f‫املذكــور عــن طريــق متريــر بطاقــات شــحن اجلــوال مســبقة الدفــع حيــث‬\n‫يقــوم املــروج (‪ )....‬التفــاوض مــع املشــتري للمــادة املخــدرة هاتفيـ ًا و يقــوم‬\n‫بأخــذ بطاقــات شــحن اجلــوال مســبوقة الدفــع عوضـ ًا عــن النقــد ثــم يقــوم‬\n‫بعــد ذلــك بإرســال أحــد أعوانــه ليرمــي الهيرويــن املخــدر للمتعاطــي و‬\n‫اتضــح لــدى فرقــة القبــض أن املذكــور يعــاون املــروج (‪ )...‬و ذلــك برمــي‬\n‫الهيرويــن املخــدر يف أماكــن محــددة بطلــب مــن املــروج ‪ ....‬واتضــح أن‬\n‫املذكــور ليــس لــه مــكان محــدد و ليــس لــه ســكن وهــو يتواجــد دائمــا‬\n‫بحــي الشميســي حيــث يفتــرش احلدائــق العامــة و ينــام بهــا و قــد أســفرت‬\n‫إجــراءات التحقيــق عــن اتهــام ‪ ............ /‬بتســلم (‪ )26‬ســت و عشــرون‬\n‫كبســولة إال ربــع الكبســولة بهــا الهرويــن املخدر تــزن جميعا ( ‪)197.5‬‬\n‫مائــة و ســبعة و تســعون جرامـ ًا و خمســة أعشــار اجلــرام بقصــد االجتــار‬\n‫و الترويــج و الشــروع يف تســليم كبســولة إال ربــع تــزن (‪ )5.5‬خمســة‬\n‫جرامــات و خمســة أعشــار اجلــرام مــن ذات الكميــة لقصــد الترويــج و‬\n‫الســابق املجــرم مبوجــب املــادة ( الثالثــة )‬   ‫ترويجــه الهيرويــن املخــدر يف ّ‬\n‫مــن نظــام مكافحــة املخــدرات و املؤثــرات العقليــة و تســتره علــي مصدر‬\n‫مــا ضبــط املعاقــب علــى ذلــك شــرع ًا و ذلــك لألدلــة و القرائــن التاليــة ‪:‬‬\n‫‪ /1‬مــا تضمنــه اعترافــه حتقيقـ ًا املنــوه عنــه املــدون علــى الصفحــات رقــم‬\n‫(‪ 1‬إلــى ‪ ) 3‬مــن ملــف التحقيــق املرفــق لفــة رقــم (‪ /2 )15‬مــا تضمنــه‬\n‫إقــراره املنــوه عنــه املــدون علــى الصفحــة رقــم (‪ )1‬مــن ملــف التحقيــق‬\n‫املرفــق لفــة رقــم (‪ /3 )16‬مــا تضمنتــه أقوالــه األوليــة املنــوه عنهــا املدونــة‬\n‫علــى الصفحــة رقــم (‪ )21‬مــن ملــف ضبــط إجــراءات االســتدالل يف‬\n‫قضايــا املخــدرات املرفــق لفــة رقــم (‪ /4 )1‬مــا تضمنــه محضــر القبــض‬\n‫و التفتيــش املنــوه املــدون علــى الصفحــات رقــم ( ‪2‬و‪12‬و‪ )13‬مــن ملــف‬\n\n\n                                                                                          ‫‪210‬‬\n\f      ‫ضبــط إجــراءات االســتدالل يف قضايــا املخــدرات املرفــق لفــة رقــم (‪)1‬‬\n      ‫‪ /5‬مــا تضمنــه التقريــر الكيميائــي الشــرعي املشــار إليــه املرفــق لفــة‬\n      ‫رقــم (‪ )13‬و ببحــث ســوابقه اتضــح عــدم وجــود ســوابق مســجلة حتــى‬\n      ‫تاريخــه و حيــث إن مــا أقــدم عليــه املذكــور فعــل محــرم و معاقــب عليــه‬\n      ‫شــرع ًا و نظامـ ًا مبوجــب نظــام مكافحــة املخــدرات و املؤثــرات العقليــة‬\n      ‫يف عقوباتــه األصليــة و التكميليــة لــذا أطلــب إثبــات إدانتــه مبــا أســند‬\n                                                         ‫إليــه و احلكــم عليــه باآلتــي ‪:‬‬\n      ‫‪ /1‬بعقوبــة احلبــس و اجللــد و الغرامــة املاليــة وفق ـ ًا للفقــرة ( األولــى )‬\n      ‫مــن املــادة (‪ )38‬مــن نظــام مكافحــة املخــدرات و املؤثــرات العقليــة‬\n      ‫و تشــديد العقوبــة بحقــه وفق ـ ًا للبنــد (ج) مــن الفقــرة ( الثانيــة ) مــن‬\n      ‫نفــس املــادة مــن النظــام املشــار إليــه ‪ /2‬إبعــاده إلــى خــارج اململكــة بعــد‬\n      ‫انتهــاء تنفيــذ عقوبــة ســجنه و عــدم الســماح لــه بالعــودة إليهــا مــرة أخــرى‬\n      ‫وفق ـ ًا للفقــرة ( الثانيــة) مــن املــادة (‪ )56‬مــن نفــس النظــام املشــار إليــه‬\n      ‫‪ /3‬مصــادرة املبلــغ املضبــوط بحــوزة املذكــور وقــدره (‪ )2056‬ألفــان‬\n      ‫و ســتة و خمســون ريــا ًال كونــه مــن نتــاج بيــع املخــدرات اســتناد ًا إلــى‬\n      ‫الفقــرة ( الثانيــة ) مــن املــادة (‪ )53‬مــن نظــام مكافحــة املخــدرات و‬\n      ‫املؤثــرات العقليــة ‪ /4‬مصــادرة اجلوالــن املضبوطــن معــه األول ‪ .....‬يحمل‬\n      ‫الرقــم املصنعــي رقــم ( ‪ ) ......‬و الثانــي ‪ .......‬يحمــل الرقــم املصنعــي رقــم‬\n      ‫‪.......‬ز كونهمــا اســتخدما يف اجلرميــة اســتناد ًا إلــى الفقــرة ( األولــى )‬\n      ‫مــن املــادة (‪ )53‬مــن نظــام مكافحــة املخــدرات و املؤثــرات العقليــة ‪/5‬‬\n      ‫إلغــاء الشــريحيتني الهاتفيتــن املســتخدمتني يف اجلرميــة و التــي حتمــان‬\n      ‫الرقــم ( ‪ ) .........‬و الرقــم ( ‪ )........‬و عــدم صرفهمــا لنفــس املشــترك يف‬\n      ‫حالــة صــدور حكــم باملصــادرة و إبــاغ الشــركة مصــدرة الشــريحة‬\n\n\n‫‪211‬‬\n\f‫بذلــك اســتناد ًا لتعميــم ســمو وزيــر الداخليــة رقــم ( ‪ ) 9798‬و تاريــخ‬\n‫‪1428/2/10-9‬ه ـ و اهلل املوفــق هــذه دعــواي و بعرض ذلك على املدعى‬\n‫ا إن مــا ذكــره املدعــي العــام مــن‬ ‫عليــه الــذي يجيــد العربيــة أجــاب قائـ ً‬\n‫وجــود الكبســولة معــي وأنــي سأســلمها لشــخص وداللتــي علــى موضــع‬\n‫خمــس و عشــرين كبســولة يف منــزل طــن صحيــح و قــد اســتلمتها مــن‬\n‫الشــخص الباكســتاني املذكــور و ذكــر لــي أنهــا حبــوب عــاج و ال‬\n‫أعلــم أنهــا مخــدرات و كانــت االتصــاالت بينــي و بينــه علــى جوالــي‬\n‫رقــم ‪ ...........‬وجــوال آخــر ال أحفــظ رقمــه و املبلــغ الــذي ضبــط معــي هــو‬\n‫مــن نتــاج عملــي يف البويــات و أنــا لــم أســلم أي شــخص شــيئ ًا مــن هــذه‬\n‫احلبــوب هكــذا أجــاب وباالطــاع علــى التقريــر الكيميائــي الصــادر‬\n‫مــن مركــز الســموم بالريــاض رقــم ‪ /6351‬س يف ‪........‬ه ـ املتضمــن‬\n‫إيجابيــة العينــات ملــادة الهرويــن أ‪.‬ه ـ بتصــرف كمــا ألفيــت قــول املدعــى‬\n‫عليــه علــى ص (‪ )2،1‬لفــة (‪ )15‬أن أخبــره أن احلبــوب التــي ســلمها لــه‬\n‫حبــوب محظــورة فبنــاء علــى مــا ســلف مــن الدعــوى و اإلجابــة و إلقــرار‬\n‫املدعــى عليــه بتســلمه ســت ًا و عشــرين كبســولة إال ربــع عــن طريــق‬\n‫جواليــه املذكوريــن و تبــن أنهــا حتــوي الهرويــن املخــدر و لعــدم قبــول‬\n‫ادعــاه بأنــه ال يعرفهــا بداللــة إفادتــه أن مــن ســلمها لــه أخبــره أنهــا حبــوب‬\n‫محظــورة ولقيــام القرائــن الدالــة علــى ترويجــه الهرويــن وهــي إقــراره‬\n‫بوضعــه كبســوالت الهرويــن املذكــورة يف منــزل الطــن و شــروعه يف‬\n‫ترويــج كبســولة إال ربــع و إلفصاحــه عــن مصــدر هــذه الكبســوالت‬\n‫و لعــدم وجــود الدليــل املقــدم مــن املدعــي العــام علــى أن املــال املقبــوض‬\n‫مــع املدعــى عليــه مــن نتــاج املخــدرات و ألن األصــل يف املــال احلرمــة و‬\n‫ملشــروعية التعزيــر بالقرائــن كمــا حبــس النبــي صلــى اهلل عليــه و ســلم‬\n\n\n                                                                                          ‫‪212‬‬\n\f      ‫ا يف تهمــة رواه أبــو داود و قــال حســن صحيــح و ألن الشــروع يف‬            ‫رج ـ ً‬\n      ‫الفعــل يف حكــم الفعــل و ملــا جــاء يف املــادة (‪ )38‬و ( ‪ )56‬و (‪ )53‬مــن‬\n      ‫نظــام املخــدرات و النتشــار ترويــج و تهريــب الهرويــن مــن هــذه اجلاليــة‬\n      ‫فقــد ثبــت لــدي إدانــة املدعــى عليــه بتســلم ســت ًا و عشــرين كبســولة‬\n      ‫إال ربعــا بهــا الهرويــن املخــدر و وزنهــا جميع ـ ًا مائــة و ســبعة و تســعون‬\n      ‫جرام ـ ًا وخمســة أعشــار اجلــرام بقصــد االجتــار و الترويــج و الشــروع‬\n      ‫يف تســليم كبســولة إال ربع ـ ًا تــزن خمســة جرامــات وخمســة أعشــار‬\n      ‫اجلــرام مــن ذات الكميــة بقصــد الترويــج ولــم يثبــت لــدي تســتره علــى‬\n      ‫مصدرهــا أو ترويجــه للهيرويــن يف الســابق و إمنــا قامــت القرائــن علــى‬\n      ‫ترويجــه الهيرويــن فيمــا ســبق و حكمــت عليــه مبــا يلــي ‪ /1 :‬ســجنه‬\n      ‫خمــس ســنوات تبــدأ مــن تاريــخ اإليقــاف و جلــده أمــام النــاس خمســمائة‬\n      ‫جلــده مفرقــة علــى عشــر دفعــات كل دفعــة خمســون جلــده بــن كل‬\n      ‫دفعتــن عشــرة أيــام و تغرميــه ثالثــة آالف ريــال و إبعــاده عــن اململكــة بعد‬\n      ‫انتهــاء ســجنه بعــد تصفيــة مالــه و مــا عليــه مــن حقــوق وعــدم الســماح لــه‬\n      ‫بالعــودة إ ّال فيمــا تســمح بــه أنظمــة احلــج و العمــرة و مصــادرة اجلوالــن‬\n      ‫املضبوطــن معــه ورقمهــا املصنعــي ‪.......‬و (‪ ).......‬و إلغــاء شــريحتهما رقــم‬\n      ‫(‪ )..........‬و (‪ )..........‬وعــدم صرفهــا نفــس املشــترك و إبــاغ الشــركة‬\n      ‫مصــدرة الشــريحتني بذلــك ‪2‬ـ صــرف النظــر عــن املطالبــة مبصــادرة‬\n      ‫املبلــغ و التســتر لعــدو وجــود موجبهمــا و بعــرض احلكــم عليهمــا قــرر‬\n      ‫املدعــى عليــه القناعــة و املدعــي العــام االعتــراض مكتفي ـ ًا بالئحــة‬\n      ‫االعتراضيــة وكان النطــق يف ‪......‬ه ـ و أغلقــت‬\n                                                    ‫ّ‬             ‫الدعــوى عــن الالئحــة‬\n      ‫اجللســة الســاعة التاســعة و النصــف و صلــى اهلل وســلم علــى نبينــا محمــد‬\n                                                                  ‫و علــى آلــه و صحبــه ‪.‬‬\n\n\n‫‪213‬‬\n\f‫احلمــد هلل وحــده ‪...‬وبعــد فقــد اطلعنــا نحــن قضــاة الدائــرة اجلزائيــة‬\n‫الرابعــة مبحكمــة االســتئناف بالريــاض علــى املعاملــة الــواردة مــن‬\n‫فضيلــة رئيــس احملكمــة اجلزائيــة بالريــاض برقــم ‪ ..........‬وتاريــخ ‪.......‬‬\n‫ه ـ املرفــق بهــا القــرار الصــادر مــن فضيلــة القاضــي الشــيخ ‪............/‬‬\n‫املســجل برقــم ‪...........‬وتاريــخ ‪.......‬ه ـ اخلــاص بدعــوى املدعــي العــام ضــد‬\n‫‪(.........../‬باكســتاني اجلنســية) يف قضيــة مخــدرات علــى النحــو املوضــح‬\n‫بالقــرار املتضمــن حكــم فضيلتــه مبــا هــو مــدون ومفصــل بــه‪ ،‬وبدراســة‬\n‫القــرار وصــورة ضبطــه وأوراق املعاملــة قــررت الدائــرة باألكثريــة‬\n‫املصادقــة علــى احلكــم‪ .‬و اهلل املوفــق وصلــى اهلل علــى نبينــا محمــد‬\n                                                     ‫وعلــى آلــه وصحبــه وســلم ‪.‬‬\n\n\n\n\n                                                                                       ‫‪214‬‬\n\f","legal_articles":[],"source_id":"831db040-0b05-5921-907d-640530e541d8","source_file_id":"396a5809-4e7b-56b3-9eb0-4f45acc6dbb7","source_page_start":208,"source_page_end":214,"original_source":"وزارة العدل السعودية","acquisition_source":"official_ministry_download_preserved_in_central_archive","source_url":null,"content_hash":"fb7d4d8820f49dd9f6f12908c97275f4f426bde41e66405603721a6df32b8888","normalized_text_hash":"c87c7a462f024ac2614d888e36ff3b4d5109e4258971dd6f7c88940fb86099f7","status":"review","review_status":"manual_field_review_pending","legal_search_eligibility":false,"legacy_id":"collector-1434-v18-p208-3433171"},{"id":"e2d2f47e-f1e8-5433-859d-6e5c911e8377","document_type":"judgment","category":"judicial","subcategory":"general","title":"مخدرات -نقل بقصد الترويج -قات -إنكار املدعى عليه علمه مبا مت نقله -التعزير بالسجن والغرامة.","document_number":"33412318","case_number":"33553670","judgment_number":null,"decision_number":null,"circular_number":null,"court":"محكمة الاستئناف","circuit":null,"issuing_authority":"وزارة العدل السعودية","document_date":null,"hijri_date":"1434/9/16","year":"1434","subject":"مخدرات -نقل بقصد الترويج -قات -إنكار املدعى عليه علمه مبا مت نقله -التعزير بالسجن والغرامة.","summary":null,"facts":null,"claims":null,"reasoning":null,"ruling":null,"principle_text":null,"full_text":"      ‫رقم الصك‪ 33412318 :‬تاريخه‪1434/9/16:‬هـ‬\n                        ‫رقم الدعوى‪33553670:‬‬\n         ‫رقم قرار التصديق من محكمة االستئناف‪:‬‬\n                ‫‪ 34169622‬تاريخه‪1434/3/23 :‬هـ‬\n\n\n      ‫مخــدرات ‪ -‬نقــل بقصــد الترويــج ‪ -‬قــات ‪ -‬إنــكار املدعــى عليــه علمــه مبــا‬\n                                             ‫مت نقلــه ‪ -‬التعزيــر بالســجن والغرامــة‪.‬‬\n\n\n\n\n      ‫‪ -1‬الفقــرة األولــى مــن األمــر الســامي الكــرمي رقــم (‪ )59633‬يف‬\n                                                          ‫‪1432 /12 /9‬هــ‪.‬‬\n               ‫‪ -2‬املادة (‪ )3‬من قرار مجلس الوزراء رقم(‪ )11‬لعام ‪1374‬هـ ‪.‬‬\n         ‫‪ -3‬املادة (‪ )3‬من قرار وزير الداخلية رقم ( ‪ ) 2057‬يف ‪1404/5/26‬هـ‬\n\n\n\n\n      ‫ادعــى املدعــي العــام ضــد املدعــى عليــه بنقــل قــات بقصــد االجتــار‬\n      ‫وطلــب إثبــات مــا أســند إليــه واحلكــم بتعزيــره ‪،‬حيــث مت إيقاف الســيارة‬\n      ‫التــي يقودهــا املدعــى عليــه مــن قبــل الدوريــة األمنيــة وبتفتيــش الســيارة‬\n      ‫عثــر علــى دوالب بداخلــه كميــة مــن نبــات القــات وأثبــت التقريــر‬\n      ‫الكيميائــي الشــرعي إيجابيــة العينــة املضبوطــة لنبــات القــات احملظــور‬\n      ‫وصــادق املدعــى عليــه علــى الدعــوى بــدون مترجــم وذلــك لكونــه يفهــم‬\n      ‫العربيــة ‪،‬وبنــاء علــى مــا تقــدم حكمــت احملكمــة بتعزيــره بالســجن‬\n      ‫خمــس ســنوات وتغرميــه خمســة آالف ريــال واعتــرض املدعــي العــام‬\n                   ‫‪،‬وصــدق احلكــم مــن محكمــة االســتئناف ‪.‬‬       ‫بــدون الئحــة ُ‬\n\n‫‪215‬‬\n\f‫احلمــد هلل وحــده أمــا بعــد فلــدي أنــا ‪.....‬القاضــي باحملكمــة اجلزائيــة‬\n‫بجــازان وبنــاء علــى املعاملــة الــواردة مــن دائــرة االدعــاء العــام بجــازان‬\n‫واملقيــدة بــوارد احملكمــة برقــم (‪ )331624474‬وتاريــخ ‪1433/8/28‬هـ‬\n‫واحملالة من فضيلة الرئيس برقم (‪ )33553670‬وتاريخ ‪1433/8/28‬هـ‬\n‫واملتعلقــة بدعــوى املدعــي العــام ضــد ‪.....‬املتهــم يف قضيــة قــات عليــه‬\n‫ففــي هــذا اليــوم الســبت ‪1433/9/16‬ه ـ افتتحــت اجللســة األولــى يف متــام‬\n‫الســاعة العاشــرة والربــع وفيهــا حضــر املدعــي العــام ‪.....‬املوجــه باخلطــاب‬\n‫رقــم (‪ ).....‬وتاريــخ ‪1433/3/22‬ه ـ وادعــى علــى احلاضــر ‪.....‬باكســتاني‬\n‫اجلنســية يحمــل رخصــة اإلقامــة رقــم (‪ ).....‬الصــادرة مــن جــوازات الدمــام‬\n‫أنــه يف متــام الســاعة الثانيــة عشــر ظهــر ًا مــن يــوم االثنــن ‪1433/7/7‬ه ـ‬\n‫وأثنــاء قيــام إحــدى دوريــات املجاهديــن بعملهــا قدمــت ســيارة مــن نــوع ‪....‬‬\n‫مــن صنــع عــام (‪2004‬م) وحتمــل رقــم اللوحــة ‪ ).....‬تعــود ملكيتهــا ل‪.....‬‬\n‫(مت حجزهــا حلــن مراجعــة مالكهــا) فتــم إيقافهــا واتضــح أنهــا بقيــادة‬\n‫املدعــى عليــه وبتفتيــش الســيارة عثــر علــى (دوالب) بداخلــه كميــة‬\n‫مــن نبــات القــات احملظــور بلــغ وزنهــا (‪ 329‬كجــم) ثالثمائــة وتســعة‬\n‫وعشــرين كيلــو جــرام وأثبــت التقريــر الكيميائــي الشــرعي رقــم (‪).....‬‬\n‫وتاريخ ‪1433/7/15‬هـ الصادر من قســم الســموم والكيمياء الشــرعية‬\n‫باملستشــفى إيجابيــة العينــة املرســلة منــه لنبــات القــات احملظــور املــدرج‬\n‫يف اجلــدول رقــم (‪ )4‬ورقــم (‪ )2‬فئــة (ا) و (ج) امللحــق بنظــام مكافحــة‬\n‫املخــدرات واملؤثــرات العقليــة الصــادر باملرســوم امللكــي رقــم م‪ 39/‬يف‬\n‫‪1426/7/8‬ه ـ ومت إيقافــه اســتناد ًا للقــرار الــوزاري رقــم (‪ )1900‬وتاريــخ‬\n\n                                                                                      ‫‪216‬‬\n\f      ‫‪1428/7/8‬ه ـ وباســتجواب املدعــى عليــه ومواجهتــه بالتهمــة املنســوبة‬\n      ‫إليــه أقــر بصحــة واقعــة القبــض و أنكــر حيازتــه للكميــة املضبوطــة‬\n      ‫البالــغ وزنهــا (‪ 329‬كجــم) ثالثمائــة وتســعة وعشــرين كيلــو جــرام‬\n      ‫مــن نبــات القــات احملظــور وذكــر بأنهــا تعــود ل ــشخص مينــي اجلنســية‬\n      ‫ال يعــرف عنــه أي معلومــات طلــب منــه إيصــال (الــدوالب) إلــى محافظــة‬\n      ‫فيفــاء مببلــغ وقــدره (‪ )120‬مائــة وعشــرين ريــاال وال يعلــم عــن وجــود‬\n      ‫القــات بداخلــه وقــد صــادق علــى أقوالــه وبالبحــث عــن ســوابقه لــم‬\n      ‫يعثــر لــه علــى ســوابق مســجلة وقــد أســفر التحقيــق معــه عــن توجيــه‬\n      ‫االتهــام إليــه بارتــكاب جرميــة نقــل مــا وزنــه (‪ 329‬كجــم) ثالثمائــة‬\n      ‫وتســعة وعشــرين كيلــو جــرام مــن نبــات القــات احملظــور لقصــد‬\n      ‫االجتــار واملجــرم مبوجــب الفقــرة الثانيــة مــن املــادة الثالثــة مــن نظــام‬\n      ‫مكافحــة املخــدرات واملؤثــرات العقليــة الصــادر باملرســوم امللكــي‬\n      ‫رقــم م‪ 39/‬يف ‪1426/7/8‬ه ـ وألن مــا أقــدم عليــه املذكــور فعــل محــرم‬\n      ‫شــرع ًا ومعاقــب عليــه نظامــا مبوجــب قــرار مجلــس الــوزراء رقــم (‪)11‬‬\n      ‫لعــام ‪1374‬ه ـ ومــا حلــق بــه مــن تعديــات فقــد طلــب املدعــي العــام إثبــات‬\n      ‫إدانتــه مبــا أســند إليــه واحلكــم بتعزيــره يف ضــوء املــادة الثالثــة مــن‬\n      ‫القــرار الــوزاري املشــار إليــه أعــاه إنفــاذ ًا لألمــر الســامي الكــرمي رقــم‬\n      ‫(‪ )59633‬وتاريــخ ‪1432/12/9‬ه ـ وباحلديــث مــع املدعــى عليــه تبــن‬\n      ‫أنــه يفهــم العربيــة ويحســن رد اجلــواب وبعــرض الدعــوى علــى املدعــى‬\n      ‫عليــه صــدق واقعــة القبــض وبقيادتــه الســيارة املشــار إليهــا ونفــى علمــه‬\n      ‫وعالقتــه بكميــة القــات املضبوطــة وقــرر قائــا إن شــخصا مينيــا طلــب‬\n      ‫منــه نقــل (دوالب) مــن محافظــة الدايــر إلــى محافظــة فيفــا مقابــل مائــة‬\n      ‫وعشــرين ريــاال فقامــا بتحميلــه يف الســيارة وال علــم لــه مبــا كان فيــه‬\n\n\n‫‪217‬‬\n\f‫هكــذا أجــاب وبالرجــوع إلــى أوراق املعاملــة واالطــاع علــى التقريــر‬\n‫الكيميائــي الشــرعي وثبــت ســوابق املدعــى عليــه وجــدت طبــق مــا يف‬\n‫الدعــوى عليــه فبنــاء علــى مــا تقــدم مــن الدعــوى واإلجابــة ولضعــف مــا‬\n‫دفــع بــه املدعــى عليــه لكبــر حجــم الكميــة املضبوطــة مــن نبــات القــات‬\n‫وهــو أمــر يلحــظ جليــا عنــد حتميــل (الــدوالب) كمــا أن لنبــات القــات‬\n‫رائحــة ال ميكــن أن تخفــى خاصــة مــع كبــر حجــم الكميــة وملــا تضمنــه‬\n‫األمــر الســامي الكــرمي رقــم (‪ )59633‬وتاريخ ‪1432/12/9‬هـ يف فقرته‬\n‫األولــى مــن املوافقــة علــى أن تطبــق احملاكــم علــى مرتكبــي جرائــم‬\n‫القــات العقوبــات املعمــول بهــا قبــل نفــاذ نظــام مكافحــة املخــدرات‬\n‫واملؤثــرات العقليــة لذلــك كلــه فقــد ثبتــت لــدي إدانــة املدعــى عليــه بنقــل‬\n‫كميــة القــات املذكــورة أعــاه بقصــد االجتــار وهــو يســتحق العقوبــة‬\n‫علــى ذلــك وفــق املــادة (‪ )3‬مــن قــرار مجلــس الــوزراء رقــم (‪ )11‬عــام‬\n‫‪1374‬ه ـ واملــادة (‪ )3‬مــن قــرار ســمو وزيــر الداخليــة رقــم (‪ )2057‬وتاريــخ‬\n‫‪1404/5/26‬ه ـ وقــد حكمــت عليــه لذلــك تعزيــرا بالســجن مــدة خمــس‬\n‫ســنوات تبــدأ مــن تاريــخ القبــض عليــه وإيقافــه علــى ذمــة هــذه القضيــة‬\n‫يف ‪1433/7/7‬ه ـ وتغرميــه مبلــغ خمســة آالف ريــال يــؤول إلــى اخلزينــة‬\n‫العامــة للدولــة هــذا مــا ثبــت لــدي وبــه حكمــت وبعرضــه علــى الطرفــن‬\n‫قــرر املدعــي العــام معارضتــه وطلــب رفعــه حملكمــة االســتئناف دون‬\n‫الئحــة فأجبتــه لذلــك وقــرر املدعــى عليــه القناعــة بــه وقــد جــرى النطــق‬\n‫بــه يف متــام الســاعة العاشــرة والنصــف وبــاهلل التوفيــق وصلــى اهلل وســلم‬\n     ‫علــى نبينــا محمــد وآلــه وصحبــه أجمعــن حــرر يف ‪1433/9/16‬هـ ـ‬\n‫ويف هــذا اليــوم األربعــاء ‪1433/11/17‬ه ـ افتتحــت اجللســة الثانيــة‬\n‫يف متــام الســاعة العاشــرة والربــع وكانــت املعاملــة قــد وردت مــن‬\n\n\n                                                                                       ‫‪218‬‬\n\f      ‫محكمــة االســتئناف رفــق خطــاب رئيســها رقــم (‪)331777988‬‬\n      ‫وتاريــخ ‪1433/11/10‬ه ـ املقيــد بهــذه احملكمــة برقــم (‪)332032997‬‬\n      ‫وتاريــخ ‪1433/11/16‬ه ـ واحملالــة مــن فضيلــة الرئيــس ومرفــق بهــا قــرار‬\n      ‫املالحظــة الصــادر عــن الدائــرة اجل ــزائية الثانيــة برقــم (‪)33440727‬‬\n      ‫وتاريــخ ‪1433/10/28‬ه ـ ويتضمــن تقــرر إعادتهــا لفضيلــة حاكمهــا‬\n      ‫ملالحظــة أن فضيلــة ناظــر القضيــة لــم يتضمــن حكمــه إبعــاد املدعــى‬\n      ‫عليــه عــن البــاد حســب التعليمــات انتهــى قــدر احلاجــة منــه وجوابــا‬\n      ‫علــى مــا ذكــره أصحــاب الفضيلــة أقــول مســتعين ًا بــاهلل إن عقوبــة‬\n      ‫اإلبعــاد لــم تــرد يف املــادة الثالثــة مــن قــرار مجلــس الــوزراء رقــم (‪)11‬‬\n      ‫لعــام ‪1374‬ه ـ والتــي جــاء األمــر الســامي الكــرمي رقــم (‪ )59633‬وتاريــخ‬\n      ‫‪1433/12/9‬ه ـ بتطبيقهــا وأمــر اإلقامــة واإلبعــاد لــه نظــام يحكمــه‬\n      ‫حســبما نــص عليــه تعميــم معالــي وزيــر العــدل رقــم (‪/183/8‬ت) وتاريــخ‬\n      ‫‪1408/10/9‬ه ـ (التصنيــف املوضوعــي املجلــد اخلامــس ص ‪62‬ـ‪ )63‬وبــه‬\n      ‫لــم يظهــر لــي عــدول عمــا رقــم أعــاه وأمــرت بإحلــاق ذلــك يف القــرار‬\n      ‫وصــورة ضبطــه وبعــث كامــل أوراق املعاملــة إلــى محكمــة االســتئناف‬\n                                        ‫وبــاهلل التوفيــق حــرر يف ‪1433/11/17‬ه ـ‬\n      ‫ويف هــذا اليــوم األحــد ‪1434/2/17‬ه ـ افتتحــت اجللســة الثالثــة يف‬\n      ‫متــام الســاعة العاشــرة والنصــف وكانــت املعاملــة قــد وردت مــن‬\n      ‫محكمــة االســتئناف رفــق خطــاب رئيســها رقــم (‪)332105274‬‬\n      ‫وتاريخ‪1433/12/26‬ه ـ املقيــد بهــذه احملكمــة برقــم (‪)346357‬‬\n      ‫وتاريخ‪1434/1/3‬ه ـ واحملالــة مــن فضيلــة الرئيــس ومرفــق بهــا قــرار‬\n      ‫املالحظــة الصــادر عــن الدائــرة اجل ــزائية الثانيــة برقــم (‪)33472424‬‬\n      ‫وتاريخ‪1433/12/19‬ه ـ ويتضمــن تقــرر إعادتهــا ملالحظــة أن مــا أجــاب‬\n\n\n‫‪219‬‬\n\f‫بــه فضيلــة ناظــر القضيــة غيــر مقنــع فقــد نــص علــى إبعــاد مــن هــو أقــل‬\n‫جرمــا مــن املدعــى عليــه وال يعنــي عــدم النــص علــى ذلــك يف املــادة املشــار‬\n‫إليهــا أنــه ال يبعــد فــكل مــن ارتكــب جرمــا وهــو أجنبــي فيبعــد اتقــاء‬\n‫لشــره انتهــى قــدر احلاجــة منــه وجوابــا علــى ذلــك أقــول مســتعينا بــاهلل‬\n‫إننــي قــد ذكــرت مســتندا لــي يف اجلــواب تعميــم معالــي وزيــر العــدل‬\n‫املشــار إليــه وهــو مــا لــم يناقشــه أصحــاب الفضيلــة يف قــرار املالحظــة‬\n‫ولــم يــرد حســب علمــي مغيــر ملقتضــاه حتــى تاريخــه ومــا حكمــت بــه‬\n‫جــار علــى منصــوص النظــام وأمــا التنصيــص علــى إبعــاد مــن هــو أقــل‬\n‫جرمــا مــن املدعــى عليــه فذلــك وارد يف قــرار املنظــم واحلكــم مبقتضــاه‬\n‫جــار علــى ذلــك ومحــل البحــث فيمــا لــم يــرد بــه نــص والتعميــم املذكــور‬\n‫يعالــج ذلــك وبــه لــم يظهــر لــي عــدول عمــا رقــم أعــاه وأمــرت بإحلــاق ذلك‬\n‫يف القــرار وصــورة ضبطــه وبعــث كامــل أوراق املعاملــة إلــى محكمــة‬\n ‫االســتئناف لتدقيــق احلكــم وبــاهلل التوفيــق حــرر يف ‪1434/2/17‬ه ـ‬\n‫احلمــد هلل وحــده وبعــد فقــد اطلعنــا نحــن قضــاة الدائــرة الثانيــة لتدقيــق‬\n‫القضايــا اجلزائيــة مبحكمــة االســتئناف مبنطقــة عســير علــى املعاملــة‬\n‫الــواردة مــن فضيلــة رئيــس احملكمــة اجلزائيــة بجــازان رقــم ‪346357‬‬\n‫وتاريــخ ‪1434/2/19‬ه ـ املرفــق بهــا القــرار الصــادر مــن فضيلــة القاضــي‬\n‫باحملكمــة الشــيخ ‪..... /‬رقــم ‪ 33412318‬وتاريــخ ‪1433/9/16‬ه ـ‬\n‫اخلــاص بدعــوى املدعــي العــام ضــد ‪ (..... /‬باكســتاني اجلنســية ) يف‬\n‫قضيــة ( قــات ) علــى الصفــة املوضحــة يف القــرار املتضمــن حكــم‬\n‫فضيلتــه مبــا هــو مــدون ومفصــل فيــه وحيث ســبق دراســة القــرار وصورة‬\n‫ضبطــه وأوراق املعاملــة وباالطــاع علــى مــا أجــاب بــه فضيلتــه وأحلقــه‬\n‫ـاء علــى قرارنــا رقــم ‪ 33472424‬وتاريــخ‬       ‫بالقــرار وصــورة ضبطــه بنـ ً‬\n\n                                                                                       ‫‪220‬‬\n\f      ‫‪1433/12/19‬ه ـ و قرارنــا رقــم ‪ 33440727‬وتاريــخ ‪1433/10/28‬ه ـ‬\n      ‫تقــررت املوافقــة علــى احلكــم بعــد اإلجــراء األخيــر ‪ .‬واهلل املوفــق وصلــى‬\n                                   ‫اهلل علــى نبينــا محمــد وآلــه وصحبــه وســلم ‪.‬‬\n\n\n\n\n‫‪221‬‬\n\f","legal_articles":[],"source_id":"831db040-0b05-5921-907d-640530e541d8","source_file_id":"396a5809-4e7b-56b3-9eb0-4f45acc6dbb7","source_page_start":215,"source_page_end":221,"original_source":"وزارة العدل السعودية","acquisition_source":"official_ministry_download_preserved_in_central_archive","source_url":null,"content_hash":"01c31ce2d9d68341f29da341cd52ea359f13208454fc7936348d9e8ac93628bf","normalized_text_hash":"08c0614fee6fd09c15ddf73eb812abf531fb54f0735c08eb326a51543bfd2313","status":"review","review_status":"manual_field_review_pending","legal_search_eligibility":false,"legacy_id":"collector-1434-v18-p215-33412318"},{"id":"462f34eb-ec5b-577a-a9e3-7b660ece8c10","document_type":"judgment","category":"judicial","subcategory":"general","title":"مخدرات -اشتراك يف ترويج -قات -مقاومة رجال األمن -مساعدة املدعى عليهما مروج على الهرب -تداخل العقوبات التعزيرية - التعزير بالسجن واجللد.","document_number":"33462509","case_number":"33598578","judgment_number":null,"decision_number":null,"circular_number":null,"court":"محكمة الاستئناف","circuit":null,"issuing_authority":"وزارة العدل السعودية","document_date":null,"hijri_date":"1433/11/22","year":"1434","subject":"مخدرات -اشتراك يف ترويج -قات -مقاومة رجال األمن -مساعدة املدعى عليهما مروج على الهرب -تداخل العقوبات التعزيرية - التعزير بالسجن واجللد.","summary":null,"facts":null,"claims":null,"reasoning":null,"ruling":null,"principle_text":null,"full_text":"‫رقم الصك‪ 33462509:‬تاريخه‪1433/11/22 :‬هـ‬\n                   ‫رقم الدعوى‪33598578:‬‬\n    ‫رقم قرار التصديق من محكمة االستئناف‪:‬‬\n           ‫‪ 3418844‬تاريخه‪1434/01/21:‬هـ‬\n\n\n‫مخدرات ‪ -‬اشــتراك يف ترويج ‪ -‬قات ‪ -‬مقاومة رجال األمن ‪ -‬مســاعدة‬\n‫املدعــى عليهمــا مــروج علــى الهــرب ‪ -‬تداخــل العقوبــات التعزيريــة ‪-‬‬\n                                            ‫التعزيــر بالســجن واجللــد‪.‬‬\n\n\n\n‫‪ -1‬مــا قــرره أهــل العلــم يف تداخــل العقوبــات التعزيريــة حيــث جــاء‬\n‫يف كشــاف القنــاع ج ‪ 485/ 20‬للبهوتــي ( ولــو توجــه عليــه تعزيــرات‬\n‫علــى معــاص شــتى فــإن متحضــت هلل تعالــى واحتــد نوعهــا كأن قبــل‬\n‫أجنبيــة مــرارا أو اختلــف نوعهــا بــأن قبــل أجنبيــة وملــس أخــرى قصــدا‬\n                                      ‫تداخلــت وكفــاه تعزيــر واحــد ) ‪.‬‬\n‫‪ -2‬املادة الرابعة من قرار وزير الداخلية رقم (‪ )2057‬يف ‪1404/5/26‬هـ‪.‬‬\n                         ‫‪ -3‬القرار الوزاري رقم (‪ )3818‬يف ‪1410/9/28‬هـ‬\n                     ‫‪ -4‬قرار وزير الداخلية رقم (‪ )1900‬يف ‪1428/7/9‬هـ‬\n\n\n\n\n‫ادعــى املدعــي العــام ضــد املدعــى عليهمــا أحدهمــا أجنبــي واآلخــر‬\n‫ســعودي باالشــتراك يف بيــع القــات ومقاومــة رجــال األمــن وطلــب إثبــات‬\n‫مــا أســند إليهمــا ومعاقبتهمــا تعزيــر ًا وتعزيرهمــا ملقاومــة رجــال األمــن ‪،‬‬\n‫حيــث مت مالحظــة شــخص يقــوم بترويــج القــات من قبــل فرقة مكافحة‬\n\n                                                                                      ‫‪222‬‬\n\f      ‫املخــدرات ومت التفــاوض معــه علــى شــرائه ويف احلــال مت القبــض عليــه‬\n      ‫وبحوزتــه القــات ثــم قــام بطلــب املســاعدة فحضــر مجموعــة مــن‬\n      ‫األشــخاص وقامــوا مبقاومــة الفرقــة ومســاعدة املــروج علــى الهــرب ومت‬\n      ‫القبــض علــى املدعــى عليهمــا وهمــا ممــن قامــا مبســاعدة املــروج علــى‬\n      ‫الهــرب وأثبــت التقريــر الكيميائــي الشــرعي إيجابيــة العينــة املضبوطــة‬\n      ‫لنبــات القــات احملظــور ‪ ،‬كمــا أقــر املدعــى عليــه األول بحيــازة القــات‬\n      ‫بقصــد االســتعمال وأنكــر املشــاركة ببيــع القــات ومقاومــة رجــال‬\n      ‫األمــن ‪ ،‬كمــا أنكــر املدعــى عليــه الثانــي الدعــوى ‪ ،‬و أحضــر املدعــي‬\n      ‫العــام شــاهدين مــن الفرقــة القابضــة وشــهدا مبقاومــة املدعــى عليهمــا‬\n      ‫للفرقــة ومســاعدة املــروج علــى الهــرب ولــم تتضمــن شــهادتهما مــا يديــن‬\n      ‫املدعــى عليهمــا باالشــتراك يف بيــع القــات وصــرف النظــر عــن طلــب‬\n      ‫املدعــي العــام مبعاقبتهمــا وإثبــات إدانــة املدعــى عليــه األول بحيــازة‬\n      ‫القــات بقصــد التعاطــي ومعاقبتــه تعزيــر ًا ‪،‬ومت إثبــات إدانــة املدعــى‬\n      ‫عليهمــا مبقاومــة رجــال األمــن واشــتراكهما يف تخليــص املقبــوض عليــه‬\n      ‫مــن قبــل رجــال األمــن وتعزيرهمــا لقــاء ذلــك بالســجن ســنتني وجلدهمــا‬\n      ‫ثالثمائــة جلــدة مفرقــة علــى دفعــات مقــدار كل دفعــة خمســة وســبعون‬\n      ‫‪،‬وصــدق‬\n            ‫وقنــع املدعــى عليهمــا واعتــرض املدعــي العــام بــدون الئحــة ُ‬\n                                               ‫احلكــم مــن محكمــة االســتئناف‪.‬‬\n\n\n\n      ‫احلمــد هلل وحــده أمــا بعــد فلــدي أنــا ‪.....‬القاضــي باحملكمــة اجلزائيــة‬\n      ‫بجــازان وبنــاء علــى املعاملــة الــواردة مــن دائــرة االدعــاء العــام بجــازان‬\n      ‫واملقيدة بوارد احملكمة برقم (‪ )331795904‬وتاريخ ‪1433/10/14‬هـ‬\n\n‫‪223‬‬\n\f‫واحملالــة مــن فضيلــة الرئيــس برقــم (‪ )33598578‬وتاريــخ‬\n‫‪1433/10/14‬ه ـ واملتعلقــة بدعــوى املدعــي العــام ضــد كل مــن االول‬\n‫‪.....‬والثانــي ‪ .....‬املتهمــان يف قضيــة قــات عليــه ففــي هــذا اليــوم الســبت‬\n‫‪1433/10/28‬ه ـ افتتحــت اجللســة األولــى يف متــام الســاعة العاشــرة إال‬\n‫ربعــا وفيهــا حضــر املدعــي العــام ‪.....‬املوجــه باخلطــاب رقــم (‪ ).....‬وتاريــخ‬\n‫‪1433/3/22‬ه ـ وادعــى علــى احلاضريــن كل مــن األول ‪.....‬ميني اجلنســية‬\n‫يحمــل بطاقــة بديلــة برقــم (‪ ).....‬صــادرة مــن إدارة مكافحــة املخــدرات‬\n‫بتاريــخ ‪1433/8/13‬ه ـ والثانــي ‪.....‬ســعودي اجلنســية يحمــل الهويــة‬\n‫الوطنيــة ورقــم ســجله املدنــي (‪ ).....‬أنــه بتاريــخ ‪1433/8/13‬ه ـ وأثنــاء‬\n‫قيــام إحــدى فــرق مكافحــة املخــدرات بعملهــا املعتــاد مبحافظــة الــدرب‬\n‫ـاء علــى املعلومــات الــواردة مــن أحــد املتعاونــن ومفادهــا وجــود‬       ‫وبنـ ً‬\n‫شــخص يدعــى ‪.....‬يقــوم بترويــج مــادة القــات يف محافظــة بيــش عليــه متــت‬\n‫مالحظــة املــروج وعنــد مقابلتــه مــن قبــل رئيــس الفرقــة وهــو يحمــل بيــده‬\n‫حزمــه يشــتبه أن تكــون مــن نبــات القــات احملظــور ملفوفــة داخــل قماش‬\n‫ومت التفــاوض معــه علــى شــرائها ويف احلــال مت القبــض علــى املــروج‬\n‫وضبطــت بحوزتــه احلزمــة التــي يريــد بيعهــا وهــي عبــارة عــن نبــات القــات‬\n‫احملظــور بلــغ وزنهــا (‪250‬جــم) مائتــن وخمســن جرامــا وأثنــاء القبــض‬\n‫عليــه صــاح بصــوت مرتفــع يطلــب مســاعدته ويف احلــال حضــر مجموعــة‬\n‫أشــخاص رجــال وبينهــم نســاء وقامــوا مبســاعدة املــروج حتــى مكنــوه‬\n‫مــن الهــرب وذلــك بعــد مقاومــة عنيفــة علــى إثرهــا أصيــب فيهــا رئيــس‬\n‫الفرقــة ومت القبــض علــى املدعــى عليهمــا وهمــا ممــن قامــوا مبســاعدة‬\n‫املــروج علــى الهــرب وأثبــت التقريــر الكيميائــي الشــرعي رقــم (‪).....‬‬\n‫بتاريــخ ‪1433/8/21‬ه ـ الصــادر مــن مستشــفى ‪ ....‬إيجابيــة العينــة‬\n\n\n                                                                                       ‫‪224‬‬\n\f      ‫املرســلة مــن الكميــة املضبوطــة لنبــات القــات احملظــور املــدرج باجلــدول‬\n      ‫رقــم (‪ )2‬فئــة (أ‪،‬ج) واجلــدول رقــم (‪ )4‬امللحقــن بنظــام مكافحــة‬\n      ‫املخــدرات واملؤثــرات العقليــة الصــادر باملرســوم امللكــي رقــم م‪ 39/‬يف‬\n      ‫‪1426/7/8‬ه ـ ومت إيقافهمــا اســتناد ًا للقــرار الــوزاري رقــم (‪)1900‬‬\n      ‫وتاريــخ ‪1432/7/9‬ه ـ املبنــي علــى املــادة (‪ )112‬مــن نظــام اإلجــراءات‬\n      ‫اجلزائيــة وبالبحــث عــن ســوابقهما عثــر لــأول منهمــا علــى ســابقة نصــب‬\n      ‫واحتيــال ولــم يعثــر للثانــي منهمــا علــى ســوابق مســجلة حتــى تاريخــه‬\n      ‫وباســتجواب املدعــي عليهمــا وبعــد مواجهتهمــا بالتهمــة املنســوبة إليهمــا‬\n      ‫أنكــرا عالقتهمــا بكميــة القــات املضبوطــة البالــغ وزنهــا (‪ 250‬جــم)‬\n      ‫مائتــن وخمســن جرامــا وأنهمــا لــم يقومــا مبســاعدة املــروج علــى الهــرب‬\n      ‫وصادقــا علــى أقوالهمــا بذلــك حتقيقـ ًا وقــد أســفر التحقيــق مــع املدعــي‬\n      ‫عليهمــا عــن توجيــه االتهــام إليهمــا باشــتراكهما يف بيــع مــا وزنــه (‪250‬‬\n      ‫جــم) مائتــن وخمســن جرامــا مــن نبــات القــات احملظــور عــن طريــق‬\n      ‫االتفــاق واملســاعدة واملجــرم مبوجــب الفقــرة رقــم (‪ )2‬مــن املــادة الثالثــة‬\n      ‫مــن نظــام مكافحــة املخــدرات واملؤثــرات العقليــة الصــادر باملرســوم‬\n      ‫امللكــي رقــم (م‪ )39/‬وتاريــخ ‪1426/7/8‬ه ـ ومبقاومــة رجــال األمــن‬\n      ‫وألن مــا أقــدم عليــه املدعــي عليهمــا فعــل محــرم شــرع ًا ومعاقــب عليــه‬\n      ‫نظامـ ًا مبوجــب قــرار مجلــس الــوزراء رقــم (‪ )11‬لعــام ‪1374‬ه ـ ومــا حلــق‬\n      ‫بــه مــن تعديــات فقــد طلــب املدعــي العــام إثبــات إدانتهمــا مبــا أســند‬\n      ‫إليهمــا واحلكــم بتعزيرهمــا يف ضــوء املــادة الثالثــة مــن القــرار الــوزاري‬\n      ‫املشــار إليــه أعــاه إنفــاذ ًا لألمــر الســامي الكــرمي رقــم (‪ )59633‬وتاريــخ‬\n      ‫‪1432/12/9‬ه ـ وتعزيرهمــا شــرع ًا لقــاء مقاومتهمــا لرجــال األمــن‬\n      ‫وبعــرض الدعــوى علــى املدعــى عليــه األول صــدق تاريــخ القبــض‬\n\n\n‫‪225‬‬\n\f‫والســابقة املســجلة عليــه وأنكــر االتهــام املوجــه إليــه وقــرر قائال كانت‬\n‫بحوزتــي كميــة القــات املشــار إليهــا يف الدعــوى بقصــد االســتعمال‬\n‫الشــخصي فتفاجــأت بشــخص يركــض خلفــي فلــذت بالفــرار ودخلــت‬\n‫منــزل املدعــى عليــه الثانــي هــذا احلاضــر ثــم جــرى القبــض علــي بعــد أن‬\n‫ســلمني مالــك املنــزل ملكافحــة املخــدرات وال صحــة التهامــي ببيــع‬\n‫القــات أو مفاوضــة رجــال األمــن يف ذلــك هكذا أجــاب وبعرض الدعوى‬\n‫علــى املدعــى عليــه الثانــي أجــاب قائــا مــا ذكــره املدعــي العــام غيــر‬\n‫صحيــح جملــة وتفصيــا بــل بالتاريــخ املشــار اليــه يف الدعــوى اســتيقظت‬\n‫علــى أصــوات النســاء يف منزلــي وعنــد خروجــي تبــن لــي وجود أشــخاص‬\n‫يف حــوش املنــزل وبســؤالهم عــن ســبب دخولهــم أفادونــي بأنهــم مــن‬\n‫مكافحــة املخــدرات وأن املدعــى عليــه األول مطلــوب لهــم وقــد الذ‬\n‫مبنزلــي عندهــا أخرجــت املدعــى عليــه األول مــن منزلــي وســلمته لهــم‬\n‫فقبــض علــي معــه أيضــا ووجــه إلــي هــذا االتهــام هكــذا أجــاب وبســؤال‬\n‫املدعــي العــام البينــة علــى دعــواه اســتمهل يف إحضارهــا إلــى جلســة تاليــة‬\n‫هكــذا أجــاب ويف جلســة تاليــه وفيهــا حضــر املدعــي العــام واملدعــى‬\n‫عليهمــا وجــرى ســؤال املدعــي العــام عــن البينــة التي اســتمهل إلحضارها‬\n‫يف اجللســة املاضيــة فأحضــر للشــهادة كال مــن ‪.....‬ســعودي اجلنســية‬\n‫يحمــل الهويــة الوطنيــة ورقــم ســجله املدنــي (‪ ).....‬واحلفيظــة رقــم (‪).....‬‬\n‫وتاريــخ ‪1426/4/15‬ه ـ الصــادرة مــن أحــوال صبيــا مضــى مــن عمــره‬\n‫(‪ 23‬عامــا) ويســكن قريــة ‪.....‬ويعمــل بــإدارة مخــدرات الــدرب و‪.....‬‬\n‫ســعودي اجلنســية يحمــل الهويــة الوطنيــة ورقــم ســجله املدنــي (‪).....‬‬\n‫واحلفيظــة رقــم (‪ ).....‬وتاريــخ ‪1426/6/11‬ه ـ الصــادرة مــن أحوال جازان‬\n‫مضــى مــن عمــره (‪ 24‬عامــا) ويســكن قريــة ‪ .....‬ويعمــل بــإدارة مخــدرات‬\n\n\n                                                                                     ‫‪226‬‬\n\f      ‫ا أشــهد بــاهلل تعالــى‬\n                             ‫الــدرب وبســؤال األول منهمــا عمــا لديــه أجــاب قائـ ً‬\n      ‫أنــه يف يــوم مــن األيــام ال أذكــره وردت إخباريــة عــن طريــق أحــد‬\n      ‫املتعاونيــن يفيــد عــن وجــود شــخص يقــوم ببيــع القــات يف حــي ‪.....‬يف‬\n      ‫محافظــة بيــش وباالنتقــال إلــى املوقــع وجــد الشــخص ومت التفــاوض معــه‬\n      ‫علــى شــراء حزمــة مــن القــات وعنــد االســتالم منــه مت القبــض عليــه‬\n      ‫فصــاح طالبــا املســاعدة فتجمهــر علينــا أنــاس كثــر منهــم رجــال ونســاء‬\n      ‫وخلصــوا الشــخص املقبــوض عليــه وأصيــب أحــد زمالئنــا ومتكنــا مــن‬\n      ‫القبــض علــى املدعــى عليهمــا وهمــا ممــن قــام مبقاومتنــا وتخليــص‬\n      ‫الشــخص املقبــوض عليــه هــذا مــا لــدي وبــه أشــهد وبســؤال الثانــي منهما‬\n      ‫ا أشــهد بــاهلل تعالــى أنــه يف يــوم مــن األيــام ال‬\n                                                             ‫عمــا لديــه أجــاب قائ ـ ً‬\n      ‫أذكــره ويف حــي ‪.....‬يف محافظــة بيــش مت التفــاوض مــع أحد األشــخاص‬\n      ‫علــى شــراء حزمــة مــن القــات وعنــد االســتالم منــه مت القبــض عليــه‬\n      ‫فصــاح طالبــا املســاعدة فتجمهــر علينــا أنــاس كثــر منهــم رجــال ونســاء‬\n      ‫وخلصــوا الشــخص املقبــوض عليــه وأصيــب أحــد زمالئنــا ومتكنــا مــن‬\n      ‫القبــض علــى املدعــى عليهمــا وهمــا ممــن قــام مبقاومتنــا وتخليــص‬\n      ‫الشــخص املقبــوض عليــه هــذا مــا لــدي وبــه أشــهد وبعــرض الشــاهدين‬\n      ‫وشــهادتهما علــى املدعــى عليــه األول وهــل لــه طعــن يف دينهمــا أو‬\n      ‫مروءتهمــا أجــاب قائــا أمــا شــهادتهما فغيــر صحيحــة وأمــا الشــاهدان‬\n      ‫فــا أعلــم عــن حالهمــا هكــذا أجــاب وبعــرض الشــاهدين وشــهادتهما‬\n      ‫علــى املدعــى عليــه الثانــي وهــل لــه طعــن يف دينهمــا أو مروءتهمــا أجــاب‬\n      ‫قائــا أمــا شــهادتهما فغيــر صحيحــة وأمــا الشــاهدان فــا أعلــم عــن‬\n      ‫حالهمــا هكــذا أجــاب ويف اجللســة حضــر ‪.....‬ســعودي اجلنســية يحمــل‬\n      ‫الهويــة الوطنيــة ورقــم ســجله املدنــي (‪ ).....‬و‪.....‬ســعودي يحمــل الهويــة‬\n\n\n‫‪227‬‬\n\f‫الوطنيــة ورقــم ســجله املدنــي (‪ ).....‬وشــهدا بعدالــة الشــاهدين وأنهمــا‬\n‫مقبــوال الشــهادة وبســؤال املدعــي العــام هــل لديــك مزيــد بينــة أجــاب‬\n‫قائــا ال أعلــم لــي مزيــد بينــة علــى مــا بــأوراق املعاملــة هكــذا أجــاب‬\n‫وبالرجــوع إلــى أوراق املعاملــة جــرى االطــاع علــى ثبــت ســوابق املدعــى‬\n‫عليهمــا والتقريــر الكيميائــي الشــرعي فوجــدت مطابقــة ملــا يف الدعوى‬\n‫كمــا جــرى االطــاع علــى بقيــة لفــات املعاملــة ولــم أجــد بهــا مــا يديــن‬\n‫املدعــى عليهمــا باالشــتراك يف بيــع نبــات القــات وبســؤال املدعــي العــام‬\n‫هــل لديــك مزيــد بينــة أجــاب قائــا ال أعلــم لــي مزيــد بينــة هكــذا أجــاب‬\n‫عليــه فبنــاء علــى مــا تقــدم مــن الدعــوى واإلجابــة وإلقــرار املدعــى عليــه‬\n‫األول بحيــازة كميــة مــن نبــات القــات بقصــد االســتعمال الشــخصي‬\n‫ولعجــز املدعــي العــام عــن إقامــة البينــة املثبتــة إلدانــة املدعــى عليهمــا‬\n‫باالشــتراك يف بيع كمية من نبات القات ولشــهادة الشــاهدين املعدلني‬\n‫شــرعا مبقامــة املدعــى عليهمــا لهــم مــع مجموعــة مــن األشــخاص‬\n‫وتخليصهــم الشــخص املقبــوض عليــه مــن قبضتهــم وشــهادتهما بإصابــة‬\n‫أحــد رجــال األمــن أثنــاء هــذه املقاومــة لذلــك كلــه وملــا تضمنــه األمــر‬\n‫الســامي الكــرمي رقــم (‪ )59633‬وتاريــخ ‪1432/12/9‬ه ـ يف فقرتــه‬\n‫األولــى مــن املوافقــة علــى أن تطبــق احملاكــم علــى مرتكبــي جرائــم‬\n‫القــات العقوبــات املعمــول بهــا قبــل نفــاذ نظــام مكافحــة املخــدرات‬\n‫واملؤثــرات العقليــة فقــد قــررت مــا يلــي أوال لــم تثبــت لــدي إدانــة املدعــى‬\n‫عليهمــا باالشــتراك يف بيــع كميــة مــن نبــات القــات وصرفــت النظــر عــن‬\n‫طلــب املدعــي العــام إثبــات إدانــة املدعــى عليهمــا بذلــك ومجازاتهمــا يف‬\n‫ضــوء املــادة الثالثــة مــن قــرار مجلــس الــوزراء رقــم (‪ )11‬لعــام ‪1374‬ه ـ‬\n‫وثبتــت لــدي إدانــة املدعــى عليــه األول حســب اعترافــه بحيــازة كميــة‬\n\n\n                                                                                        ‫‪228‬‬\n\f      ‫مــن نبــات القــات بقصــد التعاطــي وهــو يســتحق العقوبــة التعزيريــة علــى‬\n      ‫ذلــك وفــق املــادة (‪ )4‬مــن قــرار ســمو زيــر الداخليــة رقــم (‪ )2057‬وتاريــخ‬\n      ‫‪1404/5/26‬ه ـ املعدلــة بالقــرار الــوزاري رقــم (‪ )3818‬وتاريــخ‬\n      ‫‪1410/9/28‬ه ـ ثانيــا ثبتــت لــدي إدانــة املدعــى عليهمــا مبقاومــة رجــال‬\n      ‫األمــن مــع أشــخاص آخريــن واشــتراكهما يف تخليــص شــخص مقبــوض‬\n      ‫عليــه مــن قبــل رجــال األمــن وقــد نتــج عــن هــذه املقاومــة إصابــة أحــد‬\n      ‫رجــال األمــن وهمــا يســتحقان التعزيــر البليــغ لقــاء ذلــك وملــا قــرره أهــل‬\n      ‫العلــم يف تداخــل العقوبــات التعزيريــة قــال العالمــة البهوتــي (ولــو توجــه‬\n      ‫عليــه تعزيــرات علــى معــاص شــتى فــإن متحضــت هلل تعالــى واحتــد نوعهــا‬\n      ‫كأن قبــل أجنبيــة مــرار ًا أو اختلــف نوعهــا بــأن قبــل أجنبيــة وملــس أخــرى‬\n      ‫قصــد ًا تداخلــت وكفــاه تعزيــر واحــد) كشــاف القنــاع عــن مــن اإلقنــاع‬\n      ‫(ج‪20‬ص‪ )485‬فقــد قــررت االكتفــاء مبجــازاة املدعــى عليــه األول علــى‬\n      ‫جرمــه يف مقاومــة رجــال األمــن وتخليــص الشــخص املقبــوض عليــه وملــا‬\n      ‫يف الفعــل الــذي أقــدم عليــه املدعــى عليهمــا مــن مجابهــة لرجــال األمــن‬\n      ‫أثنــاء قيامهــم بواجبهــم ومتكــن للمفســدين مــن اســتمرار إجرامهــم‬\n      ‫وحمايتهــم والدفــاع عنهــم وتخليصهــم مــن أيــدي العدالــة وملــا يف فعلهمــا‬\n      ‫مــن اســتخفاف بقــوة رجــال األمــن وتعــد عليهــم واشــتراك يف إحلــاق‬\n      ‫الضــرر بهــم ســيما وأن هــذا اجلــرم يف معنــى اجلرائــم الكبيــرة الــواردة يف‬\n      ‫قــرار ســمو وزيــر الداخليــة رقــم (‪ )1900‬وتاريــخ ‪1428/7/9‬ه ـ واملبلــغ‬\n      ‫بالتعميــم رقــم (‪/13‬ت‪ )3187/‬وتاريــخ ‪1428/8/5‬ه ـ لذلــك كلــه فقــد‬\n      ‫حكمــت بســجن كل واحــد مــن املدعــى عليهمــا مــدة ســنتني اعتبــارا‬\n      ‫مــن تاريــخ القبــض عليهمــا وإيقافهمــا علــى ذمــة هــذه القضيــة يف‬\n      ‫‪1433/8/13‬ه ـ وجلــد كل واحــد منهمــا ثالثمائــة جلــدة علــى دفعــات‬\n\n\n‫‪229‬‬\n\f‫كل دفعــة خمــس وســبعون جلــدة وبــن كل دفعــة والتــي تليهــا شــهر‬\n‫هــذا مــا ثبــت لــدي وبــه حكمــت وبعرضــه علــى أطــراف القضيــة قــرر‬\n‫املدعــي العــام معارضتــه وطلــب رفعــه حملكمــة االســتئناف دون الئحــة‬\n‫فأجبتــه لذلــك وقــرر املدعــى عليهمــا القناعــة بــه وقــد جــرى النطــق بــه يف‬\n‫متــام الســاعة الواحــدة والنصــف وبــاهلل التوفيــق وصلــى اهلل وســلم علــى‬\n             ‫نبينا محمد وآله وصحبه أجمعني حرر يف ‪1433/11/17‬هـ‬\n‫احلمــد هلل وحــده وبعــد فقــد اطلعنــا نحــن قضــاة الدائــرة األولــى‬\n‫لتدقيــق القضايــا اجلزائيــة مبحكمــة االســتئناف مبنطقــة عســير علــى‬\n‫املعاملــة الــواردة مــن فضيلــة رئيــس احملكمــة اجلزائيــة بجــازان برقــم‬\n‫‪ 331795904‬وتاريــخ ‪1433/12/28‬ه ـ املرفــق بهــا القــرار الصــادر‬\n‫مــن فضيل ــة القاضــي باحملكمــة الشــيخ‪...../‬برقم ‪ 33462509‬وتاريــخ‬\n‫‪1433/11/22‬ه ـ اخلــاص بدعــوى املدعــي العــام ضــد كل مــن ‪..... /‬‬\n‫( ســعودي اجلنســية) و ‪(.....‬مينــي اجلنســية) يف قضيــة (قــات) علــى الصفــة‬\n‫املوضحــة يف القــرار املتضمــن حكــم فضيلتــه مبــا هــو مــدون ومفصــل‬\n‫فيــه وبدراســة القــرار وصــورة ضبطــه وأوراق املعاملــة تقــررت املوافقــة‬\n‫علــى احلكــم ‪ .‬واهلل املوفــق وصلــى اهلل علــى نبينــا محمــد وآلــه وصحبــه‬\n                                                                           ‫وســلم ‪.‬‬\n\n\n\n\n                                                                                      ‫‪230‬‬\n\f","legal_articles":[],"source_id":"831db040-0b05-5921-907d-640530e541d8","source_file_id":"396a5809-4e7b-56b3-9eb0-4f45acc6dbb7","source_page_start":222,"source_page_end":230,"original_source":"وزارة العدل السعودية","acquisition_source":"official_ministry_download_preserved_in_central_archive","source_url":null,"content_hash":"1896a6ab1704cd3c538785dfcea5343f7a79929f868a33057f50faa75cd8f3ff","normalized_text_hash":"0955462786bd606e9fb951e7ddc473f429c8f56a830032e0f0da6a9f0f773aa6","status":"review","review_status":"manual_field_review_pending","legal_search_eligibility":false,"legacy_id":"collector-1434-v18-p222-33462509"},{"id":"1d6fabbb-f360-5c4e-bb23-6088e7f3d5ee","document_type":"judgment","category":"judicial","subcategory":"general","title":"مخدرات -ترويج احلبوب احملظورة « حبوب الكبتاجون » -تخفيف العقوبة لقلة الكمية ولكون املدعى عليه ليس من أرباب السوابق من جنس التهمة -صرف النظر عن طلب املدعي العام إلزام املدعى عليه رد املبلغ احلكومي -صرف النظر عن طلب املدعي العام تعزير املدعى عليه لقاء تستره على مصدر املخدرات -التعزير بالسجن واجللد والغرامة واملنع من السفر ومصادرة اجلوال وإلغاء","document_number":"33483133","case_number":"33606469","judgment_number":null,"decision_number":null,"circular_number":null,"court":"محكمة الاستئناف","circuit":null,"issuing_authority":"وزارة العدل السعودية","document_date":null,"hijri_date":"1433/12/29","year":"1434","subject":"مخدرات -ترويج احلبوب احملظورة « حبوب الكبتاجون » -تخفيف العقوبة لقلة الكمية ولكون املدعى عليه ليس من أرباب السوابق من جنس التهمة -صرف النظر عن طلب املدعي العام إلزام املدعى عليه رد املبلغ احلكومي -صرف النظر عن طلب املدعي العام تعزير املدعى عليه لقاء تستره على مصدر املخدرات -التعزير بالسجن واجللد والغرامة واملنع من السفر ومصادرة اجلوال وإلغاء","summary":null,"facts":null,"claims":null,"reasoning":null,"ruling":null,"principle_text":null,"full_text":"      ‫رقم الصك‪ 33483133:‬تاريخه ‪1433/12/29:‬هـ‬\n                         ‫رقم الدعوى‪33606469:‬‬\n                   ‫رقم قرار التصديق من محكمة‬\n        ‫االستئناف‪ 3428454:‬تاريخه‪1434/02/03:‬هـ‬\n\n\n      ‫مخــدرات ‪ -‬ترويــج احلبــوب احملظــورة « حبــوب الكبتاجــون » ‪ -‬تخفيــف‬\n      ‫العقوبــة لقلــة الكميــة ولكــون املدعــى عليــه ليــس مــن أربــاب الســوابق‬\n      ‫مــن جنــس التهمــة ‪ -‬صــرف النظــر عــن طلــب املدعــي العــام إلــزام‬\n      ‫املدعــى عليــه رد املبلــغ احلكومــي ‪ -‬صــرف النظــر عــن طلــب املدعــي‬\n      ‫العــام تعزيــر املدعــى عليــه لقــاء تســتره علــى مصدر املخــدرات ‪ -‬التعزير‬\n      ‫بالســجن واجللــد والغرامــة واملنــع مــن الســفر ومصــادرة اجلــوال وإلغــاء‬\n                                                                         ‫الشــريحة ‪.‬‬\n\n\n\n\n                  ‫‪ -‬املادة (‪ )38‬من نظام مكافحة املخدرات واملؤثرات العقلية ‪.‬‬\n                   ‫‪ -‬املادة (‪ )53‬من نظام مكافحة املخدرات واملؤثرات العقلية‪.‬‬\n                   ‫‪ -‬املادة (‪ )56‬من نظام مكافحة املخدرات واملؤثرات العقلية‪.‬‬\n                   ‫‪ -‬املادة (‪ )60‬من نظام مكافحة املخدرات واملؤثرات العقلية‪.‬‬\n\n\n\n\n      ‫ادعــى املدعــي العــام علــى املدعــى عليــه بترويــج احلبــوب احملظــورة‬\n      ‫عــن طريــق البيــع ‪ ،‬انتهــى التحقيــق إلــى توجيــه االتهــام إلــى املدعــى‬\n      ‫عليــه بترويــج حبــوب الكبتاجــون عــن طريــق البيــع مرتــن ‪ ،‬األولــى‬\n      ‫لعــدد ( ‪ ) 5‬خمــس حبــات ‪ ،‬والثانيــة لعــدد (‪ ) 1.50‬حبــة ونصــف ‪،‬‬\n\n‫‪231‬‬\n\f‫وتســتره علــى مصــدره يف احلصــول علــى املخــدرات ‪ ،‬وطلــب املدعــي‬\n‫العــام تعزيــر املدعــى عليــه بالســجن واجللــد والغرامــة واملنــع مــن الســفر‬\n‫ومصــادرة اجلــوال وإلغــاء الشــريحة ورد املبلــغ احلكومــي ‪ ،‬وتعزيــره لقــاء‬\n‫تســتره علــى مصــدر املخــدرات ‪ ،‬أنكــر املدعــي عليــه مــا جــاء بدعــوى‬\n‫املدعــي العــام‪ ،‬بطلــب البينــة مــن املدعــي العــام علــى دعــواه أحضــر‬\n‫للشــهادة معــدي محضــر القبــض فشــهدا بصحــة الواقعــة ‪ ،‬وأنهمــا‬\n‫اشــتريا مــن املدعــى عليــه حبــوب محظــورة‪ ،‬وســبق أن عــدل الشــاهدان‬\n‫ســابقاً‪ ،‬صــدر احلكــم بتعزيــر املدعــى عليــه بالســجن واجللــد والغرامــة‬\n‫واملصــادرة وإلغــاء الشــريحة واملنــع مــن الســفر ملــدة ثــاث ســنوات بعــد‬\n‫إنهــاء محكوميتــه ‪ ،‬ومت النــزول عــن احلــد األدنــى للعقوبــة ‪ ،‬لكــون‬\n‫املدعــى عليــه ليــس مــن أربــاب الســوابق مــن جنــس هــذه التهمــة ‪ ،‬ولقلــة‬\n‫الكميــة املروجــة‪ ،‬صــدر احلكــم بصــرف النظــر عــن طلــب املدعــي‬\n‫العــام تعزيــر املدعــى عليــه لقــاء تســتره علــى مصــدر املخــدرات لتعاونــه‬\n‫مــع جهــة الضبــط‪ ،‬وصــرف النظــر عــن طلــب املدعــي العــام إعــادة املبلــغ‬\n‫احلكومــي ‪ ،‬لعــدم ثبــوت دعــوى الترويــج األولــى‪ ،‬قــرر املدعــى عليــه‬\n‫واملدعــى العــام اعتراضهمــا علــى احلكــم‪ ،‬صــدق احلكــم مــن محكمــة‬\n                                                                    ‫االســتئناف‪.‬‬\n\n\n\n‫احلمد هلل وحده وبعد فلدي أنا مساعد رئيس احملكمة اجلزائية مبكة‬\n‫املكرمــة وبنــاء علــى املعاملــة احملالــة لنــا مــن فضيلــة رئيــس احملكمــة‬\n‫اجلزائيــة مبكــة املكرمــة برقــم ‪ 33606469‬وتاريــخ ‪1433/10/16‬ه ـ‬\n‫املقيــدة باحملكمــة برقــم ‪ 331823849‬وتاريــخ ‪1433/10/16‬ه ـ ففــي‬\n\n                                                                                     ‫‪232‬‬\n\f      ‫يــوم االثنــن املوافــق ‪1433/11/01‬ه ـ افتتحــت اجللســة الســاعة ‪10 : 45‬‬\n      ‫وفيهــا حضــر املدعــي العــام املكلــف بالترافــع لدينــا يف قضايــا احلــق‬\n      ‫العــام مبوجــب خطــاب رئيــس دائــرة االدعــاء العــام مبكــة املكرمــة‬\n      ‫رقــم م‪/2/1‬د‪ 125/‬يف ‪1431/5/14‬ه ـ وأدعــى علــى احلاضــر معــه ‪........‬‬\n      ‫ا يف دعــواه عليــه‬   ‫ســعودي اجلنســية بالســجل املدنــي رقــم (‪ )......‬قائ ـ ً‬\n      ‫أنــه بتاريــخ ‪1433/9/16‬ه ـ مت القبــض علــى املدعــى عليــه وقــد أنتهــى‬\n      ‫التحقيــق إلــى توجيــه االتهــام للمدعــى عليــه بترويــج حبــوب الكبتاجــون‬\n      ‫عــن طريــق البيــع مرتــن األولــى لعــدد (‪ )5‬خمــس حبــات والثانيــة لعــدد‬\n      ‫(‪ )1.50‬حبــه ونصــف احلبــه احملتويــة علــى مــادة الالمفتيامــن وتســتره‬\n      ‫علــى مصــدره يف احلصــول علــى احلبــوب احملظــورة وبالبحــث عــن ســوابقه‬\n      ‫عثــر لــه علــى ســابقة ســرقة حيوانــات لــذا أطلــب إثبــات إدانتــه مبــا أســند‬\n      ‫إليــه واحلكــم عليــه بالســجن واجللــد والغرامــة ومنعــه مــن الســفر خلــارج‬\n      ‫البــاد مبوجــب املادتــن (‪ )38‬و(‪ )56‬مــن نظــام مكافحــة املخــدرات‬\n      ‫واحلكــم مبصــادرة الهاتــف اجلــوال مبوجــب املــادة (‪ )53‬مــن ذات النظــام‬\n      ‫والنــص يف القــرار الشــرعي علــى إدخــال قيمــة اجلــوال مبؤسســة النقــد‬\n      ‫العربــي الســعودي حلســاب املديريــة العامــة ملكافحــة املخــدرات وإلغــاء‬\n      ‫الشــريحة وطلــب إلزامــه بــرد املبلــغ املالــي وقــدره (‪ )200‬مئتــا ريــال‬\n      ‫املســتخدم يف عملية الشــراء العائد إلدارة مكافحة املخدرات واحلكم‬\n      ‫عليــه بعقوبــة تعزيريــة لقــاء تســتره علــى مصــدره يف احلصــول علــى‬\n      ‫احلبــوب احملظــورة وبســؤال املدعــى عليــه قــال مــا أدعــاه املدعــي العــام يف‬\n      ‫دعــواه غيــر صحيــح وبطلــب البينــة مــن املدعــي العــام قــال أطلــب إمهالــي‬\n      ‫ورفعــت اجللســة ليــوم الثالثــاء ه ـ الســاعة التاســعة والنصــف صباحـ ًا يف‬\n      ‫يــوم الثالثــاء املوافق‪1433/11/09‬ه ـ افتتحــت اجللســة الســاعة ‪45:11‬‬\n\n\n‫‪233‬‬\n\f‫وفيهــا حضــر الطرفــان وجــرى ســؤال املدعــي العــام عــن بينتــه فقــال لــم‬\n‫حتضــر وأطلــب إمهالــي للتنســيق مــع إدارة مكافحــة املخــدرات يف مــدة‬\n‫ال تتجــاوز أســبوع نظــر ًا الختــاف ورديــات الفرقــة القابضــة وســوف يتــم‬\n‫اشــعاركم باملوعــد احملــدد مــع الفرقــة بعــد التنســيق ورفعــت اجللســة يف‬\n‫يــوم الســبت املوافــق‪ 1433/11/20‬ه ـ افتتحــت اجللســة الســاعة ‪11:45‬‬\n‫وفيهــا حضــر الطرفــان وأحضــر املدعــي العــام معــه بالســجل املدنــي رقــم‬\n‫ا أكنــت‬    ‫(‪ )......‬بالســجل املدنــي رقــم (‪ ).......‬وباستشــهادهما شــهد قائـ ً‬\n‫واقف ـ ًا عنــد البنــك ‪ ....‬أصــرف مــن الصرافــة فطلــب منــي املدعــى عليــه‬\n‫أن أوصلــه إلــى بيتــه فوافقــت وركــب معــي فقلــت لــه أال تعلــم لــي أحــد ًا‬\n‫يبيــع احلبــوب فقــال أنــا آتــي لــك بهــا وســلمت مائتــي ريــال فذهــب وألتقــى‬\n‫باملــروج وســلمني خمــس حبــات ثــم أنزلتــه عنــد بيتــه ثــم أجريــت اتصــا ًال‬\n‫بــه للشــراء مــرة أخــرى وقــال الشــاهد ركبــت مــع الشــاهد والتقينــا‬\n‫باملدعــى عليــه وقــال الشــاهدان قمــت أنــا بتســليم املدعــى عليــه خمســن‬\n‫ريــا ًال وســلمني أنــا والشــاهد يــرى ذلــك وقــام بتســليمي حبــة ونصــف فتــم‬\n‫القبــض عليــه واملبلــغ املرقــم يف حوزتــه هــذا مــا لدينــا مــن شــهادة وبعرض‬\n‫حــال الشــاهدين ومــا جــاء يف شــهادتهما علــى املدعــى عليــه قــال أمــا‬\n‫حالهمــا فــا أعلــم عنهمــا شــيئ ًا وأمــا مــا جــاء يف شــهادتهما فشــهادتهما‬\n‫غيــر صحيحــة هكــذا أجــاب والشــاهدان ســبق تزكيتهمــا فســألت‬\n‫املدعــي العــام هــل لديــك زيــادة بينــة فقــال ليــس لــدي ســوى مــن أحضــرت‬\n‫ومــا جــاء يف أوراق املعاملــة ورفعــت اجللســة لالطــاع علــى املعاملــة ويف‬\n‫يــوم االربعــاء ‪1433/11/24‬ه ـ افتتحــت اجللســة الســاعة (‪)10:15‬‬\n‫وفيهــا حضــر الطرفــان وقــد جــرى االطــاع علــى التقريــر الكيميائــي‬\n‫الشــرعي رقــم (‪/26308‬س‪1433/2‬هــ) فوجدتــه يتضمــن إيجابيــة املادة‬\n\n\n                                                                                       ‫‪234‬‬\n\f      ‫املضبوطــة للحبــوب احملظــورة فســألت املدعــي العــام هــل لديــك زيــادة‬\n      ‫بينــة علــى واقعــة الترويــج األولــى التــي بــاع فيهــا املدعــى عليــه خمــس‬\n      ‫حبــات فقــال ليــس لــدي ســوى مــن أحضــرت فســألت املدعــى عليــه هــل‬\n      ‫أرشــد الفرقــة القابضــة علــى مصــدر احلبــوب فقــال نعــم مت القبــض عليــه‬\n      ‫وبعــرض ذلــك علــى املدعــي العــام قــال أطلــب إمهالــي لســؤال املكافحــة‬\n      ‫عــن صحــة ذلــك ورفعــت اجللســة ويف يــوم االربعــاء ‪1433/12/29‬ه ـ‬\n      ‫افتتحــت اجللســة الســاعة (‪ )11:45‬وفيهــا حضــر الطرفــان وقــد وردنــا‬\n      ‫مــن مديــر مكافحــة املخــدرات بالعاصمــة املقدســة خطابــه رقــم‬\n      ‫‪3991/1/2/4/15‬س يف ‪1433/12/9‬هـ وتضمن أن املتهم‪ /‬مت ســؤاله‬\n      ‫مــن أيــن يحصــل علــى احلبــوب احملظــورة فأجــاب بأنــه يحصــل عليهــا مــن‬\n      ‫شــخص يدعــى‪ /‬ومت القبــض عليــه الحق ـ ًا عــن طريــق أحــد مصادرنــا‬\n      ‫الســرية وســجلت القضيــة برقــم (‪ )33/1297‬وبعــرض ذلــك علــى املدعي‬\n      ‫ـاء علــى مــا‬\n                  ‫العــام قــال ليــس لــدي ســوى مــا ورد يف أوراق املعاملــة وبنـ ً‬\n      ‫تقــدم مــن الدعــوى واإلجابــة وشــهادة الشــاهدين أعــاه فقــد ثبــت لــدي‬\n      ‫قيــام املدعــى عليــه بترويــج حبــة ونصــف احلبــة مــن حبــوب الالمفيتامــن‬\n      ‫عــن طريــق البيــع ووجهــت لــه تهمــة ترويــج خمــس حبــات مــن ذات النــوع‬\n      ‫عــن طريــق البيــع وحيــث أن املدعــى عليــه ليــس مــن أربــاب الســوابق مــن‬\n      ‫ـاء علــى املــادة (‪)60‬‬\n                           ‫جنــس هــذه التهمــة ومــا قــام بترويجــه شــيء يســير وبنـ ً‬\n      ‫مــن نظــام مكافحــة املخــدرات فقــد قــررت النــزول عــن احلــد األدنــى مــن‬\n      ‫العقوبــة املنصــوص عليهــا يف املــادة (‪ )38‬مــن ذات النظــام وحكمــت‬\n      ‫بســجنه ثــاث ســنوات حتســب منهــا فتــرة إيقافــه الســابقة وجلــده‬\n      ‫وتغرميــه مبوجــب املــادة (‪ )38‬مــن نفــس النظــام وذلــك بجلــده ثالثمائــة‬\n      ‫جلــده مفرقــه علــى ســت دفعــات متســاوية يفصــل بينهــا عشــرة أيــام‬\n\n\n‫‪235‬‬\n\f‫وتغرميــه ثالثــة آالف ريــال كمــا حكمــت مبوجــب املــادة (‪ )53‬مــن ذات‬\n‫النظــام وذلــك مبصــادرة الهاتــف اجلــوال املذكور رقمــه يف الئحة املدعي‬\n‫العــام وإدخــال قيمتــه مبؤسســة النقــد العربــي الســعودي حلســاب املديريــة‬\n‫العامــة ملكافحــة املخــدرات كمــا حكمــت بإلغــاء شــريحة هــذا اجلــوال‬\n‫وعــدم صرفهــا للمدعــى عليــه وحيــث أن املدعــى عليــه تعــاون مــع جهــة‬\n‫الضبــط وأرشــدهم إلــى مصــدر احلبــوب ومت القبــض علــى املــروج فلــم‬\n‫يثبــت لــدي تســتره علــى مصــدر احلبــوب وحكمــت بصــرف النظــر عــن‬\n‫طلــب املدعــي العــام إلــزام املدعــى عليــه بــرد املبلــغ احلكومــي وقــدره‬\n‫(‪ )....‬مائتــا ريــال لعــدم ثبــوت دعــوى الترويــج االولــى وأفهمــت املدعــى‬\n‫عليــه بــأن املــادة (‪ )56‬مــن ذات النظــام تســتوجب منعــه مــن الســفر مــدة‬\n‫ثــاث ســنوات وبعــرض احلكــم علــى الطرفــن قــرر املدعــى عليــه عــدم‬\n‫قناعتــه باحلكــم وطلــب محكمــة االســتئناف بــدون الئحــة كمــا قــرر‬\n‫املدعــي العــام االعتــراض بالئحــة وأبلغتــه بــأن مــدة االعتــراض ثالثــون‬\n‫يوم ـ ًا مــن تاريــخ صــدور القــرار يــوم االربعــاء ‪1433/12/29‬ه ـ وبــاهلل‬\n‫التوفيــق ‪ ،‬وصلــى اهلل علــى نبينــا محمــد وعلــى آلــه وصحبــه وســلم‪ .‬حــرر‬\n                                                        ‫يف ‪1433/12/29‬ه ـ‬\n‫احلمــد هلل وحــده والصــاة والســام علــى مــن ال نبــي بعــده وبعــد‪ ،‬نحــن‬\n‫قضاة الدائرة اجلزائية السادسة مبحكمة االستئناف مبكة املكرمة‬\n‫جــرى منــا االطــاع علــى املعاملــة الــواردة إلــى هــذه احملكمــة بكتــاب‬\n‫فضيلــة الرئيــس املســاعد باحملكمــة اجلزائيــة مبكــة املكرمة الشــيخ‪/‬‬\n‫رقــم(‪ )331823849‬وتاريخ(‪1434/1/21‬هــ) املرفــق بهــا القرار الصادر‬\n‫مــن فضيلتــه برقم(‪)33483133‬وتاريخ(‪1433/12/29‬هـ)‪،‬املتضمــن‬\n‫دعــوى املدعــي العــام ضــد‪ 44/‬عامــا ســعودي اجلنســية ‪ ،‬املتهــم يف‬\n\n\n                                                                                  ‫‪236‬‬\n\f      ‫مخــدرات ‪ ،‬احملكــوم فيــه مبــا دون باطنــه ‪ ،‬وبدراســة القــرار وصــورة‬\n      ‫ضبطــه والئحتــه االعتراضيــة تقــررت املوافقــة علــى احلكــم ‪ ،‬واهلل‬\n            ‫املوفــق‪ ،‬وصلــى اهلل علــى نبينــا محمــد وعلــى آلــه وصحبــه وســلم‪.‬‬\n\n\n\n\n‫‪237‬‬\n\f","legal_articles":[],"source_id":"831db040-0b05-5921-907d-640530e541d8","source_file_id":"396a5809-4e7b-56b3-9eb0-4f45acc6dbb7","source_page_start":231,"source_page_end":237,"original_source":"وزارة العدل السعودية","acquisition_source":"official_ministry_download_preserved_in_central_archive","source_url":null,"content_hash":"ae24d6306c204b1ff3cd3c2e34762747780b60cfd17ec9c5a06002955c5a119e","normalized_text_hash":"a72e338486bd311e5de718fa900967f662a203b544cf6e35e881408f369565e9","status":"review","review_status":"manual_field_review_pending","legal_search_eligibility":false,"legacy_id":"collector-1434-v18-p231-33483133"},{"id":"593af908-bb48-5d18-8fb2-5a3eb7013f22","document_type":"judgment","category":"judicial","subcategory":"general","title":"مخدرات -ترويج احلبوب احملظورة -تعاطي احلبوب احملظورة -حيازة احلبوب احملظورة بقصد التعاطي -إقرار املدعى عليه -التعزير بالسجن واجللد والغرامة واملنع من السفر -مصادرة الهاتف اجلوال.","document_number":"33448152","case_number":"33606482","judgment_number":null,"decision_number":null,"circular_number":null,"court":"محكمة الاستئناف","circuit":null,"issuing_authority":"وزارة العدل السعودية","document_date":null,"hijri_date":"1433/11/08","year":"1434","subject":"مخدرات -ترويج احلبوب احملظورة -تعاطي احلبوب احملظورة -حيازة احلبوب احملظورة بقصد التعاطي -إقرار املدعى عليه -التعزير بالسجن واجللد والغرامة واملنع من السفر -مصادرة الهاتف اجلوال.","summary":null,"facts":null,"claims":null,"reasoning":null,"ruling":null,"principle_text":null,"full_text":"‫رقم الصك‪ 33448152:‬تاريخه ‪1433/11/08:‬هـ‬\n                  ‫رقم الدعوى ‪33606482:‬‬\n    ‫رقم قرار التصديق من محكمة االستئناف‪:‬‬\n           ‫‪ 3416074‬تاريخه‪1434/01/19:‬هـ‬\n\n\n‫مخــدرات ‪ -‬ترويــج احلبــوب احملظــورة ‪ -‬تعاطــي احلبــوب احملظــورة‬\n‫‪ -‬حيــازة احلبــوب احملظــورة بقصــد التعاطــي ‪ -‬إقــرار املدعــى عليــه‬\n‫‪ -‬التعزيــر بالســجن واجللــد والغرامــة واملنــع مــن الســفر ‪ -‬مصــادرة‬\n                                                      ‫الهاتــف اجلــوال‪.‬‬\n\n\n\n             ‫‪ -‬املادة (‪ )38‬من نظام مكافحة املخدرات واملؤثرات العقلية‪.‬‬\n             ‫‪ -‬املادة (‪ )56‬من نظام مكافحة املخدرات واملؤثرات العقلية‪.‬‬\n             ‫‪ -‬املادة (‪ )53‬من نظام مكافحة املخدرات واملؤثرات العقلية‪.‬‬\n             ‫‪ -‬املادة (‪ )60‬من نظام مكافحة املخدرات واملؤثرات العقلية‪.‬‬\n\n\n\n‫ادعــى املدعــي العــام على املدعي عليه بترويــج احلبوب احملظورة‪،‬وحيازة‬\n‫حبــة مــن حبــوب اإلمفيتامــن احملظــورة ‪ ،‬وتعاطيــه ملثلهــا‪ ،‬حيــث وردت‬\n‫معلومــات ســرية تفيــد بــأن هنــاك شــخص يقــوم بالتوســط يف ترويــج‬\n‫احلبــوب احملظــورة ‪ ،‬واســتعد املصــدر للشــراء منــه ‪ ،‬ومت تزويــده باملبلــغ‬\n‫املرقــم ‪ ،‬ومت تفتيشــه قبــل نزولــه ‪ ،‬وملــا تقابــل مــع املدعــى عليــه ‪،‬‬\n‫ســلم املصــدر املبلــغ للمدعــى عليــه ‪ ،‬وكان ذلــك حتــت أنظــار الفرقــة‬\n‫القابضــة ‪ ،‬ثــم حتــركا مــن املوقــع إلــى مــكان آخــر‪ ،‬وبعــد وقــت يســير‬\n\n\n                                                                                  ‫‪238‬‬\n\f      ‫مت القبــض علــى املدعــى عليــه ‪ ،‬وقــام املصــدر بتســليم رقيــب الفرقــة‬\n      ‫حبتــن مــن احلبــوب احملظــورة ‪ ،‬وبتفتيــش املدعــى عليــه وجــد بحوزتــه‬\n      ‫حبــة واحــدة مــن حبــوب الكبتاجــون ‪ ،‬وجهــاز جــوال ‪ ،‬وهــو الــذي مــن‬\n      ‫خاللــه مت التنســيق معــه‪ ،‬وطلــب املدعــي العــام تعزيــر املدعــى عليــه‬\n      ‫بالســجن واجللــد والغرامــة واملنــع مــن الســفر واملصــادرة‪ ،‬أقــر املدعــى‬\n      ‫عليــه مبــا جــاء بدعــوى املدعــي عليــه‪ ،‬صــدر احلكــم بتعزيــر املدعــى‬\n      ‫عليــه بالســجن واجللــد واملنــع مــن الســفر والغرامــة واملصــادرة وإعــادة‬\n      ‫املبلــغ احلكومــي وتعزيــره لقــاء اســتعماله للحبــوب احملظــورة‪ ،‬قنــع‬\n      ‫املدعــى عليــه باحلكــم ‪ ،‬وقــرر املدعــي العــام اعتراضــه علــى احلكــم‬\n                           ‫بالئحــة‪ ،‬صــدق احلكــم مــن محكمــة االســتئناف‪.‬‬\n\n\n\n      ‫احلمــد هلل وحــده وبعــد فلــدي أنــا القاضــي يف احملكمــة اجلزائيــة مبكــة‬\n      ‫املكرمــة وبنــاء علــى املعاملــة احملالــة لنــا مــن فضيلــة رئيــس احملكمــة‬\n      ‫اجلزائيــة مبكــة املكرمــة برقم (‪ ).....‬وتاريخ (‪).....‬ه ـ املقيدة باحملكمة‬\n      ‫برقــم (‪ ).....‬وتاريــخ (‪).....‬ه ـ ففــي يــوم اإلثنــن املوافق‪1433/11/08‬ه ـ‬\n      ‫افتتحــت اجللســة الســاعة ‪ 11 : 30‬وفيهــا حضــر املدعــي العــام مبوجــب‬\n      ‫خطــاب التكليــف مــن مرجعــه رقــم يف ه ـ وادعــى علــى احلاضــر معــه‬\n      ‫ســعودي اجلنســية مبوجــب الســجل املدنــي رقــم (‪ ).....‬قائــا بدعــواه أنــه‬\n      ‫يف يــوم اخلميــس (‪).....‬ه ـ وردت معلومــات ســريه تفيــد وجــود شــخص‬\n      ‫(املدعــى عليــه) يقــوم بالتوســط يف ترويــج احلبــوب احملظــورة بشــارع‬\n      ‫واســتعد املصــدر بالشــراء املباشــر منــه ومت متكينــه مــن االتصــال علــى‬\n      ‫هاتفــه رقــم (‪ ).....‬وطلــب منــه كميــة مــن احلبــوب احملظــورة مببلغ (‪)100‬‬\n\n‫‪239‬‬\n\f‫مائــة ريــال واســتعد املدعــى عليــه بذلــك وطلــب مــن املصــدر احلضــور إليــه‬\n‫بحــي ويف متــام الســاعة احلاديــة عشــر والنصــف مســاء مت تزويــد املصــدر‬\n‫باملبلــغ املرقــم بعــد تفتيشــه ودفعــه حتــت أنظــار الفرقــة وتقابــا ســوي ًا‬\n‫ومــن ثــم ركــب املدعــى عليــه مــع املصــدر وطلــب منــه االجتــاه إلــى حــي‬\n‫ودخــا إلــى احلــي وبعــد حوالــي خمــس دقائــق خرجــا مــن احلــي وعلــى‬\n‫الفــور مت القبــض علــى املدعــى عليــه وقــام املصــدر بتســليم رقيــب‬\n‫الفرقــة عــدد حبتــن مــن حبــوب الكبتاجــون احملظــورة وأفــاد بأنــه قــام‬\n‫بتســليم املبلــغ املرقــم للمدعــى عليــه وأن املدعــى عليــه نــزل واختفــاء عــن‬\n‫األنظــار ثــم عــاد وقــام بتســليم الكميــة املتفــق عليهــا وبتفتيــش املدعــى‬\n‫عليــه شــخصي ًا عثــر بداخــل جيبــه علــى عــدد حبــه واحــدة مــن حبــوب‬\n‫الكبتاجــون احملظــورة وعثــر علــى جــوال مــن نــوع (‪ ).....‬يحمــل الرقــم‬\n‫املصنعــي (‪ ).....‬وهــو نفــس اجلــوال الــذي مت التنســيق عليــه وقــد أثبــت‬\n‫التقريــر الكيميائــي الشــرعي (‪ 2259‬س‪1433 2‬هــ) أن قرصان بيضاء‬\n‫اللــون يحمــان العالمــة املعتــادة لعقــار الكبتاجــون ثبــت أنهمــا يحتويــان‬\n‫علــى مــادة االمفيتامــن وأن قــرص واحــد أبيــض اللــون يحمــل العالمــة‬\n‫املعتــادة لعقــار الكبتاجــون (املضبــوط بحــوزة املدعــى عليــه) ثبــت أنــه‬\n‫يحتــوي علــى مــادة االمفيتامــن وهــو مــن املــواد املدرجــة بجــدول املــواد‬\n‫املخــدرة واملؤثــرات العقليــة وباســتجواب املدعــى عليــه‪ /‬أقــر ببيــع عــدد‬\n‫حبتــن مــن حبــوب الكبتاجــون احملظــورة مببلــغ مائــة ريــال وحيــازة حبــة‬\n‫واحــدة مــن حبــوب الكبتاجــون احملظــورة بقصــد التعاطــي وأن آخــر‬\n‫مــرة تعاطــى بهــا احلبــوب احملظــورة قبــل القبــض عليــه بيومــن كونــه‬\n‫يتعاطــى احلبــوب احملظــورة منــذ خمــس ســنوات تقريب ـ ًا وكمــا اعتــرف‬\n‫بــأن رقــم هاتفــه الــوارد يف واقعــة الضبــط هــو الــذي مت التنســيق عليــه‬\n\n\n                                                                                      ‫‪240‬‬\n\f      ‫وقــد انتهــى التحقيــق إلــى توجيــه االتهــام ل ـ بترويــج عــدد حبتــن مــن‬\n      ‫حبــوب الكبتاجــون احملتويــة علــى مــادة االمفيتامــن عــن طريــق البيــع‬\n      ‫وحيــازة عــدد حبــة واحــدة مــن حبــوب الكبتاجــون احملتويــة علــى مــادة‬\n      ‫االمفيتامــن بقصــد التعاطــي وتعاطيــه الســابق للحبــوب احملظــورة‬\n      ‫احملرمــة شــرع ًا املجرمــة نظام ـ ًا وذلــك لألدلــة والقرائــن املوضحــة‬\n      ‫بالدعــوى وحيــث إن مــا قــام بــه املدعــى عليــه وهــو بكامــل أهليتــه‬\n      ‫املعتبــرة شــرع ًا فعــل محــرم ومجــرم ومعاقــب عليــه شــرع ًا ونظامـ ًا اطلــب‬\n      ‫احلكــم عليــه وفق ـ ًا للمــادة رقــم مــن ‪ 38‬و‪ 56‬و‪ 53‬مــن نظــام مكافحــة‬\n      ‫املخــدرات هــذه دعــواي وبســؤال املدعــى عليــه قــال مــا ذكــره املدعــي‬\n      ‫العــام صحيــح حيــث اتصــل بــي املصــدر وطلــب التوســط يف شــراء‬\n      ‫احلبــوب علــى هاتفــي املذكــور فذهبــت معــه للمــروج وأخــذت مائــة ريــال‬\n      ‫وســلمتها للمــروج واســتلمت منــه ثــاث حبــات كبتاجــون وأعطيتهــا‬\n      ‫للمصــدر الــذي أهدانــي منهــا حبــة واحــدة ألتعاطاهــا ألننــي أتعاطــى مــن‬\n      ‫نــوع هــذه احلبــوب منــذ فتــرة وبعــد ذلــك قبــض علــي واعترفــت بــكل‬\n      ‫شــيئ ودللــت علــى املــروج وأنــا مجــرد وســيط ودالل فقــط وهــذه أول مــرة‬\n      ‫وآخــر مــرة وأتعهــد بالتوبــة هــذه إجابتــي ثــم جــرى االطــاع علــى التقريــر‬\n      ‫الكيميائــي املرفــق لفــة ‪ 19‬فوجدتــه يتضمــن احتــواء املضبوطــات‬\n      ‫علــى األمفيتامــن احملظــور كمــا لــم أجــد للمدعــى عليــه ســوابق فبنــاء‬\n      ‫علــى مــا تقــدم مــن الدعــوى واإلجابــة وإلــى إقــرار املدعــى عليــه بدعــوى‬\n      ‫املدعــي العــام وبنــاء علــى املــواد ‪ 38‬و‪ 56‬و‪ 53‬و ‪ 60‬مــن نظــام مكافحــة‬\n      ‫املخــدرات ولعــدم وجــود ســوابق ومبــادرة املدعــى عليــه باالعتــراف‬\n      ‫وتعهــده بالتوبــة لــذا فقــد ثبــت لــدي إدانــة املدعــى عليــه مبــا أســند إليــه‬\n      ‫مــن ترويــج حبتــن مــن حبــوب األمفيتامــن احملظــورة عــن طريــق البيــع‬\n\n\n‫‪241‬‬\n\f‫وحيــازة حبــة واحــدة مماثلــة لقصــد التعاطــي وتعاطيــه الســابق لنوعهــا‬\n‫وحكمــت مبجازاتــه علــى جميــع ذلــك بالســجن مــدة ثــاث ســنوات‬\n‫ابتــداء مــن تاريــخ التوقيــف وجلــده مائتــن وأربعــن جلــدة مفرقــة علــى‬\n‫ســت دفعــات كل دفعــة أربعــون جلــدة بــن كل دفعــة وأخــرى شــهر‬\n‫وغرامــة ماليــة قدرهــا ألــف ريــال ومنعــه مــن الســفر إلــى خــارج اململكــة‬\n‫مــدة ثــاث ســنوات ومصــادرة الهاتــف اجلوال املذكــور وإدخال قيمته يف‬\n‫مؤسســة النقــد بحســاب إدارة مكافحــة املخــدرات ومصــادرة الشــريحة‬\n‫املذكــورة وعــدم صرفهــا للمدعــى عليــه كمــا حكمــت بإلــزام املدعــى‬\n‫عليــه بإعــادة املبلــغ احلكومــي وقــدره مائــة ريــال ‪ .‬وبعــرض احلكــم علــى‬\n‫املدعــى عليــه قنــع بــه وقــد عــارض املدعــي العــام وطلــب االســتئناف‬\n‫بالئحــة فأجيــب لطلبــه وبــاهلل التوفيــق وصلــى اهلل وســلم علــى نبينــا‬\n               ‫محمــد وآلــه وصحبــه أجمعــن ‪ .‬حــرر يف ‪1433/11/ 8‬ه ـ‬\n‫احلمــد هلل وحــده وبعــد ثــم عــادت املعاملــة مــن محكمــة االســتئناف‬\n‫وبرفقهــا القــرار رقــم وتاريــخ ‪ 1433 / 12 / 21‬ه ـ املتضمــن املالحظــة‬\n‫بــأن فضيلتــه لــم يذكــر اســم املدعــي العــام وال بــد مــن ذلــك ألنــه ركــن‬\n‫مــن أركان الدعــوى إلجــراء مــا يلــزم واهلل املوفــق أ‪.‬هــ‪ .‬واجلــواب عمــا‬\n‫ذكــره أصحــاب الفضيلــة أنــه جــرى إصــاح اخلطــأ يف موضعــه وذكــر‬\n‫اســم املدعــي العــام وبــاهلل التوفيــق وصلــى اهلل وســلم علــى نبينــا محمــد‬\n                                 ‫وآلــه وصحبــه ‪ .‬حــرر يف ‪1434/01/05‬ه ـ ‪.‬‬\n‫ثــم عــادت املعاملــة مــن محكمــة االســتئناف وبرفقهــا القــرار رقــم‬\n‫وتاريــخ ‪1434/01/19‬ه ـ املتضمــن املوافقــة والتصديــق علــى احلكــم‬\n‫قاضي اســتئناف (‪ ).....‬وقاضي اســتئناف (‪ ).....‬وقاضي اســتئناف (‪).....‬‬\n‫احلمــد هلل وحــده والصــاة والســام علــى مــن ال نبــي بعــده ‪،‬وبعــد ‪ -:‬فقد‬\n\n\n                                                                                     ‫‪242‬‬\n\f      ‫جــرى منــا نحــن قضــاة الدائــرة اجلزائيــة األولــى يف محكمــة االســتئناف‬\n      ‫مبنطقــة مكــة املكرمــة اإلطــاع علــى املعاملــة الــواردة الينــا مــن‬\n      ‫فضيلــة رئيــس احملكمــة اجلزائيــة مبكــة املكرمــة برقــم وتاريــخ‬\n      ‫‪1434/1/11‬هـ املرفق بها القرار الشــرعي رقم و تاريخ ‪1433/11/8‬ه‬\n      ‫الصــادر مــن فضيلــة الشــيخ‪ ).....( /‬القاضــي يف احملكمــة اجلزائيــة‬\n      ‫مبكــة املكرمــة ‪ ،‬املتضمــن دعــوى املدعــي العــام ضــد‪ ).....( /‬املتهــم‬\n      ‫بقضيــة مخــدرات احملكــوم فيــه مبــا دون باطنــه‪ .‬وبدراســة احلكــم‬\n      ‫وصــورة ضبطــه والالئحــة االعتراضيــة قررنــا املوافقــة علــى احلكــم بعــد‬\n      ‫اإلجــراء األخيــر واهلل املوفــق ‪ ،‬وصلــى اهلل علــى نبينــا محمــد وعلــى آلــه‬\n                                                                    ‫وصحبــه وســلم ‪.‬‬\n\n\n\n\n‫‪243‬‬\n\f","legal_articles":[],"source_id":"831db040-0b05-5921-907d-640530e541d8","source_file_id":"396a5809-4e7b-56b3-9eb0-4f45acc6dbb7","source_page_start":238,"source_page_end":243,"original_source":"وزارة العدل السعودية","acquisition_source":"official_ministry_download_preserved_in_central_archive","source_url":null,"content_hash":"16411e7bf2de069c253fdf49a9ac5270651a7db36df8f124f24f4bf0014cd6db","normalized_text_hash":"b1858b25ae25e951da042b5bdbe1265575cca75c512c402eff222d073ed9b409","status":"review","review_status":"manual_field_review_pending","legal_search_eligibility":false,"legacy_id":"collector-1434-v18-p238-33448152"},{"id":"eb31a1fb-b1a5-5205-a5c8-f4f1690e2837","document_type":"judgment","category":"judicial","subcategory":"general","title":"مخدرات -حيازة احلشيش املخدر -تعاطي احلشيش املخدر واحلبوب احملظورة -ترويج احلبوب احملظورة -إقرار املدعى عليه -إنكار املدعى عليه وادعاء اإلكراه -شهادة الشهود -تخفيف العقوبة لقلة الكمية ولعدم وجود سوابق -التعزير بالسجن واجللد واإلبعاد عن الباد واملنع من السفر وتغرميه مبلغ مالي ومصادرة اجلوال.","document_number":"33475878","case_number":"33608605","judgment_number":null,"decision_number":null,"circular_number":null,"court":"محكمة الاستئناف","circuit":null,"issuing_authority":"وزارة العدل السعودية","document_date":null,"hijri_date":"1433/03/22","year":"1434","subject":"مخدرات -حيازة احلشيش املخدر -تعاطي احلشيش املخدر واحلبوب احملظورة -ترويج احلبوب احملظورة -إقرار املدعى عليه -إنكار املدعى عليه وادعاء اإلكراه -شهادة الشهود -تخفيف العقوبة لقلة الكمية ولعدم وجود سوابق -التعزير بالسجن واجللد واإلبعاد عن الباد واملنع من السفر وتغرميه مبلغ مالي ومصادرة اجلوال.","summary":null,"facts":null,"claims":null,"reasoning":null,"ruling":null,"principle_text":null,"full_text":"‫رقم الصك‪ 33475878 :‬تاريخه ‪1433/03/22 :‬هـ‬\n                   ‫رقم الدعوى ‪33608605 :‬‬\n     ‫رقم قرار التصديق من محكمة االستئناف‪:‬‬\n           ‫‪ 34246513‬تاريخه‪1434/06/20:‬هـ‬\n\n\n ‫مخــدرات ‪ -‬حيــازة احلشــيش املخــدر ‪ -‬تعاطــي احلشــيش املخــدر‬\n ‫واحلبــوب احملظــورة ‪ -‬ترويــج احلبــوب احملظــورة ‪ -‬إقــرار املدعــى عليــه‬\n ‫‪ -‬إنــكار املدعــى عليــه وادعــاء اإلكــراه ‪ -‬شــهادة الشــهود ‪ -‬تخفيــف‬\n ‫العقوبــة لقلــة الكميــة ولعــدم وجــود ســوابق ‪ -‬التعزيــر بالســجن‬\n ‫واجللــد واإلبعــاد عــن البــاد واملنــع مــن الســفر وتغرميــه مبلــغ مالــي‬\n                                                         ‫ومصــادرة اجلــوال‪.‬‬\n\n\n\n\n           ‫‪ .1‬املادة (‪ )38‬من نظام مكافحة املخدرات و املؤثرات العقلية ‪.‬‬\n           ‫‪ .2‬املادة (‪ )41‬من نظام مكافحة املخدرات و املؤثرات العقلية ‪.‬‬\n           ‫‪ .3‬املادة (‪ )56‬من نظام مكافحة املخدرات و املؤثرات العقلية ‪.‬‬\n           ‫‪ .4‬املادة (‪ )60‬من نظام مكافحة املخدرات و املؤثرات العقلية ‪.‬‬\n\n\n\n ‫ادعــى املدعــي العــام علــى األول بترويــج احلبــوب احملظــورة عــن طريــق‬\n ‫البيع و تعاطي األول احلبوب احملظورة و الثاني بترويج احلبوب احملظورة‬\n ‫عــن طريــق االســتالم و التســليم و حيــازة حبــه مــن حبــوب اإلمفيتامــن‬\n ‫احملظــورة بقصــد الترويــج ‪ ،‬وردت معلومــات عــن قيــام املدعــى عليــه‬\n ‫الثانــي بالتوســط يف ترويــج احلبــوب احملظــورة ‪ ،‬وقــد مت متكني املصدر‬\n\n                                                                                  ‫‪244‬‬\n\f      ‫مــن االتصــال بــه‪ ،‬وطلــب كميــة مــن احلبوب‪،‬مببلــغ مائتــي ريال‪،‬فوافــق‬\n      ‫الوســيط‪ ،‬فتــم تكليــف أحــد األفــراد مــن إدارة مكافحــة املخــدرات‬\n      ‫مــع املصــدر ‪ ،‬ملشــاهدة عمليــة االســتالم والتســليم‪،‬وركب املصــدر‬\n      ‫مــع الفــرد‪ ،‬وملــا تقابــا مــع الوســيط املدعــى عليــه ‪،‬ســلم الفــرد املبلــغ‬\n      ‫للوســيط ‪ ،‬وطلــب منهمــا االنتقــال حلــي آخــر الســتالم احلبــوب ‪ ،‬فتــم‬\n      ‫االنتقــال إلــى احلــي اآلخــر ‪ ،‬وركبــوا يف الســيارة جميعـ ًا الفــرد واملصــدر‬\n      ‫والوســيط‪ ،‬وملــا وصلــوا املــكان املتفــق عليــه ‪ ،‬نــزل الوســيط إلحضــار‬\n      ‫الكميــة ‪ ،‬وغــاب عــن األنظــار ‪ ،‬وعــاد ومعــه املدعــى عليــه األول ‪ ،‬وقــام‬\n      ‫املدعــى عليــه األول بتســليم املدعــى عليــه الثانــي شــيء مــا‪ ،‬حتــت أنظــار‬\n      ‫الفرقــة القابضــة ‪ ،‬وســلم املدعــى عليــه الثاني الوســيط احلبوب وعددها‬\n      ‫خمــس حبــات يشــتبه أن تكــون مــن احلبــوب احملظــورة للمصــدر‪ ،‬أمــام‬\n      ‫أنظــار الفرقــة القابضــة ‪ ،‬فتــم القبــض عليهمــا ‪ ،‬وبتفتيــش املدعــى عليــه‬\n      ‫الثانــي وجــد معــه بجيــب ثوبــه األميــن الســفلي علــى حبــة واحــدة يشــتبه‬\n      ‫أن تكــون مــن احلبــوب احملظــورة ‪ ،‬وضبــط معــه علــى اجلــوال الــذي‬\n      ‫مــن خاللــه مت التنســيق ‪ ،‬و طلــب املدعــي العــام تعزيــر املدعــى عليهمــا‬\n      ‫بالســجن واجللــد والغرامــة واإلبعــاد عــن البــاد لــأول واملنــع مــن الســفر‬\n      ‫للثانــي ومصــادرة اجلوالــن وإلغــاء شــريحتيهما ورد املبلــغ احلكومــي ‪،‬‬\n      ‫أنكــر املدعــى عليــه األول مــا جــاء بدعــوى املدعــي العــام و أقــر املدعــى‬\n      ‫عليــه الثانــي مبــا جــاء بدعــوى املدعــي العــام ‪ ،‬بطلــب البينــة مــن املدعــي‬\n      ‫العــام علــى دعــواه ضــد املدعــى عليــه األول أحضــر الشــاهدين وشــهد‬\n      ‫بإقــرار األول بالتوســط يف ترويــج احلبــوب احملظــورة ‪ ،‬صــدر احلكــم‬\n      ‫علــى املدعــى عليهمــا بالتعزيــر و الســجن و اجللــد و الغرامــة و مصــادرة‬\n      ‫الهاتفــن احملمولــن للمدعــى عليهمــا و إدخــال قيمتهمــا يف مؤسســة‬\n\n\n‫‪245‬‬\n\f‫النقــد وإلغــاء الشــريحتني و إلزامهمــا بإعــادة املبلــغ احلكومــي و إبعــاد‬\n‫األول إلــى خــارج اململكــة وال يســمح بالعــودة إليهــا إال فيمــا تســمح‬\n‫تعليمــات احلــج و العمــرة ‪ ،‬و منــع الثانــي مــن الســفر خــارج اململكــة‬\n‫مــدة ســنتني بعــد انتهــاء محكوميتــه ‪ ،‬لقــاء إدانــة املدعــى عليهمــا‬\n‫بالترويــج ‪ ،‬األول عــن طريــق البيــع ‪ ،‬والثانــي عــن طريــق التوســط ‪،‬‬\n‫باالســتالم والتســليم‪ ،‬وحيــازة املدعــى عليــه الثانــي علــى حبــة مــن حبــوب‬\n‫اإلمفيتامــن احملظــورة بقصــد التعاطــي ‪ ،‬مت النــزول عــن احلــد األدنــى‬\n‫للعقوبــة بحــق املدعــى عليهمــا لعــدم وجــود ســوابق بحقهمــا ‪ ،‬ومبــادرة‬\n‫الثانــي باالعتــراف ‪ ،‬ولظروفــه األســرية‪ ،‬قنــع املدعــى عليهمــا باحلكــم‬\n‫‪ ،‬وقــرر املدعــي العــام اعتراضــه علــى احلكــم الئحــة اعتراضيــة ‪ ،‬صدق‬\n                                           ‫احلكــم مــن محكمــة االســتئناف‪.‬‬\n\n\n\n\n‫احلمــد هلل وحــده وبعــد فلــدي أنــا ‪ ....‬القاضــي يف احملكمــة اجلزائيــة‬\n‫بتبــوك وبنــاء علــى املعاملــة احملالــة لنــا مــن فضيلــة رئيــس احملكمــة‬\n‫اجلزائيــة بتبوك‪/‬املســاعد برقــم ‪ .....‬وتاريــخ ‪1433/11/14‬ه ـ املقيــدة‬\n‫باحملكمــة برقــم ‪ .....‬وتاريــخ ‪1433/10/17‬ه ـ ففــي يــوم االثنــن‬\n‫املوافق‪1433/11/22‬ه ـ افتتحــت اجللســة وفيها حضر املدعي العام ‪......‬‬\n‫واملعمــد مــن مرجعــه مبوجــب اخلطــاب رقــم ‪ 13058‬يف ‪1433/09/05‬ه ـ‬\n‫وحضــر حلضــوره ‪ ....‬ســجله املدنــي رقــم ‪ ....‬العمــر ‪ 22‬عاطــل عــن العمــل‬\n‫وبالرجــوع للمعاملــة وجــد أنهــا مشــتملة علــى الئحــة دعــوى عامــة ضــد ‪...‬‬\n‫املذكــور تتضمــن أنــه ورد مبحضــر الشــراء والقبــض والتفتيــش املعــد‬\n‫مــن قبــل إدارة مكافحــة املخــدرات بتبــوك أنــه بتاريــخ ‪1433/08/28‬ه ـ‬\n\n                                                                                    ‫‪246‬‬\n\f      ‫توفــرت معلومــات لديهــم مــن أحــد املصــادر الســرية بأنــه يوجــد شــخص‬\n      ‫يدعــى ‪ ...‬يســكن بحــي املنتــزه يقــوم بترويــج احلبــوب احملظــورة وأنــه‬\n      ‫يقــوم بالتنســيق علــى جوالــه رقــم (‪ )....‬يف عمليــة الترويــج وأنــه مســتعد‬\n      ‫بالشــراء منــه أمــام الفرقــة القابضــة وبالفعــل مت االتصــال علــى املــروج‬\n      ‫أمــام مســمع الفرقــة القابضــة وطلــب منــه املصــدر كميــة مــن احلبــوب‬\n      ‫مببلــغ(‪ )100‬مائــة ريــال فذكــر لــه املــروج بأنــه موجــود بحــي ‪ .....‬وأن‬\n      ‫األغــراض موجــودة فأفــاد املصــدر بأنــه قــادم إليــه ســير ًا علــى األقــدام‬\n      ‫وأنــه قريــب مــن محطــة (‪ ).....‬وعليــه انتهــت املكاملــة وعنــد وصــول‬\n      ‫املصــدر إلــى احملطــة مت تفتيــش املصــدر وترقيــم املبلــغ احلكومــي وقــام‬\n      ‫املصــدر باالتصــال علــى املــروج وذكــر لــه بأنــه متواجــد يف محطــة‬\n      ‫فذكــر لــه املــروج بأنــه قــادم إليــه ســير ًا علــى األقــدام عندهــا مت توزيــع‬\n      ‫املهــام واملراقبــة مــن قبــل الفرقــة القابضــة وعنــد ذلــك مت مشــاهدة‬\n      ‫املــروج وهــو قــادم إلــى املصــدر خلــف احملطــة وقــام مبقابلتــه وبعــد‬\n      ‫مغــادرة املــروج للموقــع بعــد مشــاهدة عمليــة االســتالم والتســليم مــن‬\n      ‫قبــل الفرقــة أعطيــت اإلشــارة املتفــق عليهــا بالقبــض علــى املــروج ومت‬\n      ‫القبــض عليــه وبتفتيشــه شــخصي ًا اتضــح أنــه املدعــى عليــه املذكــور‬\n      ‫وبتفتيشــه مت العثــور علــى املبلــغ احلكومــي املرقــم وقــدره (‪ )100‬مائــة‬\n      ‫ريــال ومت العثــور علــى عــدد(‪ )1‬ســيجارة واحــدة ملفوفــة يشــتبه بــأن‬\n      ‫تكــون مخلوطــة باحلشــيش املخــدر بلــغ وزنهــا (‪950‬ملجــم) تســعمائة‬\n      ‫وخمســون مليجــرام يف اجليــب العلــوي ومت العثــور علــى اجلــوال الــذي مت‬\n      ‫التنســيق معــه يف عمليــة البيــع يف جيــب ثوبــه األيســر هــذا وقــد ســلم‬\n      ‫املصــدر الكميــة املشــتراة للفرقــة وهــي عــدد (‪ )4‬أربــع حبــات يشــتبه‬\n      ‫أن تكــون مــن احلبــوب احملظــورة وقــد مت إيقــاف املدعــى عليــه اســتناد ًا‬\n\n\n‫‪247‬‬\n\f‫للقــرار الــوزاري رقــم(‪ )1900‬املبنــي علــى املــادة رقــم (‪ )112‬مــن نظــام‬\n                                                             ‫اإلجــراءات اجلزائيــة‬\n‫وقــد ورد التقريــر الكيميائــي الشــرعي رقــم (‪ 2395‬م‪/‬م س ت)‬\n‫لعام‪1433‬ه ـ الصــادر مــن مركــز مراقبــة الســموم والكيميــاء الطبيــة‬\n‫الشــرعية بصحــة ‪ ...‬ايجابيــة احلبــوب املروجــة لإلمفيتامــن املنبــه للجهــاز‬\n‫العصبــي واملتضمــن أيض ـ ًا إثبــات إيجابيــة مســتخلص عينــة الســيجارة‬\n‫املضبوطــة التــي ال يعلوهــا أثــار حــرق للحشــيش وهــو مــن املــواد املخــدرة‬\n‫وملــا أشــير إليــه أقــرر توجيــه االتهــام للمدعــى عليــه ‪ ....‬بترويــج عــدد(‪)4‬‬\n‫أربــع حبــات مــن حبــوب االمفيتامــن املنبــه للجهــاز العصبــي احملظــورة‬\n‫عــن طريــق البيــع وتعاطيــه لنوعهــا يف الســابق وبحيــازة عدد (‪ )1‬ســيجارة‬\n‫واحــدة مــن احلشــيش املخــدر بلــغ وزنها(‪950‬ملجــم) تســعمائة وخمســون‬\n‫مليجــرام بقصــد التعاطــي وتعاطيه من ذات الكمية وتعاطيه للحشــيش‬\n‫املخــدر يف الســابق وحيــث أن مــا أقــدم عليــه املدعــى عليــه املذكــور‬\n‫فعــل محــرم شــرعا ومجــرم ومعاقــب عليــه نظامــا واســتنادا للمــادة الثالثة‬\n‫الفقــرة الثالثــة فقــرة (‪ )2‬مــن نظــام مكافحــة املخــدرات رقــم ‪/39‬م يف‬\n‫‪1426/7/8‬ه ـ ممــا يتعــن معــه إحالتــه للمحكمــة اجلزئيــة اســتناد ًا‬\n‫للمادتــن (‪)126‬و(‪ )128‬مــن نظــام اإلجــراءات اجلزائيــة لطلــب مــا يلــي‪-:‬‬\n‫‪-1‬إثبــات مــا أســند إليــه ‪ -2‬احلكــم عليــه بالســجن واجللــد والغرامــة‬\n‫لقــاء مــا أســند إليــه اســتنادا للفقــرة األولــى مــن املــادة الثامنــة والثالثــن‬\n‫مــن نظــام مكافحــة املخــدرات واملؤثــرات العقليــة وإعمــا ًال مبقتضــى‬\n‫املــادة (‪ )62‬الفقــرة (‪ )1‬لتطبيــق العقوبــة األشــد مــن نظــام املشــار إليــه‬\n‫أعــاه ‪ -3‬تشــديد العقوبــة عليــه لقــاء ترويجــه للحبــوب احملظــورة التــي‬\n‫حتتــوي علــى مــادة اإلمفيتامــن املنبــه احملظــور اســتناد ًا لتعميــم صاحــب‬\n\n\n                                                                                           ‫‪248‬‬\n\f      ‫الســمو امللكــي وزيــر الداخليــة رقــم ‪ 2529/4/5/1‬وتاريــخ‬\n      ‫‪1427/02/08‬ه ـ ‪ -4‬احلكــم مبنعــه مــن الســفر خرج اململكة اســتنادا‬\n      ‫للفقــرة األولــى مــن املــادة السادســة واخلمســن مــن نظــام مكافحــة‬\n      ‫املخــدرات واملؤثــرات العقليــة املشــار إليــه ‪ -5‬احلكــم مبــا صــادرة جــوال‬\n      ‫املدعــى عليــه املضبــوط يف عمليــة التنســيق للترويــج نــوع نوكيــا يحمــل‬\n      ‫الرقــم ‪ ....‬اســتنادا للمــادة الثالثــة واخلمســن الفقــرة األولــى مــن نظــام‬\n      ‫مكافحــة املخــدرات واملؤثــرات العقليــة املشــار إليــه اعــاه ‪ -6‬احلكــم‬\n      ‫بإلغــاء شــريحة الهاتــف رقــم (‪ )....‬اســتنادا لتعميــم صاحــب الســمو‬\n      ‫امللكــي نائــب رئيــس مجلــس الــوزراء وزيــر الداخليــة رقــم‬\n      ‫(‪9798/4/5/1‬س د) يف ‪ 1428/2/10‬ه ـ هكــذا ادعــى وبســؤال‬\n      ‫املدعــى عليــه عــن الدعــوى أجــاب بقولــه صحيــح أنــه مت القبــض علــي مــن‬\n      ‫قبــل مكافحــة املخــدرات ومعــي صــاروخ حشــيش لغــرض االســتعمال‬\n      ‫والتعاطــي فأنــا أدخــن احلشــيش املخــدر منــذ فتــرة قريبــة ومــا ذكــره‬\n      ‫املدعــي العــام مــن أننــي قمــت ببيــع أربــع حبــات مبائــة ريــال فغيــر صحيــح‬\n      ‫واجلــوال املذكــور يف الدعــوى ليــس لــي وال أعــرف ملــن هكــذا أجــاب‬\n      ‫وبطلــب البينــة مــن املدعــي العــام قــال أطلــب مهلــة إلحضــار أفــراد الفرقة‬\n      ‫هكــذا قــرر ورفعــت اجللســة لذلــك ويف يــوم الثالثــاء‬\n      ‫املوافق‪1433/12/21‬ه ـ افتتحــت اجللســة وفيهــا حضــر املدعــي العــام‬\n      ‫واملدعــى عليــه وبطلــب البينــة مــن املدعــي العــام أحضــر للشــهادة و أدائها‬\n      ‫‪ ....‬ســعودي اجلنســية مبوجــب الســجل املدنــي رقــم ‪ ....‬وبســؤاله عمــا لديــه‬\n      ‫مــن شــهادة قــال أشــهد هلل بأننــي ســمعت املكاملــة التــي دارت بــن‬\n      ‫املصــدر واملــروج واتفقــا علــى شــراء حبــوب مبائــة ريــال و أن يتــم اللقــاء‬\n      ‫يف حــي ‪ ....‬خلــف محطــة ‪ ....‬وكان ذلــك يف متــام الســاعة العاشــرة مســاءا‬\n\n\n‫‪249‬‬\n\f‫تقريبــا وعندمــا حضرنــا للموقــع قمــت بتفتيــش املصــدر وأعطيتــه مائــة‬\n‫ريــال و أنزلتــه علــى الشــارع الرئيســي خلــف احملطــة فقابــل املصــدر‬\n‫املــروج وهــو هــذا احلاضــر ورأيتــه يســلمه شــيئا وأســتلم منــه املبلــغ‬\n‫فأعطيــت اإلشــارة ألعضــاء الفرقــة فتــم القبــض عليــه ووجــد معــه املبلــغ‬\n‫احلكومــي وســيجارة مخلوطــة باحلشــيش كمــا وجــدت مــع املصــدر‬\n‫أربــع حبــات وكان معــي يف الســيارة ‪ ...‬وقــد تــويف أثنــاء مداهمــة أحــد‬\n‫املروجــن هكــذا شــهد وبعــرض الشــاهد و مــا جــاء يف شــهادته علــى‬\n‫املدعــى عليــه قــال صحيــح أنــه مت القبــض علــي خلــف محطــة ‪ ...‬يف ‪...‬‬\n‫وكان بحوزتــي ســيجارة مخلوطــة باحلشــيش املخــدر ومــا ســوى ذلــك‬\n‫فغيــر صحيــح والشــاهد هــو مــن قــام بضربــي هكــذا أجــاب كمــا‬\n‫حضــر للشــهادة وأدائهــا ‪ ....‬ســعودي اجلنســية مبوجــب الســجل املدنــي‬\n‫رقــم ‪ .....‬وبســؤاله عمــا لديــه مــن شــهادة قــال أشــهد هلل بأننــي ســمعت‬\n‫املكاملــة التــي متــت بــن املصــدر واملــروج واالتفــاق علــى شــراء احلبــوب‬\n‫مببلــغ مائــة ريــال وبعدهــا اجتهنــا للموقــع املتفــق عليــه ونزلــت خلــف‬\n‫احملطــة علــى نفــس الشــارع و رأيــت املصــدر يقابــل املــروج وهــو هــذا‬\n‫احلاضــر ولكــن لــم أشــاهد عمليــة االســتالم والتســليم وبعدمــا أعطانــا‬\n‫قائــد الفرقــة اإلشــارة مت القبــض عليــه وبتفتيشــه وجــد يف جيبــه األيســر‬\n‫املبلــغ احلكومــي وقــدره مائــة ريــال كمــا وجــد يف جيبــه العلــوي علــى‬\n‫ســيجارة مخلوطــة باحلشــيش املخــدر هكــذا شــهد وبعــرض الشــاهد‬\n‫ومــا جــاء يف شــهادته علــى املدعــى عليــه قــال مــا جــاء يف شــهادته غيــر‬\n‫صحيــح ســوى حيــازة احلشــيش كمــا أن الشــاهد لــم يكــن موجــودا‬\n‫وقــت املداهمــة هكــذا أجــاب وبطلــب تزكيــة الشــاهدين حضــر كال‬\n‫مــن ‪ ....‬و‪ ...‬وشــهد كل واحــد منهمــا بقولــه أشــهد هلل بــأن الشــاهدين‬\n\n\n                                                                                   ‫‪250‬‬\n\f      ‫عــدالن ثقتــان وال نعلــم عنهمــا إال خيــرا هكــذا شــهدا وبتصفــح أوراق‬\n      ‫املعاملــة وجــدت علــى اللفــة رقــم (‪ )15،16‬حتقيقــا مــع املدعــى عليــه‬\n      ‫وعليــه توقيــع بالبصمــة منســوب إليــه وبــه إقــرار منــه ببيــع أربــع حبــات‬\n      ‫مبائــة ريــال وبعرضــه عليــه قــال صحيــح أننــي قمــت بالتبصيــم علــى هــذا‬\n      ‫احملضــر وبعــد تالوتــه علــي مــن قبــل احملقــق ولكــن كان ذلــك‬\n      ‫االعتــراف بســبب الضــرب وليــس لــدي بينــه علــى ذلــك هكــذا أجــاب ‪.‬‬\n      ‫فبنــاء علــى مــا تقــدم مــن الدعــوى واإلجابــة املتضمنــة مصادقــة املدعــى‬\n      ‫عليــه بتدخينــه للحشــيش وحيازتــه لســيجاره مخلوطــة باحلشــيش‬\n      ‫وإنــكاره ترويــج احلبــوب وبعــد االطــاع علــى التقريــر الكيمائــي املشــار‬\n      ‫إليــه و ملــا جــاء يف شــهادة الشــاهدين املعدلــن شــرعا وملــا جــاء يف إقــراره‬\n      ‫حتقيقــا ونظــرا لرجوعــه عنــه و ادعــاء اإلكــراه عليــه وليــس لديــه بينــه‬\n      ‫علــى ذلــك و ملــا قــرره ابــن قدامــه رحمــه اهلل يف املغنــي (‪ )389/10‬بقولــه‬\n      ‫(وال يقبــل رجــوع املقــر عــن إقــراره إال فيمــا كان حــدا هلل تعالــى يــدر‬\n      ‫بالشــبهات ويحتــاط إلســقاطه فأمــا حقــوق اآلدميــن وحقــوق اهلل تعالــى‬\n      ‫التــي ال تــدرأ بالشــبهات كالــزكاة والكفــارات فــا يقبــل رجوعــه‬\n      ‫عنهــا وال نعلــم يف هــذا خالفــا) أ‪.‬ه ـ وملــا جــاء يف الفقــرة األولــى مــن املــادة‬\n      ‫الثامنــة والثالثــن والفقــرة األولــى مــن املــادة السادســة واخلمســن مــن‬\n      ‫النظــام املشــار إليــه ونظــرا لقلــة الكميــة وعــدم وجــود ســوابق علــى‬\n      ‫املدعــى عليــه وملــا جــاء يف املــادة ســتني مــن النظــام املشــار إليــه والتــي‬\n      ‫جتيــز النــزول عــن احلــد األدنــى وملــا تســببه هــذه احلبــوب مــن فســاد للعقــل‬\n      ‫وإفســاد للبــاد والعبــاد وبنــاء علــى جميــع مــا تقــدم فقــد ثبــت لــدي إدانــة‬\n      ‫املدعــى عليــه بتدخينــه للحشــيش املخــدر وحيازتــه لســيجاره مخلوطــة‬\n      ‫باحلشــيش املخــدر بلــغ وزنهــا تســعمائة وخمســون ملجــم وترويجــه ألربــع‬\n\n\n‫‪251‬‬\n\f‫حبــات حتتــوي علــى مــادة االمفيتامــن وقــررت بحقــه مــا يلــي أوال جلــد‬\n‫املدعــى عليــه ثمانــن جلــدة حــد املســكر ثانيــا تعزيــر املدعــى عليــه‬\n‫بجلــده ثالثمائــة جلــدة مفرقــة علــى ســت دفعــات متســاوية بــن كل‬\n‫دفعــة والتــي تليهــا مــدة ال تقــل عــن عشــرة أيــام ثالثــا تعزيــر املدعــى عليــه‬\n‫بحبســه ملــدة ثــاث ســنوات اعتبــارا مــن تاريــخ توقيفــه علــى ذمــة القضيــة‬\n‫رابعــا تغــرمي املدعــى عليــه ألــف ريــال تــودع لصالــح اخلزينــة العامــة للدولــة‬\n‫خامســا مصــادرة جهــاز جوالــه والــذي يحمــل الرقــم (‪ )....‬من نــوع نوكيا‬\n‫وإيداعــه لصالــح اخلزينــة العامــة للدولــة سادســا إلغــاء شــريحة اجلــوال‬\n‫التــي حتمــل الرقــم (‪ )....‬ســابعا منــع املدعــى عليــه مــن الســفر خــارج‬\n‫اململكــة مــدة مماثلــه ملــدة ســجنه تبــدأ مــن تاريــخ انتهــاء محكوميتــه يف‬\n‫البنــد ثالثــا ومبــا ذكــر حكمــت فقــرر احملكــوم عليــه قناعتــه بــه ولــم‬\n‫يقنــع بــه املدعــي العــام وطلــب متييــزه مكتفيــا بالئحــة الدعــوى عــن‬\n‫الالئحــة االعتراضيــة فأجبتــه لطلبــه وســيتم بعــث كامــل أوراق املعاملــة‬\n‫حملكمــة االســتئناف لتدقيــق احلكــم حســب املتبــع وبــاهلل التوفيــق ‪،‬‬\n‫وصلــى اهلل علــى نبينــا محمــد وعلــى آلــه وصحبــه وســلم ‪ .‬حــرر يف‬\n‫‪ 1433/12/21‬احلمــد هلل وحــده وبعــد ففــي يــوم الســبت‬\n‫املوافــق‪ 1434/04/20‬ه ـ حضــر املدعــى عليــه وقــد أعيــدت املعاملــة‬\n‫بخطــاب رئيــس محكمــة االســتئناف املســاعد بتبــوك برقــم ‪ ....‬يف‬\n‫‪1434/04/07‬ه ـ وأحيلــت إلــي بخطــاب رئيــس احملكمــة اجلزئيــة رقــم‬\n‫‪ ....‬يف ‪1434/04/10‬ه ـ وقــد صــدر قــرار الدائــرة اجلزائيــة الثانيــة رقــم‬\n‫‪ .....‬يف ‪1434/04/02‬ه ـ املتضمــن حكــم فضيلتــه مبــا هــو مــدون‬\n‫ومفصــل فيــه وبدراســة القــرار وصــورة ضبطــه وأوراق املعاملــة لوحــظ‬\n‫مــا يلــي أوالً‪ :‬املدعــى عليــه ال يحمــل إثبــات هويتــه ســوى إثبــات مؤقــت‬\n\n\n                                                                                           ‫‪252‬‬\n\f      ‫علــى اللفــة (‪ )4‬وعليــه صورتــه مــع اخلتــم للجهــة املختصــة ولــم يشــر‬\n      ‫فضيلتــه لذلــك لدفــع اإليهــام بــأن مــا ذكــر مــن رقــم الســجل املدنــي‬\n      ‫حلملــه الهويــة الرســمية ثانيـاً‪ :‬ورد بالدعــوى اتهــام املدعــى عليــه بتعاطــي‬\n      ‫حبــوب االمفيتامــن احملظــورة ولــم يتضمــن احلكــم عقوبتــه علــى ذلــك‬\n      ‫كمــا لــم يتضمــن احلكــم أيضـ ًا الغــرض والقصــد مــن حيــازة ســيجارة‬\n      ‫احلشــيش مــع أنــه ذكــر بالدعــوى أنهــا بقصــد التعاطــي ثالث ـاً‪ :‬طلــب‬\n      ‫املدعــي العــام تشــديد العقوبــة لقــاء ترويــج املدعــى عليــه للحبــوب ولــم‬\n      ‫يجــر فضيلتــه شــيئ ًا حيــال ذلــك واحلكــم نــزل عــن احلــد األدنــى للعقوبــة‬\n      ‫دون التســبيب لذلــك رابع ـاً‪ :‬لــم يوضــح فضيلتــه مســتنده يف كــون‬\n      ‫الغرامــة وقيمــة مصــادرة اجلــوال تــودع لصالــح اخلزينــة العامــة للدولــة‬\n      ‫حســبما ورد يف احلكــم ويوجــد أخطــاء نحويــة وإمالئيــة معلــم عليهــا‬\n      ‫لتصحيحهــا مــع التنبيــه إلــى أنــه أشــير يف التســبيب إلــى عــدم وجــود‬\n      ‫ســوابق للمدعــى عليــه ولــم يشــر لصحيفــة ســوابقه ومضمونهــا طاملــا‬\n      ‫األمــر مــا ذكــر وأنــه حكــم باجللــد ثمانــن حــد املســكر ولــم يذكــر‬\n      ‫نــوع املســكر املقــام فيــه احلــد وإلــى أن أحــد الشــهود ذكــر أســمه ثالثيـ ًا‬\n      ‫فقــط ولــم يذكــر رباعي ـ ًا حســب هويتــه ولــم يشــر يف القــرار إلــى أن‬\n      ‫هويتــي املعدلــن مدونــة بضبطــه ملالحظــة ذلــك وإحلــاق مــا يجريــه علــى‬\n      ‫الضبــط والقــرار وصورتــه حســب التعليمــات واهلل املوفــق وبســؤال‬\n      ‫املدعــى عليــه هــل حتمــل إثبــات هويــة قــال ليــس لــدي إثبــات هويــة وإمنــا‬\n      ‫أنــا مضــاف مــع والــدي يف كــرت العائلــة هكــذا أجــاب وعليــه فــإن‬\n      ‫الســجل املدنــي املــدون أعــاه خــاص باملدعــى عليــه وفقـ ًا لإلنــاث املؤقــت‬\n      ‫املرفــق رقــم (‪ )4‬وأمــا مــا جــاء يف ثاني ـ ًا فقــد ثبــت لــدي إدانــة املدعــى‬\n      ‫عليــه بحيازتــه لســيجارة مخلوطــة باحلشــيش املخــدر بلــغ وزنهــا تســعمائة‬\n\n\n‫‪253‬‬\n\f‫وخمســن ملجــم لقصــد االســتعمال والتعاطي وأجاب أصحــاب الفضيلة‬\n‫بــأن عقابــه عــن اســتخدامه للحبــوب داخــل يف حــد املســكر وأمــا مــا‬\n‫جــاء يف ثالثـ ًا فقــد ذكــرت يف تســبيب احلكــم بــأن املدعــى عليــه ليــس‬\n‫لديــه ســوابق ولقلــة الكميــة التــي قــام ببيعهــا فهــذه األســباب التــي دعــت‬\n‫إلــى النــزول عــن احلــد األدنــى مــن العقوبــة وأمــا مــا جــاء يف رابع ـ ًا فــإن‬\n‫املســتند يف ذلــك هــو الفقــرة األولــى مــن املــادة الثالثــة واخلمســن مــن‬\n‫نظــام مكافحــة املخــدرات واملؤثــرات العقليــة وبــاهلل التوفيــق ‪ ،‬وصلــى‬\n‫اهلل علــى نبينــا محمــد وعلــى آلــه وصحبــه وســلم ‪ .‬حــرر يف‬\n                                                                   ‫‪1434/04/20‬هـ‬\n‫احلمــد هلل وحــده وبعــد فقــد اطلعن ــا نحن قـض ــاة الدائ ــرة اجلزائية الثانية‬\n‫يف محكمــة االســتئناف مبنطقــة تبــوك علــى املعاملــة الــواردة من فضيلة‬\n‫رئيــس احملكمــة اجلزائيــة بتبــوك برقــم ‪ .....‬وتاريخ‪1434/5/6‬ه ـ املرفــق‬\n‫بهــا القــرار الصــادر مــن فضيلــة القاضــي يف احملكمــة الشــيخ ‪ ....‬برقــم‬\n‫‪ ....‬وتاريــخ‪ 1433/12/22‬ه ـ اخلــاص بدعــوى املدعــي العــام ضــد املدعــى‬\n‫عليــه ‪ ......‬يف قضيــة مخــدرات واملتضمــن حكــم فضيلتــه مبــا هــو مــدون‬\n‫ومفصــل فيــه ‪ .‬وبدراســة القــرار وصــورة ضبطــه وأوراق املعاملــة ومــا‬\n‫أحلقــه فضيلتــه علــى قــرار الدائــرة رقــم ‪ .....‬وتاريــخ ‪1434/4/2‬ه ـ ‪،‬‬\n‫قررنــا املصادقــة علــى احلكــم بعــد اإلجــراء األخيــر ‪ .‬مــع تنبيــه فضيلتــه‬\n‫إلــى تصحيــح األخطــاء املطبعيــة املعلــم عليهــا بالقــرار ‪ .‬واهلل املوفــق‬\n                         ‫وصلــى اهلل علــى نبينــا محمــد وآلــه وصحبــه وســلم‪.‬‬\n\n\n\n\n                                                                                          ‫‪254‬‬\n\f","legal_articles":[],"source_id":"831db040-0b05-5921-907d-640530e541d8","source_file_id":"396a5809-4e7b-56b3-9eb0-4f45acc6dbb7","source_page_start":244,"source_page_end":254,"original_source":"وزارة العدل السعودية","acquisition_source":"official_ministry_download_preserved_in_central_archive","source_url":null,"content_hash":"8c4cf52d95145ac21e4f6e9e37cd946ccba91664e525ab78095845492c10fc1a","normalized_text_hash":"13a09591f2f9f00f4bba268c5546cfa0af9c8a4733a6f2f745c6a66e2ed330b5","status":"review","review_status":"manual_field_review_pending","legal_search_eligibility":false,"legacy_id":"collector-1434-v18-p244-33475878"}]$archive_payload$::jsonb) AS x LIMIT 25
       )) AS legal_documents,
       (SELECT count(*) FROM public.document_files WHERE document_id IN (
          SELECT (x->>'id')::uuid FROM jsonb_array_elements($archive_payload$[{"id":"d7dc568f-ce1c-5a1b-bfe5-739ccb6655e5","document_type":"judgment","category":"judicial","subcategory":"general","title":"مخدرات -ترويج الهيروين املخدر -تستر -شروع يف تسليم الهيروين املخدر -حيازة الهيروين املخدر -تعزير بالسجن واجللد ومصادرة اجلوال والشريحة املستخدمني يف اجلرمية -إبعاد .","document_number":"3433171","case_number":"33476048","judgment_number":null,"decision_number":null,"circular_number":null,"court":"محكمة الاستئناف","circuit":null,"issuing_authority":"وزارة العدل السعودية","document_date":null,"hijri_date":"1434/2/9","year":"1434","subject":"مخدرات -ترويج الهيروين املخدر -تستر -شروع يف تسليم الهيروين املخدر -حيازة الهيروين املخدر -تعزير بالسجن واجللد ومصادرة اجلوال والشريحة املستخدمني يف اجلرمية -إبعاد .","summary":null,"facts":null,"claims":null,"reasoning":null,"ruling":null,"principle_text":null,"full_text":"  ‫رقم الصك‪ 3433171:‬تاريخه‪1434/2/9 :‬هـ‬\n                  ‫رقم الدعوى‪33476048 :‬‬\n   ‫رقم قرار التصديق من محكمة االستئناف‪:‬‬\n          ‫‪ 34221172‬تاريخه‪1434/5/25 :‬هـ‬\n\n\n‫مخدرات ‪ -‬ترويج الهيروين املخدر‪ -‬تســتر‪ -‬شــروع يف تســليم الهيروين‬\n‫املخــدر‪ -‬حيــازة الهيرويــن املخــدر‪ -‬تعزيــر بالســجن واجللــد ومصــادرة‬\n                ‫اجلــوال والشــريحة املســتخدمني يف اجلرميــة ‪ -‬إبعــاد ‪.‬‬\n\n\n\n     ‫ال يف تهمة رواه أبو داود ‪.‬‬\n                             ‫‪ -1‬حبس النبي صلى اهلل عليه وسلم رج ً‬\n‫‪ -2‬املــواد (‪ )38‬و (‪ )56‬و (‪ )53‬مــن نظــام مكافحــة املخــدرات واملؤثــرات‬\n                                                              ‫العقليــة‪.‬‬\n\n\n\n‫ادعــى املدعــي العــام ضــد املدعــى عليــه بتســليم وحيــازة الهيرويــن لغرض‬\n‫الترويــج والشــروع يف ترويــج الهيرويــن وطلــب املدعــي العــام إثبــات مــا‬\n‫أســند إليــه واحلكــم عليــه بالســجن واجللــد والغرامــة املاليــة وإبعــاده عــن‬\n‫البــاد بعــد انتهــاء عقوبــة الســجن وعــدم الســماح لــه بالعــودة مــرة أخــرى‬\n‫ومصــادرة املبلــغ املضبــوط بحــوزة املدعــى عليــه ومصــادرة اجلوالــن‬\n‫املضبوطــن وإلغــاء شــريحتيهما كونهمــا مســتخدمتان يف اجلرميــة وعــدم‬\n‫صــرف الشــريحتني لنفــس املشــترك‪ ،‬حيــث أنــه مت القبــض علــى املدعــى‬\n‫ـاء علــى إخباريــة مــن أحــد املصــادر الســرية عــن وجــود شــخص‬    ‫عليــه بنـ ً‬\n‫وافــد يقــوم بترويــج كبســوالت الهيرويــن املخــدر ويعاونــه شــخص آخــر‬\n\n\n                                                                                      ‫‪208‬‬\n\f      ‫عــن طريــق متريــر بطاقــات شــحن اجلــوال حيث يقــوم املــروج بالتفاوض مع‬\n      ‫املشــتري للمــادة املخــدرة ويقــوم بأخــذ بطاقــات الشــحن مســبقة الدفــع‬\n      ‫عوض ـ ًا عــن النقــد ثــم يقــوم بعــد ذلــك بإرســال أحــد معاونيــه ليرمــي‬\n      ‫الهيرويــن املخــدر للمتعاطــي واتضــح أن املعــاون هــو املدعــى عليــه‪ ،‬أقــر‬\n      ‫املدعــى عليــه بالتســليم والشــروع يف التســليم وأنكــر علمــه أن احلبــوب‬\n      ‫( الكبســوالت ) هــي الهيرويــن املخــدر‪ ،‬ثبتــت إدانــة املدعــى عليــه‬\n      ‫‪ ،‬بنــاء علــى مــا تقــدم حكمــت احملكمــة بتعزيــره بالســجن واجللــد‬\n      ‫والغرامــة واألبعــاد ومصــادرة اجلــوال والشــريحة ‪ ،‬قنــع املدعــى عليــه‬\n      ‫وصــدق احلكــم‬ ‫باحلكــم وقــرر املدعــي العــام االعتــراض بغيــر الئحــة ُ‬\n                                                       ‫مــن محكمــة االســتئناف‪.‬‬\n\n\n\n      ‫احلمــد هلل وحــده وبعــد فلــدي أنــا ‪ ........‬القاضــي يف احملكمــة اجلزائيــة‬\n      ‫بالريــاض وبنــاء علــى املعاملــة احملالــة لنــا مــن فضيلــة رئيــس احملكمــة‬\n      ‫اجلزائيــة بالريــاض برقــم ‪ ......‬وتاريــخ ‪ .....‬ه ـ املقيــدة باحملكمــة برقــم‬\n      ‫‪ .....‬وتاريــخ ‪ ........‬ه ـ ففــي يــوم الثالثــاء املوافــق‪ ......‬ه ـ افتتحــت اجللســة‬\n      ‫الســاعة الثامنــة وفيهــا قــدم املدعــي العــام ‪ .........‬الئحــة دعــوى عامــة‬\n      ‫ضــد ‪ ....... /‬يحمــل رخصــة إقامــة رقــم ( ‪ )......‬باكســتاني اجلنســية‬\n      ‫جــاء فيهــا بتاريــخ ‪.......‬ه ـ قبــض علــى املذكــور مــن قبــل إحــدى فــرق‬\n      ‫شــعبة املكافحــة و البحــث و التحــري بــإدارة مكافحــة املخــدرات‬\n      ‫الســرية عــن وجــود‬ ‫مبنطقــة الريــاض بنــاء إلخباريــة مــن أحــد املصــادر ّ‬\n      ‫شــخص باكســتاني يدعــى‪ .....‬يتواجــد علــى اجلــوال رقــم ( ‪ ) .......‬يقــوم‬\n      ‫بترويــج كبســوالت الهيرويــن املخــدر و يعاونــه شــخص يدعــى ‪ ....‬وهــو‬\n\n‫‪209‬‬\n\f‫املذكــور عــن طريــق متريــر بطاقــات شــحن اجلــوال مســبقة الدفــع حيــث‬\n‫يقــوم املــروج (‪ )....‬التفــاوض مــع املشــتري للمــادة املخــدرة هاتفيـ ًا و يقــوم‬\n‫بأخــذ بطاقــات شــحن اجلــوال مســبوقة الدفــع عوضـ ًا عــن النقــد ثــم يقــوم‬\n‫بعــد ذلــك بإرســال أحــد أعوانــه ليرمــي الهيرويــن املخــدر للمتعاطــي و‬\n‫اتضــح لــدى فرقــة القبــض أن املذكــور يعــاون املــروج (‪ )...‬و ذلــك برمــي‬\n‫الهيرويــن املخــدر يف أماكــن محــددة بطلــب مــن املــروج ‪ ....‬واتضــح أن‬\n‫املذكــور ليــس لــه مــكان محــدد و ليــس لــه ســكن وهــو يتواجــد دائمــا‬\n‫بحــي الشميســي حيــث يفتــرش احلدائــق العامــة و ينــام بهــا و قــد أســفرت‬\n‫إجــراءات التحقيــق عــن اتهــام ‪ ............ /‬بتســلم (‪ )26‬ســت و عشــرون‬\n‫كبســولة إال ربــع الكبســولة بهــا الهرويــن املخدر تــزن جميعا ( ‪)197.5‬‬\n‫مائــة و ســبعة و تســعون جرامـ ًا و خمســة أعشــار اجلــرام بقصــد االجتــار‬\n‫و الترويــج و الشــروع يف تســليم كبســولة إال ربــع تــزن (‪ )5.5‬خمســة‬\n‫جرامــات و خمســة أعشــار اجلــرام مــن ذات الكميــة لقصــد الترويــج و‬\n‫الســابق املجــرم مبوجــب املــادة ( الثالثــة )‬   ‫ترويجــه الهيرويــن املخــدر يف ّ‬\n‫مــن نظــام مكافحــة املخــدرات و املؤثــرات العقليــة و تســتره علــي مصدر‬\n‫مــا ضبــط املعاقــب علــى ذلــك شــرع ًا و ذلــك لألدلــة و القرائــن التاليــة ‪:‬‬\n‫‪ /1‬مــا تضمنــه اعترافــه حتقيقـ ًا املنــوه عنــه املــدون علــى الصفحــات رقــم‬\n‫(‪ 1‬إلــى ‪ ) 3‬مــن ملــف التحقيــق املرفــق لفــة رقــم (‪ /2 )15‬مــا تضمنــه‬\n‫إقــراره املنــوه عنــه املــدون علــى الصفحــة رقــم (‪ )1‬مــن ملــف التحقيــق‬\n‫املرفــق لفــة رقــم (‪ /3 )16‬مــا تضمنتــه أقوالــه األوليــة املنــوه عنهــا املدونــة‬\n‫علــى الصفحــة رقــم (‪ )21‬مــن ملــف ضبــط إجــراءات االســتدالل يف‬\n‫قضايــا املخــدرات املرفــق لفــة رقــم (‪ /4 )1‬مــا تضمنــه محضــر القبــض‬\n‫و التفتيــش املنــوه املــدون علــى الصفحــات رقــم ( ‪2‬و‪12‬و‪ )13‬مــن ملــف‬\n\n\n                                                                                          ‫‪210‬‬\n\f      ‫ضبــط إجــراءات االســتدالل يف قضايــا املخــدرات املرفــق لفــة رقــم (‪)1‬‬\n      ‫‪ /5‬مــا تضمنــه التقريــر الكيميائــي الشــرعي املشــار إليــه املرفــق لفــة‬\n      ‫رقــم (‪ )13‬و ببحــث ســوابقه اتضــح عــدم وجــود ســوابق مســجلة حتــى‬\n      ‫تاريخــه و حيــث إن مــا أقــدم عليــه املذكــور فعــل محــرم و معاقــب عليــه‬\n      ‫شــرع ًا و نظامـ ًا مبوجــب نظــام مكافحــة املخــدرات و املؤثــرات العقليــة‬\n      ‫يف عقوباتــه األصليــة و التكميليــة لــذا أطلــب إثبــات إدانتــه مبــا أســند‬\n                                                         ‫إليــه و احلكــم عليــه باآلتــي ‪:‬‬\n      ‫‪ /1‬بعقوبــة احلبــس و اجللــد و الغرامــة املاليــة وفق ـ ًا للفقــرة ( األولــى )‬\n      ‫مــن املــادة (‪ )38‬مــن نظــام مكافحــة املخــدرات و املؤثــرات العقليــة‬\n      ‫و تشــديد العقوبــة بحقــه وفق ـ ًا للبنــد (ج) مــن الفقــرة ( الثانيــة ) مــن‬\n      ‫نفــس املــادة مــن النظــام املشــار إليــه ‪ /2‬إبعــاده إلــى خــارج اململكــة بعــد‬\n      ‫انتهــاء تنفيــذ عقوبــة ســجنه و عــدم الســماح لــه بالعــودة إليهــا مــرة أخــرى‬\n      ‫وفق ـ ًا للفقــرة ( الثانيــة) مــن املــادة (‪ )56‬مــن نفــس النظــام املشــار إليــه‬\n      ‫‪ /3‬مصــادرة املبلــغ املضبــوط بحــوزة املذكــور وقــدره (‪ )2056‬ألفــان‬\n      ‫و ســتة و خمســون ريــا ًال كونــه مــن نتــاج بيــع املخــدرات اســتناد ًا إلــى‬\n      ‫الفقــرة ( الثانيــة ) مــن املــادة (‪ )53‬مــن نظــام مكافحــة املخــدرات و‬\n      ‫املؤثــرات العقليــة ‪ /4‬مصــادرة اجلوالــن املضبوطــن معــه األول ‪ .....‬يحمل‬\n      ‫الرقــم املصنعــي رقــم ( ‪ ) ......‬و الثانــي ‪ .......‬يحمــل الرقــم املصنعــي رقــم‬\n      ‫‪.......‬ز كونهمــا اســتخدما يف اجلرميــة اســتناد ًا إلــى الفقــرة ( األولــى )‬\n      ‫مــن املــادة (‪ )53‬مــن نظــام مكافحــة املخــدرات و املؤثــرات العقليــة ‪/5‬‬\n      ‫إلغــاء الشــريحيتني الهاتفيتــن املســتخدمتني يف اجلرميــة و التــي حتمــان‬\n      ‫الرقــم ( ‪ ) .........‬و الرقــم ( ‪ )........‬و عــدم صرفهمــا لنفــس املشــترك يف‬\n      ‫حالــة صــدور حكــم باملصــادرة و إبــاغ الشــركة مصــدرة الشــريحة‬\n\n\n‫‪211‬‬\n\f‫بذلــك اســتناد ًا لتعميــم ســمو وزيــر الداخليــة رقــم ( ‪ ) 9798‬و تاريــخ‬\n‫‪1428/2/10-9‬ه ـ و اهلل املوفــق هــذه دعــواي و بعرض ذلك على املدعى‬\n‫ا إن مــا ذكــره املدعــي العــام مــن‬ ‫عليــه الــذي يجيــد العربيــة أجــاب قائـ ً‬\n‫وجــود الكبســولة معــي وأنــي سأســلمها لشــخص وداللتــي علــى موضــع‬\n‫خمــس و عشــرين كبســولة يف منــزل طــن صحيــح و قــد اســتلمتها مــن‬\n‫الشــخص الباكســتاني املذكــور و ذكــر لــي أنهــا حبــوب عــاج و ال‬\n‫أعلــم أنهــا مخــدرات و كانــت االتصــاالت بينــي و بينــه علــى جوالــي‬\n‫رقــم ‪ ...........‬وجــوال آخــر ال أحفــظ رقمــه و املبلــغ الــذي ضبــط معــي هــو‬\n‫مــن نتــاج عملــي يف البويــات و أنــا لــم أســلم أي شــخص شــيئ ًا مــن هــذه‬\n‫احلبــوب هكــذا أجــاب وباالطــاع علــى التقريــر الكيميائــي الصــادر‬\n‫مــن مركــز الســموم بالريــاض رقــم ‪ /6351‬س يف ‪........‬ه ـ املتضمــن‬\n‫إيجابيــة العينــات ملــادة الهرويــن أ‪.‬ه ـ بتصــرف كمــا ألفيــت قــول املدعــى‬\n‫عليــه علــى ص (‪ )2،1‬لفــة (‪ )15‬أن أخبــره أن احلبــوب التــي ســلمها لــه‬\n‫حبــوب محظــورة فبنــاء علــى مــا ســلف مــن الدعــوى و اإلجابــة و إلقــرار‬\n‫املدعــى عليــه بتســلمه ســت ًا و عشــرين كبســولة إال ربــع عــن طريــق‬\n‫جواليــه املذكوريــن و تبــن أنهــا حتــوي الهرويــن املخــدر و لعــدم قبــول‬\n‫ادعــاه بأنــه ال يعرفهــا بداللــة إفادتــه أن مــن ســلمها لــه أخبــره أنهــا حبــوب‬\n‫محظــورة ولقيــام القرائــن الدالــة علــى ترويجــه الهرويــن وهــي إقــراره‬\n‫بوضعــه كبســوالت الهرويــن املذكــورة يف منــزل الطــن و شــروعه يف‬\n‫ترويــج كبســولة إال ربــع و إلفصاحــه عــن مصــدر هــذه الكبســوالت‬\n‫و لعــدم وجــود الدليــل املقــدم مــن املدعــي العــام علــى أن املــال املقبــوض‬\n‫مــع املدعــى عليــه مــن نتــاج املخــدرات و ألن األصــل يف املــال احلرمــة و‬\n‫ملشــروعية التعزيــر بالقرائــن كمــا حبــس النبــي صلــى اهلل عليــه و ســلم‬\n\n\n                                                                                          ‫‪212‬‬\n\f      ‫ا يف تهمــة رواه أبــو داود و قــال حســن صحيــح و ألن الشــروع يف‬            ‫رج ـ ً‬\n      ‫الفعــل يف حكــم الفعــل و ملــا جــاء يف املــادة (‪ )38‬و ( ‪ )56‬و (‪ )53‬مــن‬\n      ‫نظــام املخــدرات و النتشــار ترويــج و تهريــب الهرويــن مــن هــذه اجلاليــة‬\n      ‫فقــد ثبــت لــدي إدانــة املدعــى عليــه بتســلم ســت ًا و عشــرين كبســولة‬\n      ‫إال ربعــا بهــا الهرويــن املخــدر و وزنهــا جميع ـ ًا مائــة و ســبعة و تســعون‬\n      ‫جرام ـ ًا وخمســة أعشــار اجلــرام بقصــد االجتــار و الترويــج و الشــروع‬\n      ‫يف تســليم كبســولة إال ربع ـ ًا تــزن خمســة جرامــات وخمســة أعشــار‬\n      ‫اجلــرام مــن ذات الكميــة بقصــد الترويــج ولــم يثبــت لــدي تســتره علــى‬\n      ‫مصدرهــا أو ترويجــه للهيرويــن يف الســابق و إمنــا قامــت القرائــن علــى‬\n      ‫ترويجــه الهيرويــن فيمــا ســبق و حكمــت عليــه مبــا يلــي ‪ /1 :‬ســجنه‬\n      ‫خمــس ســنوات تبــدأ مــن تاريــخ اإليقــاف و جلــده أمــام النــاس خمســمائة‬\n      ‫جلــده مفرقــة علــى عشــر دفعــات كل دفعــة خمســون جلــده بــن كل‬\n      ‫دفعتــن عشــرة أيــام و تغرميــه ثالثــة آالف ريــال و إبعــاده عــن اململكــة بعد‬\n      ‫انتهــاء ســجنه بعــد تصفيــة مالــه و مــا عليــه مــن حقــوق وعــدم الســماح لــه‬\n      ‫بالعــودة إ ّال فيمــا تســمح بــه أنظمــة احلــج و العمــرة و مصــادرة اجلوالــن‬\n      ‫املضبوطــن معــه ورقمهــا املصنعــي ‪.......‬و (‪ ).......‬و إلغــاء شــريحتهما رقــم‬\n      ‫(‪ )..........‬و (‪ )..........‬وعــدم صرفهــا نفــس املشــترك و إبــاغ الشــركة‬\n      ‫مصــدرة الشــريحتني بذلــك ‪2‬ـ صــرف النظــر عــن املطالبــة مبصــادرة‬\n      ‫املبلــغ و التســتر لعــدو وجــود موجبهمــا و بعــرض احلكــم عليهمــا قــرر‬\n      ‫املدعــى عليــه القناعــة و املدعــي العــام االعتــراض مكتفي ـ ًا بالئحــة‬\n      ‫االعتراضيــة وكان النطــق يف ‪......‬ه ـ و أغلقــت‬\n                                                    ‫ّ‬             ‫الدعــوى عــن الالئحــة‬\n      ‫اجللســة الســاعة التاســعة و النصــف و صلــى اهلل وســلم علــى نبينــا محمــد‬\n                                                                  ‫و علــى آلــه و صحبــه ‪.‬‬\n\n\n‫‪213‬‬\n\f‫احلمــد هلل وحــده ‪...‬وبعــد فقــد اطلعنــا نحــن قضــاة الدائــرة اجلزائيــة‬\n‫الرابعــة مبحكمــة االســتئناف بالريــاض علــى املعاملــة الــواردة مــن‬\n‫فضيلــة رئيــس احملكمــة اجلزائيــة بالريــاض برقــم ‪ ..........‬وتاريــخ ‪.......‬‬\n‫ه ـ املرفــق بهــا القــرار الصــادر مــن فضيلــة القاضــي الشــيخ ‪............/‬‬\n‫املســجل برقــم ‪...........‬وتاريــخ ‪.......‬ه ـ اخلــاص بدعــوى املدعــي العــام ضــد‬\n‫‪(.........../‬باكســتاني اجلنســية) يف قضيــة مخــدرات علــى النحــو املوضــح‬\n‫بالقــرار املتضمــن حكــم فضيلتــه مبــا هــو مــدون ومفصــل بــه‪ ،‬وبدراســة‬\n‫القــرار وصــورة ضبطــه وأوراق املعاملــة قــررت الدائــرة باألكثريــة‬\n‫املصادقــة علــى احلكــم‪ .‬و اهلل املوفــق وصلــى اهلل علــى نبينــا محمــد‬\n                                                     ‫وعلــى آلــه وصحبــه وســلم ‪.‬‬\n\n\n\n\n                                                                                       ‫‪214‬‬\n\f","legal_articles":[],"source_id":"831db040-0b05-5921-907d-640530e541d8","source_file_id":"396a5809-4e7b-56b3-9eb0-4f45acc6dbb7","source_page_start":208,"source_page_end":214,"original_source":"وزارة العدل السعودية","acquisition_source":"official_ministry_download_preserved_in_central_archive","source_url":null,"content_hash":"fb7d4d8820f49dd9f6f12908c97275f4f426bde41e66405603721a6df32b8888","normalized_text_hash":"c87c7a462f024ac2614d888e36ff3b4d5109e4258971dd6f7c88940fb86099f7","status":"review","review_status":"manual_field_review_pending","legal_search_eligibility":false,"legacy_id":"collector-1434-v18-p208-3433171"},{"id":"e2d2f47e-f1e8-5433-859d-6e5c911e8377","document_type":"judgment","category":"judicial","subcategory":"general","title":"مخدرات -نقل بقصد الترويج -قات -إنكار املدعى عليه علمه مبا مت نقله -التعزير بالسجن والغرامة.","document_number":"33412318","case_number":"33553670","judgment_number":null,"decision_number":null,"circular_number":null,"court":"محكمة الاستئناف","circuit":null,"issuing_authority":"وزارة العدل السعودية","document_date":null,"hijri_date":"1434/9/16","year":"1434","subject":"مخدرات -نقل بقصد الترويج -قات -إنكار املدعى عليه علمه مبا مت نقله -التعزير بالسجن والغرامة.","summary":null,"facts":null,"claims":null,"reasoning":null,"ruling":null,"principle_text":null,"full_text":"      ‫رقم الصك‪ 33412318 :‬تاريخه‪1434/9/16:‬هـ‬\n                        ‫رقم الدعوى‪33553670:‬‬\n         ‫رقم قرار التصديق من محكمة االستئناف‪:‬‬\n                ‫‪ 34169622‬تاريخه‪1434/3/23 :‬هـ‬\n\n\n      ‫مخــدرات ‪ -‬نقــل بقصــد الترويــج ‪ -‬قــات ‪ -‬إنــكار املدعــى عليــه علمــه مبــا‬\n                                             ‫مت نقلــه ‪ -‬التعزيــر بالســجن والغرامــة‪.‬‬\n\n\n\n\n      ‫‪ -1‬الفقــرة األولــى مــن األمــر الســامي الكــرمي رقــم (‪ )59633‬يف‬\n                                                          ‫‪1432 /12 /9‬هــ‪.‬‬\n               ‫‪ -2‬املادة (‪ )3‬من قرار مجلس الوزراء رقم(‪ )11‬لعام ‪1374‬هـ ‪.‬‬\n         ‫‪ -3‬املادة (‪ )3‬من قرار وزير الداخلية رقم ( ‪ ) 2057‬يف ‪1404/5/26‬هـ‬\n\n\n\n\n      ‫ادعــى املدعــي العــام ضــد املدعــى عليــه بنقــل قــات بقصــد االجتــار‬\n      ‫وطلــب إثبــات مــا أســند إليــه واحلكــم بتعزيــره ‪،‬حيــث مت إيقاف الســيارة‬\n      ‫التــي يقودهــا املدعــى عليــه مــن قبــل الدوريــة األمنيــة وبتفتيــش الســيارة‬\n      ‫عثــر علــى دوالب بداخلــه كميــة مــن نبــات القــات وأثبــت التقريــر‬\n      ‫الكيميائــي الشــرعي إيجابيــة العينــة املضبوطــة لنبــات القــات احملظــور‬\n      ‫وصــادق املدعــى عليــه علــى الدعــوى بــدون مترجــم وذلــك لكونــه يفهــم‬\n      ‫العربيــة ‪،‬وبنــاء علــى مــا تقــدم حكمــت احملكمــة بتعزيــره بالســجن‬\n      ‫خمــس ســنوات وتغرميــه خمســة آالف ريــال واعتــرض املدعــي العــام‬\n                   ‫‪،‬وصــدق احلكــم مــن محكمــة االســتئناف ‪.‬‬       ‫بــدون الئحــة ُ‬\n\n‫‪215‬‬\n\f‫احلمــد هلل وحــده أمــا بعــد فلــدي أنــا ‪.....‬القاضــي باحملكمــة اجلزائيــة‬\n‫بجــازان وبنــاء علــى املعاملــة الــواردة مــن دائــرة االدعــاء العــام بجــازان‬\n‫واملقيــدة بــوارد احملكمــة برقــم (‪ )331624474‬وتاريــخ ‪1433/8/28‬هـ‬\n‫واحملالة من فضيلة الرئيس برقم (‪ )33553670‬وتاريخ ‪1433/8/28‬هـ‬\n‫واملتعلقــة بدعــوى املدعــي العــام ضــد ‪.....‬املتهــم يف قضيــة قــات عليــه‬\n‫ففــي هــذا اليــوم الســبت ‪1433/9/16‬ه ـ افتتحــت اجللســة األولــى يف متــام‬\n‫الســاعة العاشــرة والربــع وفيهــا حضــر املدعــي العــام ‪.....‬املوجــه باخلطــاب‬\n‫رقــم (‪ ).....‬وتاريــخ ‪1433/3/22‬ه ـ وادعــى علــى احلاضــر ‪.....‬باكســتاني‬\n‫اجلنســية يحمــل رخصــة اإلقامــة رقــم (‪ ).....‬الصــادرة مــن جــوازات الدمــام‬\n‫أنــه يف متــام الســاعة الثانيــة عشــر ظهــر ًا مــن يــوم االثنــن ‪1433/7/7‬ه ـ‬\n‫وأثنــاء قيــام إحــدى دوريــات املجاهديــن بعملهــا قدمــت ســيارة مــن نــوع ‪....‬‬\n‫مــن صنــع عــام (‪2004‬م) وحتمــل رقــم اللوحــة ‪ ).....‬تعــود ملكيتهــا ل‪.....‬‬\n‫(مت حجزهــا حلــن مراجعــة مالكهــا) فتــم إيقافهــا واتضــح أنهــا بقيــادة‬\n‫املدعــى عليــه وبتفتيــش الســيارة عثــر علــى (دوالب) بداخلــه كميــة‬\n‫مــن نبــات القــات احملظــور بلــغ وزنهــا (‪ 329‬كجــم) ثالثمائــة وتســعة‬\n‫وعشــرين كيلــو جــرام وأثبــت التقريــر الكيميائــي الشــرعي رقــم (‪).....‬‬\n‫وتاريخ ‪1433/7/15‬هـ الصادر من قســم الســموم والكيمياء الشــرعية‬\n‫باملستشــفى إيجابيــة العينــة املرســلة منــه لنبــات القــات احملظــور املــدرج‬\n‫يف اجلــدول رقــم (‪ )4‬ورقــم (‪ )2‬فئــة (ا) و (ج) امللحــق بنظــام مكافحــة‬\n‫املخــدرات واملؤثــرات العقليــة الصــادر باملرســوم امللكــي رقــم م‪ 39/‬يف‬\n‫‪1426/7/8‬ه ـ ومت إيقافــه اســتناد ًا للقــرار الــوزاري رقــم (‪ )1900‬وتاريــخ‬\n\n                                                                                      ‫‪216‬‬\n\f      ‫‪1428/7/8‬ه ـ وباســتجواب املدعــى عليــه ومواجهتــه بالتهمــة املنســوبة‬\n      ‫إليــه أقــر بصحــة واقعــة القبــض و أنكــر حيازتــه للكميــة املضبوطــة‬\n      ‫البالــغ وزنهــا (‪ 329‬كجــم) ثالثمائــة وتســعة وعشــرين كيلــو جــرام‬\n      ‫مــن نبــات القــات احملظــور وذكــر بأنهــا تعــود ل ــشخص مينــي اجلنســية‬\n      ‫ال يعــرف عنــه أي معلومــات طلــب منــه إيصــال (الــدوالب) إلــى محافظــة‬\n      ‫فيفــاء مببلــغ وقــدره (‪ )120‬مائــة وعشــرين ريــاال وال يعلــم عــن وجــود‬\n      ‫القــات بداخلــه وقــد صــادق علــى أقوالــه وبالبحــث عــن ســوابقه لــم‬\n      ‫يعثــر لــه علــى ســوابق مســجلة وقــد أســفر التحقيــق معــه عــن توجيــه‬\n      ‫االتهــام إليــه بارتــكاب جرميــة نقــل مــا وزنــه (‪ 329‬كجــم) ثالثمائــة‬\n      ‫وتســعة وعشــرين كيلــو جــرام مــن نبــات القــات احملظــور لقصــد‬\n      ‫االجتــار واملجــرم مبوجــب الفقــرة الثانيــة مــن املــادة الثالثــة مــن نظــام‬\n      ‫مكافحــة املخــدرات واملؤثــرات العقليــة الصــادر باملرســوم امللكــي‬\n      ‫رقــم م‪ 39/‬يف ‪1426/7/8‬ه ـ وألن مــا أقــدم عليــه املذكــور فعــل محــرم‬\n      ‫شــرع ًا ومعاقــب عليــه نظامــا مبوجــب قــرار مجلــس الــوزراء رقــم (‪)11‬‬\n      ‫لعــام ‪1374‬ه ـ ومــا حلــق بــه مــن تعديــات فقــد طلــب املدعــي العــام إثبــات‬\n      ‫إدانتــه مبــا أســند إليــه واحلكــم بتعزيــره يف ضــوء املــادة الثالثــة مــن‬\n      ‫القــرار الــوزاري املشــار إليــه أعــاه إنفــاذ ًا لألمــر الســامي الكــرمي رقــم‬\n      ‫(‪ )59633‬وتاريــخ ‪1432/12/9‬ه ـ وباحلديــث مــع املدعــى عليــه تبــن‬\n      ‫أنــه يفهــم العربيــة ويحســن رد اجلــواب وبعــرض الدعــوى علــى املدعــى‬\n      ‫عليــه صــدق واقعــة القبــض وبقيادتــه الســيارة املشــار إليهــا ونفــى علمــه‬\n      ‫وعالقتــه بكميــة القــات املضبوطــة وقــرر قائــا إن شــخصا مينيــا طلــب‬\n      ‫منــه نقــل (دوالب) مــن محافظــة الدايــر إلــى محافظــة فيفــا مقابــل مائــة‬\n      ‫وعشــرين ريــاال فقامــا بتحميلــه يف الســيارة وال علــم لــه مبــا كان فيــه‬\n\n\n‫‪217‬‬\n\f‫هكــذا أجــاب وبالرجــوع إلــى أوراق املعاملــة واالطــاع علــى التقريــر‬\n‫الكيميائــي الشــرعي وثبــت ســوابق املدعــى عليــه وجــدت طبــق مــا يف‬\n‫الدعــوى عليــه فبنــاء علــى مــا تقــدم مــن الدعــوى واإلجابــة ولضعــف مــا‬\n‫دفــع بــه املدعــى عليــه لكبــر حجــم الكميــة املضبوطــة مــن نبــات القــات‬\n‫وهــو أمــر يلحــظ جليــا عنــد حتميــل (الــدوالب) كمــا أن لنبــات القــات‬\n‫رائحــة ال ميكــن أن تخفــى خاصــة مــع كبــر حجــم الكميــة وملــا تضمنــه‬\n‫األمــر الســامي الكــرمي رقــم (‪ )59633‬وتاريخ ‪1432/12/9‬هـ يف فقرته‬\n‫األولــى مــن املوافقــة علــى أن تطبــق احملاكــم علــى مرتكبــي جرائــم‬\n‫القــات العقوبــات املعمــول بهــا قبــل نفــاذ نظــام مكافحــة املخــدرات‬\n‫واملؤثــرات العقليــة لذلــك كلــه فقــد ثبتــت لــدي إدانــة املدعــى عليــه بنقــل‬\n‫كميــة القــات املذكــورة أعــاه بقصــد االجتــار وهــو يســتحق العقوبــة‬\n‫علــى ذلــك وفــق املــادة (‪ )3‬مــن قــرار مجلــس الــوزراء رقــم (‪ )11‬عــام‬\n‫‪1374‬ه ـ واملــادة (‪ )3‬مــن قــرار ســمو وزيــر الداخليــة رقــم (‪ )2057‬وتاريــخ‬\n‫‪1404/5/26‬ه ـ وقــد حكمــت عليــه لذلــك تعزيــرا بالســجن مــدة خمــس‬\n‫ســنوات تبــدأ مــن تاريــخ القبــض عليــه وإيقافــه علــى ذمــة هــذه القضيــة‬\n‫يف ‪1433/7/7‬ه ـ وتغرميــه مبلــغ خمســة آالف ريــال يــؤول إلــى اخلزينــة‬\n‫العامــة للدولــة هــذا مــا ثبــت لــدي وبــه حكمــت وبعرضــه علــى الطرفــن‬\n‫قــرر املدعــي العــام معارضتــه وطلــب رفعــه حملكمــة االســتئناف دون‬\n‫الئحــة فأجبتــه لذلــك وقــرر املدعــى عليــه القناعــة بــه وقــد جــرى النطــق‬\n‫بــه يف متــام الســاعة العاشــرة والنصــف وبــاهلل التوفيــق وصلــى اهلل وســلم‬\n     ‫علــى نبينــا محمــد وآلــه وصحبــه أجمعــن حــرر يف ‪1433/9/16‬هـ ـ‬\n‫ويف هــذا اليــوم األربعــاء ‪1433/11/17‬ه ـ افتتحــت اجللســة الثانيــة‬\n‫يف متــام الســاعة العاشــرة والربــع وكانــت املعاملــة قــد وردت مــن‬\n\n\n                                                                                       ‫‪218‬‬\n\f      ‫محكمــة االســتئناف رفــق خطــاب رئيســها رقــم (‪)331777988‬‬\n      ‫وتاريــخ ‪1433/11/10‬ه ـ املقيــد بهــذه احملكمــة برقــم (‪)332032997‬‬\n      ‫وتاريــخ ‪1433/11/16‬ه ـ واحملالــة مــن فضيلــة الرئيــس ومرفــق بهــا قــرار‬\n      ‫املالحظــة الصــادر عــن الدائــرة اجل ــزائية الثانيــة برقــم (‪)33440727‬‬\n      ‫وتاريــخ ‪1433/10/28‬ه ـ ويتضمــن تقــرر إعادتهــا لفضيلــة حاكمهــا‬\n      ‫ملالحظــة أن فضيلــة ناظــر القضيــة لــم يتضمــن حكمــه إبعــاد املدعــى‬\n      ‫عليــه عــن البــاد حســب التعليمــات انتهــى قــدر احلاجــة منــه وجوابــا‬\n      ‫علــى مــا ذكــره أصحــاب الفضيلــة أقــول مســتعين ًا بــاهلل إن عقوبــة‬\n      ‫اإلبعــاد لــم تــرد يف املــادة الثالثــة مــن قــرار مجلــس الــوزراء رقــم (‪)11‬‬\n      ‫لعــام ‪1374‬ه ـ والتــي جــاء األمــر الســامي الكــرمي رقــم (‪ )59633‬وتاريــخ‬\n      ‫‪1433/12/9‬ه ـ بتطبيقهــا وأمــر اإلقامــة واإلبعــاد لــه نظــام يحكمــه‬\n      ‫حســبما نــص عليــه تعميــم معالــي وزيــر العــدل رقــم (‪/183/8‬ت) وتاريــخ‬\n      ‫‪1408/10/9‬ه ـ (التصنيــف املوضوعــي املجلــد اخلامــس ص ‪62‬ـ‪ )63‬وبــه‬\n      ‫لــم يظهــر لــي عــدول عمــا رقــم أعــاه وأمــرت بإحلــاق ذلــك يف القــرار‬\n      ‫وصــورة ضبطــه وبعــث كامــل أوراق املعاملــة إلــى محكمــة االســتئناف‬\n                                        ‫وبــاهلل التوفيــق حــرر يف ‪1433/11/17‬ه ـ‬\n      ‫ويف هــذا اليــوم األحــد ‪1434/2/17‬ه ـ افتتحــت اجللســة الثالثــة يف‬\n      ‫متــام الســاعة العاشــرة والنصــف وكانــت املعاملــة قــد وردت مــن‬\n      ‫محكمــة االســتئناف رفــق خطــاب رئيســها رقــم (‪)332105274‬‬\n      ‫وتاريخ‪1433/12/26‬ه ـ املقيــد بهــذه احملكمــة برقــم (‪)346357‬‬\n      ‫وتاريخ‪1434/1/3‬ه ـ واحملالــة مــن فضيلــة الرئيــس ومرفــق بهــا قــرار‬\n      ‫املالحظــة الصــادر عــن الدائــرة اجل ــزائية الثانيــة برقــم (‪)33472424‬‬\n      ‫وتاريخ‪1433/12/19‬ه ـ ويتضمــن تقــرر إعادتهــا ملالحظــة أن مــا أجــاب‬\n\n\n‫‪219‬‬\n\f‫بــه فضيلــة ناظــر القضيــة غيــر مقنــع فقــد نــص علــى إبعــاد مــن هــو أقــل‬\n‫جرمــا مــن املدعــى عليــه وال يعنــي عــدم النــص علــى ذلــك يف املــادة املشــار‬\n‫إليهــا أنــه ال يبعــد فــكل مــن ارتكــب جرمــا وهــو أجنبــي فيبعــد اتقــاء‬\n‫لشــره انتهــى قــدر احلاجــة منــه وجوابــا علــى ذلــك أقــول مســتعينا بــاهلل‬\n‫إننــي قــد ذكــرت مســتندا لــي يف اجلــواب تعميــم معالــي وزيــر العــدل‬\n‫املشــار إليــه وهــو مــا لــم يناقشــه أصحــاب الفضيلــة يف قــرار املالحظــة‬\n‫ولــم يــرد حســب علمــي مغيــر ملقتضــاه حتــى تاريخــه ومــا حكمــت بــه‬\n‫جــار علــى منصــوص النظــام وأمــا التنصيــص علــى إبعــاد مــن هــو أقــل‬\n‫جرمــا مــن املدعــى عليــه فذلــك وارد يف قــرار املنظــم واحلكــم مبقتضــاه‬\n‫جــار علــى ذلــك ومحــل البحــث فيمــا لــم يــرد بــه نــص والتعميــم املذكــور‬\n‫يعالــج ذلــك وبــه لــم يظهــر لــي عــدول عمــا رقــم أعــاه وأمــرت بإحلــاق ذلك‬\n‫يف القــرار وصــورة ضبطــه وبعــث كامــل أوراق املعاملــة إلــى محكمــة‬\n ‫االســتئناف لتدقيــق احلكــم وبــاهلل التوفيــق حــرر يف ‪1434/2/17‬ه ـ‬\n‫احلمــد هلل وحــده وبعــد فقــد اطلعنــا نحــن قضــاة الدائــرة الثانيــة لتدقيــق‬\n‫القضايــا اجلزائيــة مبحكمــة االســتئناف مبنطقــة عســير علــى املعاملــة‬\n‫الــواردة مــن فضيلــة رئيــس احملكمــة اجلزائيــة بجــازان رقــم ‪346357‬‬\n‫وتاريــخ ‪1434/2/19‬ه ـ املرفــق بهــا القــرار الصــادر مــن فضيلــة القاضــي‬\n‫باحملكمــة الشــيخ ‪..... /‬رقــم ‪ 33412318‬وتاريــخ ‪1433/9/16‬ه ـ‬\n‫اخلــاص بدعــوى املدعــي العــام ضــد ‪ (..... /‬باكســتاني اجلنســية ) يف‬\n‫قضيــة ( قــات ) علــى الصفــة املوضحــة يف القــرار املتضمــن حكــم‬\n‫فضيلتــه مبــا هــو مــدون ومفصــل فيــه وحيث ســبق دراســة القــرار وصورة‬\n‫ضبطــه وأوراق املعاملــة وباالطــاع علــى مــا أجــاب بــه فضيلتــه وأحلقــه‬\n‫ـاء علــى قرارنــا رقــم ‪ 33472424‬وتاريــخ‬       ‫بالقــرار وصــورة ضبطــه بنـ ً‬\n\n                                                                                       ‫‪220‬‬\n\f      ‫‪1433/12/19‬ه ـ و قرارنــا رقــم ‪ 33440727‬وتاريــخ ‪1433/10/28‬ه ـ‬\n      ‫تقــررت املوافقــة علــى احلكــم بعــد اإلجــراء األخيــر ‪ .‬واهلل املوفــق وصلــى‬\n                                   ‫اهلل علــى نبينــا محمــد وآلــه وصحبــه وســلم ‪.‬‬\n\n\n\n\n‫‪221‬‬\n\f","legal_articles":[],"source_id":"831db040-0b05-5921-907d-640530e541d8","source_file_id":"396a5809-4e7b-56b3-9eb0-4f45acc6dbb7","source_page_start":215,"source_page_end":221,"original_source":"وزارة العدل السعودية","acquisition_source":"official_ministry_download_preserved_in_central_archive","source_url":null,"content_hash":"01c31ce2d9d68341f29da341cd52ea359f13208454fc7936348d9e8ac93628bf","normalized_text_hash":"08c0614fee6fd09c15ddf73eb812abf531fb54f0735c08eb326a51543bfd2313","status":"review","review_status":"manual_field_review_pending","legal_search_eligibility":false,"legacy_id":"collector-1434-v18-p215-33412318"},{"id":"462f34eb-ec5b-577a-a9e3-7b660ece8c10","document_type":"judgment","category":"judicial","subcategory":"general","title":"مخدرات -اشتراك يف ترويج -قات -مقاومة رجال األمن -مساعدة املدعى عليهما مروج على الهرب -تداخل العقوبات التعزيرية - التعزير بالسجن واجللد.","document_number":"33462509","case_number":"33598578","judgment_number":null,"decision_number":null,"circular_number":null,"court":"محكمة الاستئناف","circuit":null,"issuing_authority":"وزارة العدل السعودية","document_date":null,"hijri_date":"1433/11/22","year":"1434","subject":"مخدرات -اشتراك يف ترويج -قات -مقاومة رجال األمن -مساعدة املدعى عليهما مروج على الهرب -تداخل العقوبات التعزيرية - التعزير بالسجن واجللد.","summary":null,"facts":null,"claims":null,"reasoning":null,"ruling":null,"principle_text":null,"full_text":"‫رقم الصك‪ 33462509:‬تاريخه‪1433/11/22 :‬هـ‬\n                   ‫رقم الدعوى‪33598578:‬‬\n    ‫رقم قرار التصديق من محكمة االستئناف‪:‬‬\n           ‫‪ 3418844‬تاريخه‪1434/01/21:‬هـ‬\n\n\n‫مخدرات ‪ -‬اشــتراك يف ترويج ‪ -‬قات ‪ -‬مقاومة رجال األمن ‪ -‬مســاعدة‬\n‫املدعــى عليهمــا مــروج علــى الهــرب ‪ -‬تداخــل العقوبــات التعزيريــة ‪-‬‬\n                                            ‫التعزيــر بالســجن واجللــد‪.‬‬\n\n\n\n‫‪ -1‬مــا قــرره أهــل العلــم يف تداخــل العقوبــات التعزيريــة حيــث جــاء‬\n‫يف كشــاف القنــاع ج ‪ 485/ 20‬للبهوتــي ( ولــو توجــه عليــه تعزيــرات‬\n‫علــى معــاص شــتى فــإن متحضــت هلل تعالــى واحتــد نوعهــا كأن قبــل‬\n‫أجنبيــة مــرارا أو اختلــف نوعهــا بــأن قبــل أجنبيــة وملــس أخــرى قصــدا‬\n                                      ‫تداخلــت وكفــاه تعزيــر واحــد ) ‪.‬‬\n‫‪ -2‬املادة الرابعة من قرار وزير الداخلية رقم (‪ )2057‬يف ‪1404/5/26‬هـ‪.‬‬\n                         ‫‪ -3‬القرار الوزاري رقم (‪ )3818‬يف ‪1410/9/28‬هـ‬\n                     ‫‪ -4‬قرار وزير الداخلية رقم (‪ )1900‬يف ‪1428/7/9‬هـ‬\n\n\n\n\n‫ادعــى املدعــي العــام ضــد املدعــى عليهمــا أحدهمــا أجنبــي واآلخــر‬\n‫ســعودي باالشــتراك يف بيــع القــات ومقاومــة رجــال األمــن وطلــب إثبــات‬\n‫مــا أســند إليهمــا ومعاقبتهمــا تعزيــر ًا وتعزيرهمــا ملقاومــة رجــال األمــن ‪،‬‬\n‫حيــث مت مالحظــة شــخص يقــوم بترويــج القــات من قبــل فرقة مكافحة‬\n\n                                                                                      ‫‪222‬‬\n\f      ‫املخــدرات ومت التفــاوض معــه علــى شــرائه ويف احلــال مت القبــض عليــه‬\n      ‫وبحوزتــه القــات ثــم قــام بطلــب املســاعدة فحضــر مجموعــة مــن‬\n      ‫األشــخاص وقامــوا مبقاومــة الفرقــة ومســاعدة املــروج علــى الهــرب ومت‬\n      ‫القبــض علــى املدعــى عليهمــا وهمــا ممــن قامــا مبســاعدة املــروج علــى‬\n      ‫الهــرب وأثبــت التقريــر الكيميائــي الشــرعي إيجابيــة العينــة املضبوطــة‬\n      ‫لنبــات القــات احملظــور ‪ ،‬كمــا أقــر املدعــى عليــه األول بحيــازة القــات‬\n      ‫بقصــد االســتعمال وأنكــر املشــاركة ببيــع القــات ومقاومــة رجــال‬\n      ‫األمــن ‪ ،‬كمــا أنكــر املدعــى عليــه الثانــي الدعــوى ‪ ،‬و أحضــر املدعــي‬\n      ‫العــام شــاهدين مــن الفرقــة القابضــة وشــهدا مبقاومــة املدعــى عليهمــا‬\n      ‫للفرقــة ومســاعدة املــروج علــى الهــرب ولــم تتضمــن شــهادتهما مــا يديــن‬\n      ‫املدعــى عليهمــا باالشــتراك يف بيــع القــات وصــرف النظــر عــن طلــب‬\n      ‫املدعــي العــام مبعاقبتهمــا وإثبــات إدانــة املدعــى عليــه األول بحيــازة‬\n      ‫القــات بقصــد التعاطــي ومعاقبتــه تعزيــر ًا ‪،‬ومت إثبــات إدانــة املدعــى‬\n      ‫عليهمــا مبقاومــة رجــال األمــن واشــتراكهما يف تخليــص املقبــوض عليــه‬\n      ‫مــن قبــل رجــال األمــن وتعزيرهمــا لقــاء ذلــك بالســجن ســنتني وجلدهمــا‬\n      ‫ثالثمائــة جلــدة مفرقــة علــى دفعــات مقــدار كل دفعــة خمســة وســبعون‬\n      ‫‪،‬وصــدق‬\n            ‫وقنــع املدعــى عليهمــا واعتــرض املدعــي العــام بــدون الئحــة ُ‬\n                                               ‫احلكــم مــن محكمــة االســتئناف‪.‬‬\n\n\n\n      ‫احلمــد هلل وحــده أمــا بعــد فلــدي أنــا ‪.....‬القاضــي باحملكمــة اجلزائيــة‬\n      ‫بجــازان وبنــاء علــى املعاملــة الــواردة مــن دائــرة االدعــاء العــام بجــازان‬\n      ‫واملقيدة بوارد احملكمة برقم (‪ )331795904‬وتاريخ ‪1433/10/14‬هـ‬\n\n‫‪223‬‬\n\f‫واحملالــة مــن فضيلــة الرئيــس برقــم (‪ )33598578‬وتاريــخ‬\n‫‪1433/10/14‬ه ـ واملتعلقــة بدعــوى املدعــي العــام ضــد كل مــن االول‬\n‫‪.....‬والثانــي ‪ .....‬املتهمــان يف قضيــة قــات عليــه ففــي هــذا اليــوم الســبت‬\n‫‪1433/10/28‬ه ـ افتتحــت اجللســة األولــى يف متــام الســاعة العاشــرة إال‬\n‫ربعــا وفيهــا حضــر املدعــي العــام ‪.....‬املوجــه باخلطــاب رقــم (‪ ).....‬وتاريــخ‬\n‫‪1433/3/22‬ه ـ وادعــى علــى احلاضريــن كل مــن األول ‪.....‬ميني اجلنســية‬\n‫يحمــل بطاقــة بديلــة برقــم (‪ ).....‬صــادرة مــن إدارة مكافحــة املخــدرات‬\n‫بتاريــخ ‪1433/8/13‬ه ـ والثانــي ‪.....‬ســعودي اجلنســية يحمــل الهويــة‬\n‫الوطنيــة ورقــم ســجله املدنــي (‪ ).....‬أنــه بتاريــخ ‪1433/8/13‬ه ـ وأثنــاء‬\n‫قيــام إحــدى فــرق مكافحــة املخــدرات بعملهــا املعتــاد مبحافظــة الــدرب‬\n‫ـاء علــى املعلومــات الــواردة مــن أحــد املتعاونــن ومفادهــا وجــود‬       ‫وبنـ ً‬\n‫شــخص يدعــى ‪.....‬يقــوم بترويــج مــادة القــات يف محافظــة بيــش عليــه متــت‬\n‫مالحظــة املــروج وعنــد مقابلتــه مــن قبــل رئيــس الفرقــة وهــو يحمــل بيــده‬\n‫حزمــه يشــتبه أن تكــون مــن نبــات القــات احملظــور ملفوفــة داخــل قماش‬\n‫ومت التفــاوض معــه علــى شــرائها ويف احلــال مت القبــض علــى املــروج‬\n‫وضبطــت بحوزتــه احلزمــة التــي يريــد بيعهــا وهــي عبــارة عــن نبــات القــات‬\n‫احملظــور بلــغ وزنهــا (‪250‬جــم) مائتــن وخمســن جرامــا وأثنــاء القبــض‬\n‫عليــه صــاح بصــوت مرتفــع يطلــب مســاعدته ويف احلــال حضــر مجموعــة‬\n‫أشــخاص رجــال وبينهــم نســاء وقامــوا مبســاعدة املــروج حتــى مكنــوه‬\n‫مــن الهــرب وذلــك بعــد مقاومــة عنيفــة علــى إثرهــا أصيــب فيهــا رئيــس‬\n‫الفرقــة ومت القبــض علــى املدعــى عليهمــا وهمــا ممــن قامــوا مبســاعدة‬\n‫املــروج علــى الهــرب وأثبــت التقريــر الكيميائــي الشــرعي رقــم (‪).....‬‬\n‫بتاريــخ ‪1433/8/21‬ه ـ الصــادر مــن مستشــفى ‪ ....‬إيجابيــة العينــة‬\n\n\n                                                                                       ‫‪224‬‬\n\f      ‫املرســلة مــن الكميــة املضبوطــة لنبــات القــات احملظــور املــدرج باجلــدول‬\n      ‫رقــم (‪ )2‬فئــة (أ‪،‬ج) واجلــدول رقــم (‪ )4‬امللحقــن بنظــام مكافحــة‬\n      ‫املخــدرات واملؤثــرات العقليــة الصــادر باملرســوم امللكــي رقــم م‪ 39/‬يف‬\n      ‫‪1426/7/8‬ه ـ ومت إيقافهمــا اســتناد ًا للقــرار الــوزاري رقــم (‪)1900‬‬\n      ‫وتاريــخ ‪1432/7/9‬ه ـ املبنــي علــى املــادة (‪ )112‬مــن نظــام اإلجــراءات‬\n      ‫اجلزائيــة وبالبحــث عــن ســوابقهما عثــر لــأول منهمــا علــى ســابقة نصــب‬\n      ‫واحتيــال ولــم يعثــر للثانــي منهمــا علــى ســوابق مســجلة حتــى تاريخــه‬\n      ‫وباســتجواب املدعــي عليهمــا وبعــد مواجهتهمــا بالتهمــة املنســوبة إليهمــا‬\n      ‫أنكــرا عالقتهمــا بكميــة القــات املضبوطــة البالــغ وزنهــا (‪ 250‬جــم)‬\n      ‫مائتــن وخمســن جرامــا وأنهمــا لــم يقومــا مبســاعدة املــروج علــى الهــرب‬\n      ‫وصادقــا علــى أقوالهمــا بذلــك حتقيقـ ًا وقــد أســفر التحقيــق مــع املدعــي‬\n      ‫عليهمــا عــن توجيــه االتهــام إليهمــا باشــتراكهما يف بيــع مــا وزنــه (‪250‬‬\n      ‫جــم) مائتــن وخمســن جرامــا مــن نبــات القــات احملظــور عــن طريــق‬\n      ‫االتفــاق واملســاعدة واملجــرم مبوجــب الفقــرة رقــم (‪ )2‬مــن املــادة الثالثــة‬\n      ‫مــن نظــام مكافحــة املخــدرات واملؤثــرات العقليــة الصــادر باملرســوم‬\n      ‫امللكــي رقــم (م‪ )39/‬وتاريــخ ‪1426/7/8‬ه ـ ومبقاومــة رجــال األمــن‬\n      ‫وألن مــا أقــدم عليــه املدعــي عليهمــا فعــل محــرم شــرع ًا ومعاقــب عليــه‬\n      ‫نظامـ ًا مبوجــب قــرار مجلــس الــوزراء رقــم (‪ )11‬لعــام ‪1374‬ه ـ ومــا حلــق‬\n      ‫بــه مــن تعديــات فقــد طلــب املدعــي العــام إثبــات إدانتهمــا مبــا أســند‬\n      ‫إليهمــا واحلكــم بتعزيرهمــا يف ضــوء املــادة الثالثــة مــن القــرار الــوزاري‬\n      ‫املشــار إليــه أعــاه إنفــاذ ًا لألمــر الســامي الكــرمي رقــم (‪ )59633‬وتاريــخ‬\n      ‫‪1432/12/9‬ه ـ وتعزيرهمــا شــرع ًا لقــاء مقاومتهمــا لرجــال األمــن‬\n      ‫وبعــرض الدعــوى علــى املدعــى عليــه األول صــدق تاريــخ القبــض‬\n\n\n‫‪225‬‬\n\f‫والســابقة املســجلة عليــه وأنكــر االتهــام املوجــه إليــه وقــرر قائال كانت‬\n‫بحوزتــي كميــة القــات املشــار إليهــا يف الدعــوى بقصــد االســتعمال‬\n‫الشــخصي فتفاجــأت بشــخص يركــض خلفــي فلــذت بالفــرار ودخلــت‬\n‫منــزل املدعــى عليــه الثانــي هــذا احلاضــر ثــم جــرى القبــض علــي بعــد أن‬\n‫ســلمني مالــك املنــزل ملكافحــة املخــدرات وال صحــة التهامــي ببيــع‬\n‫القــات أو مفاوضــة رجــال األمــن يف ذلــك هكذا أجــاب وبعرض الدعوى‬\n‫علــى املدعــى عليــه الثانــي أجــاب قائــا مــا ذكــره املدعــي العــام غيــر‬\n‫صحيــح جملــة وتفصيــا بــل بالتاريــخ املشــار اليــه يف الدعــوى اســتيقظت‬\n‫علــى أصــوات النســاء يف منزلــي وعنــد خروجــي تبــن لــي وجود أشــخاص‬\n‫يف حــوش املنــزل وبســؤالهم عــن ســبب دخولهــم أفادونــي بأنهــم مــن‬\n‫مكافحــة املخــدرات وأن املدعــى عليــه األول مطلــوب لهــم وقــد الذ‬\n‫مبنزلــي عندهــا أخرجــت املدعــى عليــه األول مــن منزلــي وســلمته لهــم‬\n‫فقبــض علــي معــه أيضــا ووجــه إلــي هــذا االتهــام هكــذا أجــاب وبســؤال‬\n‫املدعــي العــام البينــة علــى دعــواه اســتمهل يف إحضارهــا إلــى جلســة تاليــة‬\n‫هكــذا أجــاب ويف جلســة تاليــه وفيهــا حضــر املدعــي العــام واملدعــى‬\n‫عليهمــا وجــرى ســؤال املدعــي العــام عــن البينــة التي اســتمهل إلحضارها‬\n‫يف اجللســة املاضيــة فأحضــر للشــهادة كال مــن ‪.....‬ســعودي اجلنســية‬\n‫يحمــل الهويــة الوطنيــة ورقــم ســجله املدنــي (‪ ).....‬واحلفيظــة رقــم (‪).....‬‬\n‫وتاريــخ ‪1426/4/15‬ه ـ الصــادرة مــن أحــوال صبيــا مضــى مــن عمــره‬\n‫(‪ 23‬عامــا) ويســكن قريــة ‪.....‬ويعمــل بــإدارة مخــدرات الــدرب و‪.....‬‬\n‫ســعودي اجلنســية يحمــل الهويــة الوطنيــة ورقــم ســجله املدنــي (‪).....‬‬\n‫واحلفيظــة رقــم (‪ ).....‬وتاريــخ ‪1426/6/11‬ه ـ الصــادرة مــن أحوال جازان‬\n‫مضــى مــن عمــره (‪ 24‬عامــا) ويســكن قريــة ‪ .....‬ويعمــل بــإدارة مخــدرات‬\n\n\n                                                                                     ‫‪226‬‬\n\f      ‫ا أشــهد بــاهلل تعالــى‬\n                             ‫الــدرب وبســؤال األول منهمــا عمــا لديــه أجــاب قائـ ً‬\n      ‫أنــه يف يــوم مــن األيــام ال أذكــره وردت إخباريــة عــن طريــق أحــد‬\n      ‫املتعاونيــن يفيــد عــن وجــود شــخص يقــوم ببيــع القــات يف حــي ‪.....‬يف‬\n      ‫محافظــة بيــش وباالنتقــال إلــى املوقــع وجــد الشــخص ومت التفــاوض معــه‬\n      ‫علــى شــراء حزمــة مــن القــات وعنــد االســتالم منــه مت القبــض عليــه‬\n      ‫فصــاح طالبــا املســاعدة فتجمهــر علينــا أنــاس كثــر منهــم رجــال ونســاء‬\n      ‫وخلصــوا الشــخص املقبــوض عليــه وأصيــب أحــد زمالئنــا ومتكنــا مــن‬\n      ‫القبــض علــى املدعــى عليهمــا وهمــا ممــن قــام مبقاومتنــا وتخليــص‬\n      ‫الشــخص املقبــوض عليــه هــذا مــا لــدي وبــه أشــهد وبســؤال الثانــي منهما‬\n      ‫ا أشــهد بــاهلل تعالــى أنــه يف يــوم مــن األيــام ال‬\n                                                             ‫عمــا لديــه أجــاب قائ ـ ً‬\n      ‫أذكــره ويف حــي ‪.....‬يف محافظــة بيــش مت التفــاوض مــع أحد األشــخاص‬\n      ‫علــى شــراء حزمــة مــن القــات وعنــد االســتالم منــه مت القبــض عليــه‬\n      ‫فصــاح طالبــا املســاعدة فتجمهــر علينــا أنــاس كثــر منهــم رجــال ونســاء‬\n      ‫وخلصــوا الشــخص املقبــوض عليــه وأصيــب أحــد زمالئنــا ومتكنــا مــن‬\n      ‫القبــض علــى املدعــى عليهمــا وهمــا ممــن قــام مبقاومتنــا وتخليــص‬\n      ‫الشــخص املقبــوض عليــه هــذا مــا لــدي وبــه أشــهد وبعــرض الشــاهدين‬\n      ‫وشــهادتهما علــى املدعــى عليــه األول وهــل لــه طعــن يف دينهمــا أو‬\n      ‫مروءتهمــا أجــاب قائــا أمــا شــهادتهما فغيــر صحيحــة وأمــا الشــاهدان‬\n      ‫فــا أعلــم عــن حالهمــا هكــذا أجــاب وبعــرض الشــاهدين وشــهادتهما‬\n      ‫علــى املدعــى عليــه الثانــي وهــل لــه طعــن يف دينهمــا أو مروءتهمــا أجــاب‬\n      ‫قائــا أمــا شــهادتهما فغيــر صحيحــة وأمــا الشــاهدان فــا أعلــم عــن‬\n      ‫حالهمــا هكــذا أجــاب ويف اجللســة حضــر ‪.....‬ســعودي اجلنســية يحمــل‬\n      ‫الهويــة الوطنيــة ورقــم ســجله املدنــي (‪ ).....‬و‪.....‬ســعودي يحمــل الهويــة‬\n\n\n‫‪227‬‬\n\f‫الوطنيــة ورقــم ســجله املدنــي (‪ ).....‬وشــهدا بعدالــة الشــاهدين وأنهمــا‬\n‫مقبــوال الشــهادة وبســؤال املدعــي العــام هــل لديــك مزيــد بينــة أجــاب‬\n‫قائــا ال أعلــم لــي مزيــد بينــة علــى مــا بــأوراق املعاملــة هكــذا أجــاب‬\n‫وبالرجــوع إلــى أوراق املعاملــة جــرى االطــاع علــى ثبــت ســوابق املدعــى‬\n‫عليهمــا والتقريــر الكيميائــي الشــرعي فوجــدت مطابقــة ملــا يف الدعوى‬\n‫كمــا جــرى االطــاع علــى بقيــة لفــات املعاملــة ولــم أجــد بهــا مــا يديــن‬\n‫املدعــى عليهمــا باالشــتراك يف بيــع نبــات القــات وبســؤال املدعــي العــام‬\n‫هــل لديــك مزيــد بينــة أجــاب قائــا ال أعلــم لــي مزيــد بينــة هكــذا أجــاب‬\n‫عليــه فبنــاء علــى مــا تقــدم مــن الدعــوى واإلجابــة وإلقــرار املدعــى عليــه‬\n‫األول بحيــازة كميــة مــن نبــات القــات بقصــد االســتعمال الشــخصي‬\n‫ولعجــز املدعــي العــام عــن إقامــة البينــة املثبتــة إلدانــة املدعــى عليهمــا‬\n‫باالشــتراك يف بيع كمية من نبات القات ولشــهادة الشــاهدين املعدلني‬\n‫شــرعا مبقامــة املدعــى عليهمــا لهــم مــع مجموعــة مــن األشــخاص‬\n‫وتخليصهــم الشــخص املقبــوض عليــه مــن قبضتهــم وشــهادتهما بإصابــة‬\n‫أحــد رجــال األمــن أثنــاء هــذه املقاومــة لذلــك كلــه وملــا تضمنــه األمــر‬\n‫الســامي الكــرمي رقــم (‪ )59633‬وتاريــخ ‪1432/12/9‬ه ـ يف فقرتــه‬\n‫األولــى مــن املوافقــة علــى أن تطبــق احملاكــم علــى مرتكبــي جرائــم‬\n‫القــات العقوبــات املعمــول بهــا قبــل نفــاذ نظــام مكافحــة املخــدرات‬\n‫واملؤثــرات العقليــة فقــد قــررت مــا يلــي أوال لــم تثبــت لــدي إدانــة املدعــى‬\n‫عليهمــا باالشــتراك يف بيــع كميــة مــن نبــات القــات وصرفــت النظــر عــن‬\n‫طلــب املدعــي العــام إثبــات إدانــة املدعــى عليهمــا بذلــك ومجازاتهمــا يف‬\n‫ضــوء املــادة الثالثــة مــن قــرار مجلــس الــوزراء رقــم (‪ )11‬لعــام ‪1374‬ه ـ‬\n‫وثبتــت لــدي إدانــة املدعــى عليــه األول حســب اعترافــه بحيــازة كميــة‬\n\n\n                                                                                        ‫‪228‬‬\n\f      ‫مــن نبــات القــات بقصــد التعاطــي وهــو يســتحق العقوبــة التعزيريــة علــى‬\n      ‫ذلــك وفــق املــادة (‪ )4‬مــن قــرار ســمو زيــر الداخليــة رقــم (‪ )2057‬وتاريــخ‬\n      ‫‪1404/5/26‬ه ـ املعدلــة بالقــرار الــوزاري رقــم (‪ )3818‬وتاريــخ‬\n      ‫‪1410/9/28‬ه ـ ثانيــا ثبتــت لــدي إدانــة املدعــى عليهمــا مبقاومــة رجــال‬\n      ‫األمــن مــع أشــخاص آخريــن واشــتراكهما يف تخليــص شــخص مقبــوض‬\n      ‫عليــه مــن قبــل رجــال األمــن وقــد نتــج عــن هــذه املقاومــة إصابــة أحــد‬\n      ‫رجــال األمــن وهمــا يســتحقان التعزيــر البليــغ لقــاء ذلــك وملــا قــرره أهــل‬\n      ‫العلــم يف تداخــل العقوبــات التعزيريــة قــال العالمــة البهوتــي (ولــو توجــه‬\n      ‫عليــه تعزيــرات علــى معــاص شــتى فــإن متحضــت هلل تعالــى واحتــد نوعهــا‬\n      ‫كأن قبــل أجنبيــة مــرار ًا أو اختلــف نوعهــا بــأن قبــل أجنبيــة وملــس أخــرى‬\n      ‫قصــد ًا تداخلــت وكفــاه تعزيــر واحــد) كشــاف القنــاع عــن مــن اإلقنــاع‬\n      ‫(ج‪20‬ص‪ )485‬فقــد قــررت االكتفــاء مبجــازاة املدعــى عليــه األول علــى‬\n      ‫جرمــه يف مقاومــة رجــال األمــن وتخليــص الشــخص املقبــوض عليــه وملــا‬\n      ‫يف الفعــل الــذي أقــدم عليــه املدعــى عليهمــا مــن مجابهــة لرجــال األمــن‬\n      ‫أثنــاء قيامهــم بواجبهــم ومتكــن للمفســدين مــن اســتمرار إجرامهــم‬\n      ‫وحمايتهــم والدفــاع عنهــم وتخليصهــم مــن أيــدي العدالــة وملــا يف فعلهمــا‬\n      ‫مــن اســتخفاف بقــوة رجــال األمــن وتعــد عليهــم واشــتراك يف إحلــاق‬\n      ‫الضــرر بهــم ســيما وأن هــذا اجلــرم يف معنــى اجلرائــم الكبيــرة الــواردة يف‬\n      ‫قــرار ســمو وزيــر الداخليــة رقــم (‪ )1900‬وتاريــخ ‪1428/7/9‬ه ـ واملبلــغ‬\n      ‫بالتعميــم رقــم (‪/13‬ت‪ )3187/‬وتاريــخ ‪1428/8/5‬ه ـ لذلــك كلــه فقــد‬\n      ‫حكمــت بســجن كل واحــد مــن املدعــى عليهمــا مــدة ســنتني اعتبــارا‬\n      ‫مــن تاريــخ القبــض عليهمــا وإيقافهمــا علــى ذمــة هــذه القضيــة يف‬\n      ‫‪1433/8/13‬ه ـ وجلــد كل واحــد منهمــا ثالثمائــة جلــدة علــى دفعــات‬\n\n\n‫‪229‬‬\n\f‫كل دفعــة خمــس وســبعون جلــدة وبــن كل دفعــة والتــي تليهــا شــهر‬\n‫هــذا مــا ثبــت لــدي وبــه حكمــت وبعرضــه علــى أطــراف القضيــة قــرر‬\n‫املدعــي العــام معارضتــه وطلــب رفعــه حملكمــة االســتئناف دون الئحــة‬\n‫فأجبتــه لذلــك وقــرر املدعــى عليهمــا القناعــة بــه وقــد جــرى النطــق بــه يف‬\n‫متــام الســاعة الواحــدة والنصــف وبــاهلل التوفيــق وصلــى اهلل وســلم علــى‬\n             ‫نبينا محمد وآله وصحبه أجمعني حرر يف ‪1433/11/17‬هـ‬\n‫احلمــد هلل وحــده وبعــد فقــد اطلعنــا نحــن قضــاة الدائــرة األولــى‬\n‫لتدقيــق القضايــا اجلزائيــة مبحكمــة االســتئناف مبنطقــة عســير علــى‬\n‫املعاملــة الــواردة مــن فضيلــة رئيــس احملكمــة اجلزائيــة بجــازان برقــم‬\n‫‪ 331795904‬وتاريــخ ‪1433/12/28‬ه ـ املرفــق بهــا القــرار الصــادر‬\n‫مــن فضيل ــة القاضــي باحملكمــة الشــيخ‪...../‬برقم ‪ 33462509‬وتاريــخ‬\n‫‪1433/11/22‬ه ـ اخلــاص بدعــوى املدعــي العــام ضــد كل مــن ‪..... /‬‬\n‫( ســعودي اجلنســية) و ‪(.....‬مينــي اجلنســية) يف قضيــة (قــات) علــى الصفــة‬\n‫املوضحــة يف القــرار املتضمــن حكــم فضيلتــه مبــا هــو مــدون ومفصــل‬\n‫فيــه وبدراســة القــرار وصــورة ضبطــه وأوراق املعاملــة تقــررت املوافقــة‬\n‫علــى احلكــم ‪ .‬واهلل املوفــق وصلــى اهلل علــى نبينــا محمــد وآلــه وصحبــه‬\n                                                                           ‫وســلم ‪.‬‬\n\n\n\n\n                                                                                      ‫‪230‬‬\n\f","legal_articles":[],"source_id":"831db040-0b05-5921-907d-640530e541d8","source_file_id":"396a5809-4e7b-56b3-9eb0-4f45acc6dbb7","source_page_start":222,"source_page_end":230,"original_source":"وزارة العدل السعودية","acquisition_source":"official_ministry_download_preserved_in_central_archive","source_url":null,"content_hash":"1896a6ab1704cd3c538785dfcea5343f7a79929f868a33057f50faa75cd8f3ff","normalized_text_hash":"0955462786bd606e9fb951e7ddc473f429c8f56a830032e0f0da6a9f0f773aa6","status":"review","review_status":"manual_field_review_pending","legal_search_eligibility":false,"legacy_id":"collector-1434-v18-p222-33462509"},{"id":"1d6fabbb-f360-5c4e-bb23-6088e7f3d5ee","document_type":"judgment","category":"judicial","subcategory":"general","title":"مخدرات -ترويج احلبوب احملظورة « حبوب الكبتاجون » -تخفيف العقوبة لقلة الكمية ولكون املدعى عليه ليس من أرباب السوابق من جنس التهمة -صرف النظر عن طلب املدعي العام إلزام املدعى عليه رد املبلغ احلكومي -صرف النظر عن طلب املدعي العام تعزير املدعى عليه لقاء تستره على مصدر املخدرات -التعزير بالسجن واجللد والغرامة واملنع من السفر ومصادرة اجلوال وإلغاء","document_number":"33483133","case_number":"33606469","judgment_number":null,"decision_number":null,"circular_number":null,"court":"محكمة الاستئناف","circuit":null,"issuing_authority":"وزارة العدل السعودية","document_date":null,"hijri_date":"1433/12/29","year":"1434","subject":"مخدرات -ترويج احلبوب احملظورة « حبوب الكبتاجون » -تخفيف العقوبة لقلة الكمية ولكون املدعى عليه ليس من أرباب السوابق من جنس التهمة -صرف النظر عن طلب املدعي العام إلزام املدعى عليه رد املبلغ احلكومي -صرف النظر عن طلب املدعي العام تعزير املدعى عليه لقاء تستره على مصدر املخدرات -التعزير بالسجن واجللد والغرامة واملنع من السفر ومصادرة اجلوال وإلغاء","summary":null,"facts":null,"claims":null,"reasoning":null,"ruling":null,"principle_text":null,"full_text":"      ‫رقم الصك‪ 33483133:‬تاريخه ‪1433/12/29:‬هـ‬\n                         ‫رقم الدعوى‪33606469:‬‬\n                   ‫رقم قرار التصديق من محكمة‬\n        ‫االستئناف‪ 3428454:‬تاريخه‪1434/02/03:‬هـ‬\n\n\n      ‫مخــدرات ‪ -‬ترويــج احلبــوب احملظــورة « حبــوب الكبتاجــون » ‪ -‬تخفيــف‬\n      ‫العقوبــة لقلــة الكميــة ولكــون املدعــى عليــه ليــس مــن أربــاب الســوابق‬\n      ‫مــن جنــس التهمــة ‪ -‬صــرف النظــر عــن طلــب املدعــي العــام إلــزام‬\n      ‫املدعــى عليــه رد املبلــغ احلكومــي ‪ -‬صــرف النظــر عــن طلــب املدعــي‬\n      ‫العــام تعزيــر املدعــى عليــه لقــاء تســتره علــى مصدر املخــدرات ‪ -‬التعزير‬\n      ‫بالســجن واجللــد والغرامــة واملنــع مــن الســفر ومصــادرة اجلــوال وإلغــاء‬\n                                                                         ‫الشــريحة ‪.‬‬\n\n\n\n\n                  ‫‪ -‬املادة (‪ )38‬من نظام مكافحة املخدرات واملؤثرات العقلية ‪.‬‬\n                   ‫‪ -‬املادة (‪ )53‬من نظام مكافحة املخدرات واملؤثرات العقلية‪.‬‬\n                   ‫‪ -‬املادة (‪ )56‬من نظام مكافحة املخدرات واملؤثرات العقلية‪.‬‬\n                   ‫‪ -‬املادة (‪ )60‬من نظام مكافحة املخدرات واملؤثرات العقلية‪.‬‬\n\n\n\n\n      ‫ادعــى املدعــي العــام علــى املدعــى عليــه بترويــج احلبــوب احملظــورة‬\n      ‫عــن طريــق البيــع ‪ ،‬انتهــى التحقيــق إلــى توجيــه االتهــام إلــى املدعــى‬\n      ‫عليــه بترويــج حبــوب الكبتاجــون عــن طريــق البيــع مرتــن ‪ ،‬األولــى‬\n      ‫لعــدد ( ‪ ) 5‬خمــس حبــات ‪ ،‬والثانيــة لعــدد (‪ ) 1.50‬حبــة ونصــف ‪،‬‬\n\n‫‪231‬‬\n\f‫وتســتره علــى مصــدره يف احلصــول علــى املخــدرات ‪ ،‬وطلــب املدعــي‬\n‫العــام تعزيــر املدعــى عليــه بالســجن واجللــد والغرامــة واملنــع مــن الســفر‬\n‫ومصــادرة اجلــوال وإلغــاء الشــريحة ورد املبلــغ احلكومــي ‪ ،‬وتعزيــره لقــاء‬\n‫تســتره علــى مصــدر املخــدرات ‪ ،‬أنكــر املدعــي عليــه مــا جــاء بدعــوى‬\n‫املدعــي العــام‪ ،‬بطلــب البينــة مــن املدعــي العــام علــى دعــواه أحضــر‬\n‫للشــهادة معــدي محضــر القبــض فشــهدا بصحــة الواقعــة ‪ ،‬وأنهمــا‬\n‫اشــتريا مــن املدعــى عليــه حبــوب محظــورة‪ ،‬وســبق أن عــدل الشــاهدان‬\n‫ســابقاً‪ ،‬صــدر احلكــم بتعزيــر املدعــى عليــه بالســجن واجللــد والغرامــة‬\n‫واملصــادرة وإلغــاء الشــريحة واملنــع مــن الســفر ملــدة ثــاث ســنوات بعــد‬\n‫إنهــاء محكوميتــه ‪ ،‬ومت النــزول عــن احلــد األدنــى للعقوبــة ‪ ،‬لكــون‬\n‫املدعــى عليــه ليــس مــن أربــاب الســوابق مــن جنــس هــذه التهمــة ‪ ،‬ولقلــة‬\n‫الكميــة املروجــة‪ ،‬صــدر احلكــم بصــرف النظــر عــن طلــب املدعــي‬\n‫العــام تعزيــر املدعــى عليــه لقــاء تســتره علــى مصــدر املخــدرات لتعاونــه‬\n‫مــع جهــة الضبــط‪ ،‬وصــرف النظــر عــن طلــب املدعــي العــام إعــادة املبلــغ‬\n‫احلكومــي ‪ ،‬لعــدم ثبــوت دعــوى الترويــج األولــى‪ ،‬قــرر املدعــى عليــه‬\n‫واملدعــى العــام اعتراضهمــا علــى احلكــم‪ ،‬صــدق احلكــم مــن محكمــة‬\n                                                                    ‫االســتئناف‪.‬‬\n\n\n\n‫احلمد هلل وحده وبعد فلدي أنا مساعد رئيس احملكمة اجلزائية مبكة‬\n‫املكرمــة وبنــاء علــى املعاملــة احملالــة لنــا مــن فضيلــة رئيــس احملكمــة‬\n‫اجلزائيــة مبكــة املكرمــة برقــم ‪ 33606469‬وتاريــخ ‪1433/10/16‬ه ـ‬\n‫املقيــدة باحملكمــة برقــم ‪ 331823849‬وتاريــخ ‪1433/10/16‬ه ـ ففــي‬\n\n                                                                                     ‫‪232‬‬\n\f      ‫يــوم االثنــن املوافــق ‪1433/11/01‬ه ـ افتتحــت اجللســة الســاعة ‪10 : 45‬‬\n      ‫وفيهــا حضــر املدعــي العــام املكلــف بالترافــع لدينــا يف قضايــا احلــق‬\n      ‫العــام مبوجــب خطــاب رئيــس دائــرة االدعــاء العــام مبكــة املكرمــة‬\n      ‫رقــم م‪/2/1‬د‪ 125/‬يف ‪1431/5/14‬ه ـ وأدعــى علــى احلاضــر معــه ‪........‬‬\n      ‫ا يف دعــواه عليــه‬   ‫ســعودي اجلنســية بالســجل املدنــي رقــم (‪ )......‬قائ ـ ً‬\n      ‫أنــه بتاريــخ ‪1433/9/16‬ه ـ مت القبــض علــى املدعــى عليــه وقــد أنتهــى‬\n      ‫التحقيــق إلــى توجيــه االتهــام للمدعــى عليــه بترويــج حبــوب الكبتاجــون‬\n      ‫عــن طريــق البيــع مرتــن األولــى لعــدد (‪ )5‬خمــس حبــات والثانيــة لعــدد‬\n      ‫(‪ )1.50‬حبــه ونصــف احلبــه احملتويــة علــى مــادة الالمفتيامــن وتســتره‬\n      ‫علــى مصــدره يف احلصــول علــى احلبــوب احملظــورة وبالبحــث عــن ســوابقه‬\n      ‫عثــر لــه علــى ســابقة ســرقة حيوانــات لــذا أطلــب إثبــات إدانتــه مبــا أســند‬\n      ‫إليــه واحلكــم عليــه بالســجن واجللــد والغرامــة ومنعــه مــن الســفر خلــارج‬\n      ‫البــاد مبوجــب املادتــن (‪ )38‬و(‪ )56‬مــن نظــام مكافحــة املخــدرات‬\n      ‫واحلكــم مبصــادرة الهاتــف اجلــوال مبوجــب املــادة (‪ )53‬مــن ذات النظــام‬\n      ‫والنــص يف القــرار الشــرعي علــى إدخــال قيمــة اجلــوال مبؤسســة النقــد‬\n      ‫العربــي الســعودي حلســاب املديريــة العامــة ملكافحــة املخــدرات وإلغــاء‬\n      ‫الشــريحة وطلــب إلزامــه بــرد املبلــغ املالــي وقــدره (‪ )200‬مئتــا ريــال‬\n      ‫املســتخدم يف عملية الشــراء العائد إلدارة مكافحة املخدرات واحلكم‬\n      ‫عليــه بعقوبــة تعزيريــة لقــاء تســتره علــى مصــدره يف احلصــول علــى‬\n      ‫احلبــوب احملظــورة وبســؤال املدعــى عليــه قــال مــا أدعــاه املدعــي العــام يف‬\n      ‫دعــواه غيــر صحيــح وبطلــب البينــة مــن املدعــي العــام قــال أطلــب إمهالــي‬\n      ‫ورفعــت اجللســة ليــوم الثالثــاء ه ـ الســاعة التاســعة والنصــف صباحـ ًا يف‬\n      ‫يــوم الثالثــاء املوافق‪1433/11/09‬ه ـ افتتحــت اجللســة الســاعة ‪45:11‬‬\n\n\n‫‪233‬‬\n\f‫وفيهــا حضــر الطرفــان وجــرى ســؤال املدعــي العــام عــن بينتــه فقــال لــم‬\n‫حتضــر وأطلــب إمهالــي للتنســيق مــع إدارة مكافحــة املخــدرات يف مــدة‬\n‫ال تتجــاوز أســبوع نظــر ًا الختــاف ورديــات الفرقــة القابضــة وســوف يتــم‬\n‫اشــعاركم باملوعــد احملــدد مــع الفرقــة بعــد التنســيق ورفعــت اجللســة يف‬\n‫يــوم الســبت املوافــق‪ 1433/11/20‬ه ـ افتتحــت اجللســة الســاعة ‪11:45‬‬\n‫وفيهــا حضــر الطرفــان وأحضــر املدعــي العــام معــه بالســجل املدنــي رقــم‬\n‫ا أكنــت‬    ‫(‪ )......‬بالســجل املدنــي رقــم (‪ ).......‬وباستشــهادهما شــهد قائـ ً‬\n‫واقف ـ ًا عنــد البنــك ‪ ....‬أصــرف مــن الصرافــة فطلــب منــي املدعــى عليــه‬\n‫أن أوصلــه إلــى بيتــه فوافقــت وركــب معــي فقلــت لــه أال تعلــم لــي أحــد ًا‬\n‫يبيــع احلبــوب فقــال أنــا آتــي لــك بهــا وســلمت مائتــي ريــال فذهــب وألتقــى‬\n‫باملــروج وســلمني خمــس حبــات ثــم أنزلتــه عنــد بيتــه ثــم أجريــت اتصــا ًال‬\n‫بــه للشــراء مــرة أخــرى وقــال الشــاهد ركبــت مــع الشــاهد والتقينــا‬\n‫باملدعــى عليــه وقــال الشــاهدان قمــت أنــا بتســليم املدعــى عليــه خمســن‬\n‫ريــا ًال وســلمني أنــا والشــاهد يــرى ذلــك وقــام بتســليمي حبــة ونصــف فتــم‬\n‫القبــض عليــه واملبلــغ املرقــم يف حوزتــه هــذا مــا لدينــا مــن شــهادة وبعرض‬\n‫حــال الشــاهدين ومــا جــاء يف شــهادتهما علــى املدعــى عليــه قــال أمــا‬\n‫حالهمــا فــا أعلــم عنهمــا شــيئ ًا وأمــا مــا جــاء يف شــهادتهما فشــهادتهما‬\n‫غيــر صحيحــة هكــذا أجــاب والشــاهدان ســبق تزكيتهمــا فســألت‬\n‫املدعــي العــام هــل لديــك زيــادة بينــة فقــال ليــس لــدي ســوى مــن أحضــرت‬\n‫ومــا جــاء يف أوراق املعاملــة ورفعــت اجللســة لالطــاع علــى املعاملــة ويف‬\n‫يــوم االربعــاء ‪1433/11/24‬ه ـ افتتحــت اجللســة الســاعة (‪)10:15‬‬\n‫وفيهــا حضــر الطرفــان وقــد جــرى االطــاع علــى التقريــر الكيميائــي‬\n‫الشــرعي رقــم (‪/26308‬س‪1433/2‬هــ) فوجدتــه يتضمــن إيجابيــة املادة‬\n\n\n                                                                                       ‫‪234‬‬\n\f      ‫املضبوطــة للحبــوب احملظــورة فســألت املدعــي العــام هــل لديــك زيــادة‬\n      ‫بينــة علــى واقعــة الترويــج األولــى التــي بــاع فيهــا املدعــى عليــه خمــس‬\n      ‫حبــات فقــال ليــس لــدي ســوى مــن أحضــرت فســألت املدعــى عليــه هــل‬\n      ‫أرشــد الفرقــة القابضــة علــى مصــدر احلبــوب فقــال نعــم مت القبــض عليــه‬\n      ‫وبعــرض ذلــك علــى املدعــي العــام قــال أطلــب إمهالــي لســؤال املكافحــة‬\n      ‫عــن صحــة ذلــك ورفعــت اجللســة ويف يــوم االربعــاء ‪1433/12/29‬ه ـ‬\n      ‫افتتحــت اجللســة الســاعة (‪ )11:45‬وفيهــا حضــر الطرفــان وقــد وردنــا‬\n      ‫مــن مديــر مكافحــة املخــدرات بالعاصمــة املقدســة خطابــه رقــم‬\n      ‫‪3991/1/2/4/15‬س يف ‪1433/12/9‬هـ وتضمن أن املتهم‪ /‬مت ســؤاله‬\n      ‫مــن أيــن يحصــل علــى احلبــوب احملظــورة فأجــاب بأنــه يحصــل عليهــا مــن‬\n      ‫شــخص يدعــى‪ /‬ومت القبــض عليــه الحق ـ ًا عــن طريــق أحــد مصادرنــا‬\n      ‫الســرية وســجلت القضيــة برقــم (‪ )33/1297‬وبعــرض ذلــك علــى املدعي‬\n      ‫ـاء علــى مــا‬\n                  ‫العــام قــال ليــس لــدي ســوى مــا ورد يف أوراق املعاملــة وبنـ ً‬\n      ‫تقــدم مــن الدعــوى واإلجابــة وشــهادة الشــاهدين أعــاه فقــد ثبــت لــدي‬\n      ‫قيــام املدعــى عليــه بترويــج حبــة ونصــف احلبــة مــن حبــوب الالمفيتامــن‬\n      ‫عــن طريــق البيــع ووجهــت لــه تهمــة ترويــج خمــس حبــات مــن ذات النــوع‬\n      ‫عــن طريــق البيــع وحيــث أن املدعــى عليــه ليــس مــن أربــاب الســوابق مــن‬\n      ‫ـاء علــى املــادة (‪)60‬‬\n                           ‫جنــس هــذه التهمــة ومــا قــام بترويجــه شــيء يســير وبنـ ً‬\n      ‫مــن نظــام مكافحــة املخــدرات فقــد قــررت النــزول عــن احلــد األدنــى مــن‬\n      ‫العقوبــة املنصــوص عليهــا يف املــادة (‪ )38‬مــن ذات النظــام وحكمــت‬\n      ‫بســجنه ثــاث ســنوات حتســب منهــا فتــرة إيقافــه الســابقة وجلــده‬\n      ‫وتغرميــه مبوجــب املــادة (‪ )38‬مــن نفــس النظــام وذلــك بجلــده ثالثمائــة‬\n      ‫جلــده مفرقــه علــى ســت دفعــات متســاوية يفصــل بينهــا عشــرة أيــام‬\n\n\n‫‪235‬‬\n\f‫وتغرميــه ثالثــة آالف ريــال كمــا حكمــت مبوجــب املــادة (‪ )53‬مــن ذات‬\n‫النظــام وذلــك مبصــادرة الهاتــف اجلــوال املذكور رقمــه يف الئحة املدعي‬\n‫العــام وإدخــال قيمتــه مبؤسســة النقــد العربــي الســعودي حلســاب املديريــة‬\n‫العامــة ملكافحــة املخــدرات كمــا حكمــت بإلغــاء شــريحة هــذا اجلــوال‬\n‫وعــدم صرفهــا للمدعــى عليــه وحيــث أن املدعــى عليــه تعــاون مــع جهــة‬\n‫الضبــط وأرشــدهم إلــى مصــدر احلبــوب ومت القبــض علــى املــروج فلــم‬\n‫يثبــت لــدي تســتره علــى مصــدر احلبــوب وحكمــت بصــرف النظــر عــن‬\n‫طلــب املدعــي العــام إلــزام املدعــى عليــه بــرد املبلــغ احلكومــي وقــدره‬\n‫(‪ )....‬مائتــا ريــال لعــدم ثبــوت دعــوى الترويــج االولــى وأفهمــت املدعــى‬\n‫عليــه بــأن املــادة (‪ )56‬مــن ذات النظــام تســتوجب منعــه مــن الســفر مــدة‬\n‫ثــاث ســنوات وبعــرض احلكــم علــى الطرفــن قــرر املدعــى عليــه عــدم‬\n‫قناعتــه باحلكــم وطلــب محكمــة االســتئناف بــدون الئحــة كمــا قــرر‬\n‫املدعــي العــام االعتــراض بالئحــة وأبلغتــه بــأن مــدة االعتــراض ثالثــون‬\n‫يوم ـ ًا مــن تاريــخ صــدور القــرار يــوم االربعــاء ‪1433/12/29‬ه ـ وبــاهلل‬\n‫التوفيــق ‪ ،‬وصلــى اهلل علــى نبينــا محمــد وعلــى آلــه وصحبــه وســلم‪ .‬حــرر‬\n                                                        ‫يف ‪1433/12/29‬ه ـ‬\n‫احلمــد هلل وحــده والصــاة والســام علــى مــن ال نبــي بعــده وبعــد‪ ،‬نحــن‬\n‫قضاة الدائرة اجلزائية السادسة مبحكمة االستئناف مبكة املكرمة‬\n‫جــرى منــا االطــاع علــى املعاملــة الــواردة إلــى هــذه احملكمــة بكتــاب‬\n‫فضيلــة الرئيــس املســاعد باحملكمــة اجلزائيــة مبكــة املكرمة الشــيخ‪/‬‬\n‫رقــم(‪ )331823849‬وتاريخ(‪1434/1/21‬هــ) املرفــق بهــا القرار الصادر‬\n‫مــن فضيلتــه برقم(‪)33483133‬وتاريخ(‪1433/12/29‬هـ)‪،‬املتضمــن‬\n‫دعــوى املدعــي العــام ضــد‪ 44/‬عامــا ســعودي اجلنســية ‪ ،‬املتهــم يف‬\n\n\n                                                                                  ‫‪236‬‬\n\f      ‫مخــدرات ‪ ،‬احملكــوم فيــه مبــا دون باطنــه ‪ ،‬وبدراســة القــرار وصــورة‬\n      ‫ضبطــه والئحتــه االعتراضيــة تقــررت املوافقــة علــى احلكــم ‪ ،‬واهلل‬\n            ‫املوفــق‪ ،‬وصلــى اهلل علــى نبينــا محمــد وعلــى آلــه وصحبــه وســلم‪.‬‬\n\n\n\n\n‫‪237‬‬\n\f","legal_articles":[],"source_id":"831db040-0b05-5921-907d-640530e541d8","source_file_id":"396a5809-4e7b-56b3-9eb0-4f45acc6dbb7","source_page_start":231,"source_page_end":237,"original_source":"وزارة العدل السعودية","acquisition_source":"official_ministry_download_preserved_in_central_archive","source_url":null,"content_hash":"ae24d6306c204b1ff3cd3c2e34762747780b60cfd17ec9c5a06002955c5a119e","normalized_text_hash":"a72e338486bd311e5de718fa900967f662a203b544cf6e35e881408f369565e9","status":"review","review_status":"manual_field_review_pending","legal_search_eligibility":false,"legacy_id":"collector-1434-v18-p231-33483133"},{"id":"593af908-bb48-5d18-8fb2-5a3eb7013f22","document_type":"judgment","category":"judicial","subcategory":"general","title":"مخدرات -ترويج احلبوب احملظورة -تعاطي احلبوب احملظورة -حيازة احلبوب احملظورة بقصد التعاطي -إقرار املدعى عليه -التعزير بالسجن واجللد والغرامة واملنع من السفر -مصادرة الهاتف اجلوال.","document_number":"33448152","case_number":"33606482","judgment_number":null,"decision_number":null,"circular_number":null,"court":"محكمة الاستئناف","circuit":null,"issuing_authority":"وزارة العدل السعودية","document_date":null,"hijri_date":"1433/11/08","year":"1434","subject":"مخدرات -ترويج احلبوب احملظورة -تعاطي احلبوب احملظورة -حيازة احلبوب احملظورة بقصد التعاطي -إقرار املدعى عليه -التعزير بالسجن واجللد والغرامة واملنع من السفر -مصادرة الهاتف اجلوال.","summary":null,"facts":null,"claims":null,"reasoning":null,"ruling":null,"principle_text":null,"full_text":"‫رقم الصك‪ 33448152:‬تاريخه ‪1433/11/08:‬هـ‬\n                  ‫رقم الدعوى ‪33606482:‬‬\n    ‫رقم قرار التصديق من محكمة االستئناف‪:‬‬\n           ‫‪ 3416074‬تاريخه‪1434/01/19:‬هـ‬\n\n\n‫مخــدرات ‪ -‬ترويــج احلبــوب احملظــورة ‪ -‬تعاطــي احلبــوب احملظــورة‬\n‫‪ -‬حيــازة احلبــوب احملظــورة بقصــد التعاطــي ‪ -‬إقــرار املدعــى عليــه‬\n‫‪ -‬التعزيــر بالســجن واجللــد والغرامــة واملنــع مــن الســفر ‪ -‬مصــادرة‬\n                                                      ‫الهاتــف اجلــوال‪.‬‬\n\n\n\n             ‫‪ -‬املادة (‪ )38‬من نظام مكافحة املخدرات واملؤثرات العقلية‪.‬‬\n             ‫‪ -‬املادة (‪ )56‬من نظام مكافحة املخدرات واملؤثرات العقلية‪.‬‬\n             ‫‪ -‬املادة (‪ )53‬من نظام مكافحة املخدرات واملؤثرات العقلية‪.‬‬\n             ‫‪ -‬املادة (‪ )60‬من نظام مكافحة املخدرات واملؤثرات العقلية‪.‬‬\n\n\n\n‫ادعــى املدعــي العــام على املدعي عليه بترويــج احلبوب احملظورة‪،‬وحيازة‬\n‫حبــة مــن حبــوب اإلمفيتامــن احملظــورة ‪ ،‬وتعاطيــه ملثلهــا‪ ،‬حيــث وردت‬\n‫معلومــات ســرية تفيــد بــأن هنــاك شــخص يقــوم بالتوســط يف ترويــج‬\n‫احلبــوب احملظــورة ‪ ،‬واســتعد املصــدر للشــراء منــه ‪ ،‬ومت تزويــده باملبلــغ‬\n‫املرقــم ‪ ،‬ومت تفتيشــه قبــل نزولــه ‪ ،‬وملــا تقابــل مــع املدعــى عليــه ‪،‬‬\n‫ســلم املصــدر املبلــغ للمدعــى عليــه ‪ ،‬وكان ذلــك حتــت أنظــار الفرقــة‬\n‫القابضــة ‪ ،‬ثــم حتــركا مــن املوقــع إلــى مــكان آخــر‪ ،‬وبعــد وقــت يســير‬\n\n\n                                                                                  ‫‪238‬‬\n\f      ‫مت القبــض علــى املدعــى عليــه ‪ ،‬وقــام املصــدر بتســليم رقيــب الفرقــة‬\n      ‫حبتــن مــن احلبــوب احملظــورة ‪ ،‬وبتفتيــش املدعــى عليــه وجــد بحوزتــه‬\n      ‫حبــة واحــدة مــن حبــوب الكبتاجــون ‪ ،‬وجهــاز جــوال ‪ ،‬وهــو الــذي مــن‬\n      ‫خاللــه مت التنســيق معــه‪ ،‬وطلــب املدعــي العــام تعزيــر املدعــى عليــه‬\n      ‫بالســجن واجللــد والغرامــة واملنــع مــن الســفر واملصــادرة‪ ،‬أقــر املدعــى‬\n      ‫عليــه مبــا جــاء بدعــوى املدعــي عليــه‪ ،‬صــدر احلكــم بتعزيــر املدعــى‬\n      ‫عليــه بالســجن واجللــد واملنــع مــن الســفر والغرامــة واملصــادرة وإعــادة‬\n      ‫املبلــغ احلكومــي وتعزيــره لقــاء اســتعماله للحبــوب احملظــورة‪ ،‬قنــع‬\n      ‫املدعــى عليــه باحلكــم ‪ ،‬وقــرر املدعــي العــام اعتراضــه علــى احلكــم‬\n                           ‫بالئحــة‪ ،‬صــدق احلكــم مــن محكمــة االســتئناف‪.‬‬\n\n\n\n      ‫احلمــد هلل وحــده وبعــد فلــدي أنــا القاضــي يف احملكمــة اجلزائيــة مبكــة‬\n      ‫املكرمــة وبنــاء علــى املعاملــة احملالــة لنــا مــن فضيلــة رئيــس احملكمــة‬\n      ‫اجلزائيــة مبكــة املكرمــة برقم (‪ ).....‬وتاريخ (‪).....‬ه ـ املقيدة باحملكمة‬\n      ‫برقــم (‪ ).....‬وتاريــخ (‪).....‬ه ـ ففــي يــوم اإلثنــن املوافق‪1433/11/08‬ه ـ‬\n      ‫افتتحــت اجللســة الســاعة ‪ 11 : 30‬وفيهــا حضــر املدعــي العــام مبوجــب‬\n      ‫خطــاب التكليــف مــن مرجعــه رقــم يف ه ـ وادعــى علــى احلاضــر معــه‬\n      ‫ســعودي اجلنســية مبوجــب الســجل املدنــي رقــم (‪ ).....‬قائــا بدعــواه أنــه‬\n      ‫يف يــوم اخلميــس (‪).....‬ه ـ وردت معلومــات ســريه تفيــد وجــود شــخص‬\n      ‫(املدعــى عليــه) يقــوم بالتوســط يف ترويــج احلبــوب احملظــورة بشــارع‬\n      ‫واســتعد املصــدر بالشــراء املباشــر منــه ومت متكينــه مــن االتصــال علــى‬\n      ‫هاتفــه رقــم (‪ ).....‬وطلــب منــه كميــة مــن احلبــوب احملظــورة مببلغ (‪)100‬‬\n\n‫‪239‬‬\n\f‫مائــة ريــال واســتعد املدعــى عليــه بذلــك وطلــب مــن املصــدر احلضــور إليــه‬\n‫بحــي ويف متــام الســاعة احلاديــة عشــر والنصــف مســاء مت تزويــد املصــدر‬\n‫باملبلــغ املرقــم بعــد تفتيشــه ودفعــه حتــت أنظــار الفرقــة وتقابــا ســوي ًا‬\n‫ومــن ثــم ركــب املدعــى عليــه مــع املصــدر وطلــب منــه االجتــاه إلــى حــي‬\n‫ودخــا إلــى احلــي وبعــد حوالــي خمــس دقائــق خرجــا مــن احلــي وعلــى‬\n‫الفــور مت القبــض علــى املدعــى عليــه وقــام املصــدر بتســليم رقيــب‬\n‫الفرقــة عــدد حبتــن مــن حبــوب الكبتاجــون احملظــورة وأفــاد بأنــه قــام‬\n‫بتســليم املبلــغ املرقــم للمدعــى عليــه وأن املدعــى عليــه نــزل واختفــاء عــن‬\n‫األنظــار ثــم عــاد وقــام بتســليم الكميــة املتفــق عليهــا وبتفتيــش املدعــى‬\n‫عليــه شــخصي ًا عثــر بداخــل جيبــه علــى عــدد حبــه واحــدة مــن حبــوب‬\n‫الكبتاجــون احملظــورة وعثــر علــى جــوال مــن نــوع (‪ ).....‬يحمــل الرقــم‬\n‫املصنعــي (‪ ).....‬وهــو نفــس اجلــوال الــذي مت التنســيق عليــه وقــد أثبــت‬\n‫التقريــر الكيميائــي الشــرعي (‪ 2259‬س‪1433 2‬هــ) أن قرصان بيضاء‬\n‫اللــون يحمــان العالمــة املعتــادة لعقــار الكبتاجــون ثبــت أنهمــا يحتويــان‬\n‫علــى مــادة االمفيتامــن وأن قــرص واحــد أبيــض اللــون يحمــل العالمــة‬\n‫املعتــادة لعقــار الكبتاجــون (املضبــوط بحــوزة املدعــى عليــه) ثبــت أنــه‬\n‫يحتــوي علــى مــادة االمفيتامــن وهــو مــن املــواد املدرجــة بجــدول املــواد‬\n‫املخــدرة واملؤثــرات العقليــة وباســتجواب املدعــى عليــه‪ /‬أقــر ببيــع عــدد‬\n‫حبتــن مــن حبــوب الكبتاجــون احملظــورة مببلــغ مائــة ريــال وحيــازة حبــة‬\n‫واحــدة مــن حبــوب الكبتاجــون احملظــورة بقصــد التعاطــي وأن آخــر‬\n‫مــرة تعاطــى بهــا احلبــوب احملظــورة قبــل القبــض عليــه بيومــن كونــه‬\n‫يتعاطــى احلبــوب احملظــورة منــذ خمــس ســنوات تقريب ـ ًا وكمــا اعتــرف‬\n‫بــأن رقــم هاتفــه الــوارد يف واقعــة الضبــط هــو الــذي مت التنســيق عليــه‬\n\n\n                                                                                      ‫‪240‬‬\n\f      ‫وقــد انتهــى التحقيــق إلــى توجيــه االتهــام ل ـ بترويــج عــدد حبتــن مــن‬\n      ‫حبــوب الكبتاجــون احملتويــة علــى مــادة االمفيتامــن عــن طريــق البيــع‬\n      ‫وحيــازة عــدد حبــة واحــدة مــن حبــوب الكبتاجــون احملتويــة علــى مــادة‬\n      ‫االمفيتامــن بقصــد التعاطــي وتعاطيــه الســابق للحبــوب احملظــورة‬\n      ‫احملرمــة شــرع ًا املجرمــة نظام ـ ًا وذلــك لألدلــة والقرائــن املوضحــة‬\n      ‫بالدعــوى وحيــث إن مــا قــام بــه املدعــى عليــه وهــو بكامــل أهليتــه‬\n      ‫املعتبــرة شــرع ًا فعــل محــرم ومجــرم ومعاقــب عليــه شــرع ًا ونظامـ ًا اطلــب‬\n      ‫احلكــم عليــه وفق ـ ًا للمــادة رقــم مــن ‪ 38‬و‪ 56‬و‪ 53‬مــن نظــام مكافحــة‬\n      ‫املخــدرات هــذه دعــواي وبســؤال املدعــى عليــه قــال مــا ذكــره املدعــي‬\n      ‫العــام صحيــح حيــث اتصــل بــي املصــدر وطلــب التوســط يف شــراء‬\n      ‫احلبــوب علــى هاتفــي املذكــور فذهبــت معــه للمــروج وأخــذت مائــة ريــال‬\n      ‫وســلمتها للمــروج واســتلمت منــه ثــاث حبــات كبتاجــون وأعطيتهــا‬\n      ‫للمصــدر الــذي أهدانــي منهــا حبــة واحــدة ألتعاطاهــا ألننــي أتعاطــى مــن‬\n      ‫نــوع هــذه احلبــوب منــذ فتــرة وبعــد ذلــك قبــض علــي واعترفــت بــكل‬\n      ‫شــيئ ودللــت علــى املــروج وأنــا مجــرد وســيط ودالل فقــط وهــذه أول مــرة‬\n      ‫وآخــر مــرة وأتعهــد بالتوبــة هــذه إجابتــي ثــم جــرى االطــاع علــى التقريــر‬\n      ‫الكيميائــي املرفــق لفــة ‪ 19‬فوجدتــه يتضمــن احتــواء املضبوطــات‬\n      ‫علــى األمفيتامــن احملظــور كمــا لــم أجــد للمدعــى عليــه ســوابق فبنــاء‬\n      ‫علــى مــا تقــدم مــن الدعــوى واإلجابــة وإلــى إقــرار املدعــى عليــه بدعــوى‬\n      ‫املدعــي العــام وبنــاء علــى املــواد ‪ 38‬و‪ 56‬و‪ 53‬و ‪ 60‬مــن نظــام مكافحــة‬\n      ‫املخــدرات ولعــدم وجــود ســوابق ومبــادرة املدعــى عليــه باالعتــراف‬\n      ‫وتعهــده بالتوبــة لــذا فقــد ثبــت لــدي إدانــة املدعــى عليــه مبــا أســند إليــه‬\n      ‫مــن ترويــج حبتــن مــن حبــوب األمفيتامــن احملظــورة عــن طريــق البيــع‬\n\n\n‫‪241‬‬\n\f‫وحيــازة حبــة واحــدة مماثلــة لقصــد التعاطــي وتعاطيــه الســابق لنوعهــا‬\n‫وحكمــت مبجازاتــه علــى جميــع ذلــك بالســجن مــدة ثــاث ســنوات‬\n‫ابتــداء مــن تاريــخ التوقيــف وجلــده مائتــن وأربعــن جلــدة مفرقــة علــى‬\n‫ســت دفعــات كل دفعــة أربعــون جلــدة بــن كل دفعــة وأخــرى شــهر‬\n‫وغرامــة ماليــة قدرهــا ألــف ريــال ومنعــه مــن الســفر إلــى خــارج اململكــة‬\n‫مــدة ثــاث ســنوات ومصــادرة الهاتــف اجلوال املذكــور وإدخال قيمته يف‬\n‫مؤسســة النقــد بحســاب إدارة مكافحــة املخــدرات ومصــادرة الشــريحة‬\n‫املذكــورة وعــدم صرفهــا للمدعــى عليــه كمــا حكمــت بإلــزام املدعــى‬\n‫عليــه بإعــادة املبلــغ احلكومــي وقــدره مائــة ريــال ‪ .‬وبعــرض احلكــم علــى‬\n‫املدعــى عليــه قنــع بــه وقــد عــارض املدعــي العــام وطلــب االســتئناف‬\n‫بالئحــة فأجيــب لطلبــه وبــاهلل التوفيــق وصلــى اهلل وســلم علــى نبينــا‬\n               ‫محمــد وآلــه وصحبــه أجمعــن ‪ .‬حــرر يف ‪1433/11/ 8‬ه ـ‬\n‫احلمــد هلل وحــده وبعــد ثــم عــادت املعاملــة مــن محكمــة االســتئناف‬\n‫وبرفقهــا القــرار رقــم وتاريــخ ‪ 1433 / 12 / 21‬ه ـ املتضمــن املالحظــة‬\n‫بــأن فضيلتــه لــم يذكــر اســم املدعــي العــام وال بــد مــن ذلــك ألنــه ركــن‬\n‫مــن أركان الدعــوى إلجــراء مــا يلــزم واهلل املوفــق أ‪.‬هــ‪ .‬واجلــواب عمــا‬\n‫ذكــره أصحــاب الفضيلــة أنــه جــرى إصــاح اخلطــأ يف موضعــه وذكــر‬\n‫اســم املدعــي العــام وبــاهلل التوفيــق وصلــى اهلل وســلم علــى نبينــا محمــد‬\n                                 ‫وآلــه وصحبــه ‪ .‬حــرر يف ‪1434/01/05‬ه ـ ‪.‬‬\n‫ثــم عــادت املعاملــة مــن محكمــة االســتئناف وبرفقهــا القــرار رقــم‬\n‫وتاريــخ ‪1434/01/19‬ه ـ املتضمــن املوافقــة والتصديــق علــى احلكــم‬\n‫قاضي اســتئناف (‪ ).....‬وقاضي اســتئناف (‪ ).....‬وقاضي اســتئناف (‪).....‬‬\n‫احلمــد هلل وحــده والصــاة والســام علــى مــن ال نبــي بعــده ‪،‬وبعــد ‪ -:‬فقد‬\n\n\n                                                                                     ‫‪242‬‬\n\f      ‫جــرى منــا نحــن قضــاة الدائــرة اجلزائيــة األولــى يف محكمــة االســتئناف‬\n      ‫مبنطقــة مكــة املكرمــة اإلطــاع علــى املعاملــة الــواردة الينــا مــن‬\n      ‫فضيلــة رئيــس احملكمــة اجلزائيــة مبكــة املكرمــة برقــم وتاريــخ‬\n      ‫‪1434/1/11‬هـ املرفق بها القرار الشــرعي رقم و تاريخ ‪1433/11/8‬ه‬\n      ‫الصــادر مــن فضيلــة الشــيخ‪ ).....( /‬القاضــي يف احملكمــة اجلزائيــة‬\n      ‫مبكــة املكرمــة ‪ ،‬املتضمــن دعــوى املدعــي العــام ضــد‪ ).....( /‬املتهــم‬\n      ‫بقضيــة مخــدرات احملكــوم فيــه مبــا دون باطنــه‪ .‬وبدراســة احلكــم‬\n      ‫وصــورة ضبطــه والالئحــة االعتراضيــة قررنــا املوافقــة علــى احلكــم بعــد‬\n      ‫اإلجــراء األخيــر واهلل املوفــق ‪ ،‬وصلــى اهلل علــى نبينــا محمــد وعلــى آلــه‬\n                                                                    ‫وصحبــه وســلم ‪.‬‬\n\n\n\n\n‫‪243‬‬\n\f","legal_articles":[],"source_id":"831db040-0b05-5921-907d-640530e541d8","source_file_id":"396a5809-4e7b-56b3-9eb0-4f45acc6dbb7","source_page_start":238,"source_page_end":243,"original_source":"وزارة العدل السعودية","acquisition_source":"official_ministry_download_preserved_in_central_archive","source_url":null,"content_hash":"16411e7bf2de069c253fdf49a9ac5270651a7db36df8f124f24f4bf0014cd6db","normalized_text_hash":"b1858b25ae25e951da042b5bdbe1265575cca75c512c402eff222d073ed9b409","status":"review","review_status":"manual_field_review_pending","legal_search_eligibility":false,"legacy_id":"collector-1434-v18-p238-33448152"},{"id":"eb31a1fb-b1a5-5205-a5c8-f4f1690e2837","document_type":"judgment","category":"judicial","subcategory":"general","title":"مخدرات -حيازة احلشيش املخدر -تعاطي احلشيش املخدر واحلبوب احملظورة -ترويج احلبوب احملظورة -إقرار املدعى عليه -إنكار املدعى عليه وادعاء اإلكراه -شهادة الشهود -تخفيف العقوبة لقلة الكمية ولعدم وجود سوابق -التعزير بالسجن واجللد واإلبعاد عن الباد واملنع من السفر وتغرميه مبلغ مالي ومصادرة اجلوال.","document_number":"33475878","case_number":"33608605","judgment_number":null,"decision_number":null,"circular_number":null,"court":"محكمة الاستئناف","circuit":null,"issuing_authority":"وزارة العدل السعودية","document_date":null,"hijri_date":"1433/03/22","year":"1434","subject":"مخدرات -حيازة احلشيش املخدر -تعاطي احلشيش املخدر واحلبوب احملظورة -ترويج احلبوب احملظورة -إقرار املدعى عليه -إنكار املدعى عليه وادعاء اإلكراه -شهادة الشهود -تخفيف العقوبة لقلة الكمية ولعدم وجود سوابق -التعزير بالسجن واجللد واإلبعاد عن الباد واملنع من السفر وتغرميه مبلغ مالي ومصادرة اجلوال.","summary":null,"facts":null,"claims":null,"reasoning":null,"ruling":null,"principle_text":null,"full_text":"‫رقم الصك‪ 33475878 :‬تاريخه ‪1433/03/22 :‬هـ‬\n                   ‫رقم الدعوى ‪33608605 :‬‬\n     ‫رقم قرار التصديق من محكمة االستئناف‪:‬‬\n           ‫‪ 34246513‬تاريخه‪1434/06/20:‬هـ‬\n\n\n ‫مخــدرات ‪ -‬حيــازة احلشــيش املخــدر ‪ -‬تعاطــي احلشــيش املخــدر‬\n ‫واحلبــوب احملظــورة ‪ -‬ترويــج احلبــوب احملظــورة ‪ -‬إقــرار املدعــى عليــه‬\n ‫‪ -‬إنــكار املدعــى عليــه وادعــاء اإلكــراه ‪ -‬شــهادة الشــهود ‪ -‬تخفيــف‬\n ‫العقوبــة لقلــة الكميــة ولعــدم وجــود ســوابق ‪ -‬التعزيــر بالســجن‬\n ‫واجللــد واإلبعــاد عــن البــاد واملنــع مــن الســفر وتغرميــه مبلــغ مالــي‬\n                                                         ‫ومصــادرة اجلــوال‪.‬‬\n\n\n\n\n           ‫‪ .1‬املادة (‪ )38‬من نظام مكافحة املخدرات و املؤثرات العقلية ‪.‬‬\n           ‫‪ .2‬املادة (‪ )41‬من نظام مكافحة املخدرات و املؤثرات العقلية ‪.‬‬\n           ‫‪ .3‬املادة (‪ )56‬من نظام مكافحة املخدرات و املؤثرات العقلية ‪.‬‬\n           ‫‪ .4‬املادة (‪ )60‬من نظام مكافحة املخدرات و املؤثرات العقلية ‪.‬‬\n\n\n\n ‫ادعــى املدعــي العــام علــى األول بترويــج احلبــوب احملظــورة عــن طريــق‬\n ‫البيع و تعاطي األول احلبوب احملظورة و الثاني بترويج احلبوب احملظورة‬\n ‫عــن طريــق االســتالم و التســليم و حيــازة حبــه مــن حبــوب اإلمفيتامــن‬\n ‫احملظــورة بقصــد الترويــج ‪ ،‬وردت معلومــات عــن قيــام املدعــى عليــه‬\n ‫الثانــي بالتوســط يف ترويــج احلبــوب احملظــورة ‪ ،‬وقــد مت متكني املصدر‬\n\n                                                                                  ‫‪244‬‬\n\f      ‫مــن االتصــال بــه‪ ،‬وطلــب كميــة مــن احلبوب‪،‬مببلــغ مائتــي ريال‪،‬فوافــق‬\n      ‫الوســيط‪ ،‬فتــم تكليــف أحــد األفــراد مــن إدارة مكافحــة املخــدرات‬\n      ‫مــع املصــدر ‪ ،‬ملشــاهدة عمليــة االســتالم والتســليم‪،‬وركب املصــدر‬\n      ‫مــع الفــرد‪ ،‬وملــا تقابــا مــع الوســيط املدعــى عليــه ‪،‬ســلم الفــرد املبلــغ‬\n      ‫للوســيط ‪ ،‬وطلــب منهمــا االنتقــال حلــي آخــر الســتالم احلبــوب ‪ ،‬فتــم‬\n      ‫االنتقــال إلــى احلــي اآلخــر ‪ ،‬وركبــوا يف الســيارة جميعـ ًا الفــرد واملصــدر‬\n      ‫والوســيط‪ ،‬وملــا وصلــوا املــكان املتفــق عليــه ‪ ،‬نــزل الوســيط إلحضــار‬\n      ‫الكميــة ‪ ،‬وغــاب عــن األنظــار ‪ ،‬وعــاد ومعــه املدعــى عليــه األول ‪ ،‬وقــام‬\n      ‫املدعــى عليــه األول بتســليم املدعــى عليــه الثانــي شــيء مــا‪ ،‬حتــت أنظــار‬\n      ‫الفرقــة القابضــة ‪ ،‬وســلم املدعــى عليــه الثاني الوســيط احلبوب وعددها‬\n      ‫خمــس حبــات يشــتبه أن تكــون مــن احلبــوب احملظــورة للمصــدر‪ ،‬أمــام‬\n      ‫أنظــار الفرقــة القابضــة ‪ ،‬فتــم القبــض عليهمــا ‪ ،‬وبتفتيــش املدعــى عليــه‬\n      ‫الثانــي وجــد معــه بجيــب ثوبــه األميــن الســفلي علــى حبــة واحــدة يشــتبه‬\n      ‫أن تكــون مــن احلبــوب احملظــورة ‪ ،‬وضبــط معــه علــى اجلــوال الــذي‬\n      ‫مــن خاللــه مت التنســيق ‪ ،‬و طلــب املدعــي العــام تعزيــر املدعــى عليهمــا‬\n      ‫بالســجن واجللــد والغرامــة واإلبعــاد عــن البــاد لــأول واملنــع مــن الســفر‬\n      ‫للثانــي ومصــادرة اجلوالــن وإلغــاء شــريحتيهما ورد املبلــغ احلكومــي ‪،‬‬\n      ‫أنكــر املدعــى عليــه األول مــا جــاء بدعــوى املدعــي العــام و أقــر املدعــى‬\n      ‫عليــه الثانــي مبــا جــاء بدعــوى املدعــي العــام ‪ ،‬بطلــب البينــة مــن املدعــي‬\n      ‫العــام علــى دعــواه ضــد املدعــى عليــه األول أحضــر الشــاهدين وشــهد‬\n      ‫بإقــرار األول بالتوســط يف ترويــج احلبــوب احملظــورة ‪ ،‬صــدر احلكــم‬\n      ‫علــى املدعــى عليهمــا بالتعزيــر و الســجن و اجللــد و الغرامــة و مصــادرة‬\n      ‫الهاتفــن احملمولــن للمدعــى عليهمــا و إدخــال قيمتهمــا يف مؤسســة‬\n\n\n‫‪245‬‬\n\f‫النقــد وإلغــاء الشــريحتني و إلزامهمــا بإعــادة املبلــغ احلكومــي و إبعــاد‬\n‫األول إلــى خــارج اململكــة وال يســمح بالعــودة إليهــا إال فيمــا تســمح‬\n‫تعليمــات احلــج و العمــرة ‪ ،‬و منــع الثانــي مــن الســفر خــارج اململكــة‬\n‫مــدة ســنتني بعــد انتهــاء محكوميتــه ‪ ،‬لقــاء إدانــة املدعــى عليهمــا‬\n‫بالترويــج ‪ ،‬األول عــن طريــق البيــع ‪ ،‬والثانــي عــن طريــق التوســط ‪،‬‬\n‫باالســتالم والتســليم‪ ،‬وحيــازة املدعــى عليــه الثانــي علــى حبــة مــن حبــوب‬\n‫اإلمفيتامــن احملظــورة بقصــد التعاطــي ‪ ،‬مت النــزول عــن احلــد األدنــى‬\n‫للعقوبــة بحــق املدعــى عليهمــا لعــدم وجــود ســوابق بحقهمــا ‪ ،‬ومبــادرة‬\n‫الثانــي باالعتــراف ‪ ،‬ولظروفــه األســرية‪ ،‬قنــع املدعــى عليهمــا باحلكــم‬\n‫‪ ،‬وقــرر املدعــي العــام اعتراضــه علــى احلكــم الئحــة اعتراضيــة ‪ ،‬صدق‬\n                                           ‫احلكــم مــن محكمــة االســتئناف‪.‬‬\n\n\n\n\n‫احلمــد هلل وحــده وبعــد فلــدي أنــا ‪ ....‬القاضــي يف احملكمــة اجلزائيــة‬\n‫بتبــوك وبنــاء علــى املعاملــة احملالــة لنــا مــن فضيلــة رئيــس احملكمــة‬\n‫اجلزائيــة بتبوك‪/‬املســاعد برقــم ‪ .....‬وتاريــخ ‪1433/11/14‬ه ـ املقيــدة‬\n‫باحملكمــة برقــم ‪ .....‬وتاريــخ ‪1433/10/17‬ه ـ ففــي يــوم االثنــن‬\n‫املوافق‪1433/11/22‬ه ـ افتتحــت اجللســة وفيها حضر املدعي العام ‪......‬‬\n‫واملعمــد مــن مرجعــه مبوجــب اخلطــاب رقــم ‪ 13058‬يف ‪1433/09/05‬ه ـ‬\n‫وحضــر حلضــوره ‪ ....‬ســجله املدنــي رقــم ‪ ....‬العمــر ‪ 22‬عاطــل عــن العمــل‬\n‫وبالرجــوع للمعاملــة وجــد أنهــا مشــتملة علــى الئحــة دعــوى عامــة ضــد ‪...‬‬\n‫املذكــور تتضمــن أنــه ورد مبحضــر الشــراء والقبــض والتفتيــش املعــد‬\n‫مــن قبــل إدارة مكافحــة املخــدرات بتبــوك أنــه بتاريــخ ‪1433/08/28‬ه ـ‬\n\n                                                                                    ‫‪246‬‬\n\f      ‫توفــرت معلومــات لديهــم مــن أحــد املصــادر الســرية بأنــه يوجــد شــخص‬\n      ‫يدعــى ‪ ...‬يســكن بحــي املنتــزه يقــوم بترويــج احلبــوب احملظــورة وأنــه‬\n      ‫يقــوم بالتنســيق علــى جوالــه رقــم (‪ )....‬يف عمليــة الترويــج وأنــه مســتعد‬\n      ‫بالشــراء منــه أمــام الفرقــة القابضــة وبالفعــل مت االتصــال علــى املــروج‬\n      ‫أمــام مســمع الفرقــة القابضــة وطلــب منــه املصــدر كميــة مــن احلبــوب‬\n      ‫مببلــغ(‪ )100‬مائــة ريــال فذكــر لــه املــروج بأنــه موجــود بحــي ‪ .....‬وأن‬\n      ‫األغــراض موجــودة فأفــاد املصــدر بأنــه قــادم إليــه ســير ًا علــى األقــدام‬\n      ‫وأنــه قريــب مــن محطــة (‪ ).....‬وعليــه انتهــت املكاملــة وعنــد وصــول‬\n      ‫املصــدر إلــى احملطــة مت تفتيــش املصــدر وترقيــم املبلــغ احلكومــي وقــام‬\n      ‫املصــدر باالتصــال علــى املــروج وذكــر لــه بأنــه متواجــد يف محطــة‬\n      ‫فذكــر لــه املــروج بأنــه قــادم إليــه ســير ًا علــى األقــدام عندهــا مت توزيــع‬\n      ‫املهــام واملراقبــة مــن قبــل الفرقــة القابضــة وعنــد ذلــك مت مشــاهدة‬\n      ‫املــروج وهــو قــادم إلــى املصــدر خلــف احملطــة وقــام مبقابلتــه وبعــد‬\n      ‫مغــادرة املــروج للموقــع بعــد مشــاهدة عمليــة االســتالم والتســليم مــن‬\n      ‫قبــل الفرقــة أعطيــت اإلشــارة املتفــق عليهــا بالقبــض علــى املــروج ومت‬\n      ‫القبــض عليــه وبتفتيشــه شــخصي ًا اتضــح أنــه املدعــى عليــه املذكــور‬\n      ‫وبتفتيشــه مت العثــور علــى املبلــغ احلكومــي املرقــم وقــدره (‪ )100‬مائــة‬\n      ‫ريــال ومت العثــور علــى عــدد(‪ )1‬ســيجارة واحــدة ملفوفــة يشــتبه بــأن‬\n      ‫تكــون مخلوطــة باحلشــيش املخــدر بلــغ وزنهــا (‪950‬ملجــم) تســعمائة‬\n      ‫وخمســون مليجــرام يف اجليــب العلــوي ومت العثــور علــى اجلــوال الــذي مت‬\n      ‫التنســيق معــه يف عمليــة البيــع يف جيــب ثوبــه األيســر هــذا وقــد ســلم‬\n      ‫املصــدر الكميــة املشــتراة للفرقــة وهــي عــدد (‪ )4‬أربــع حبــات يشــتبه‬\n      ‫أن تكــون مــن احلبــوب احملظــورة وقــد مت إيقــاف املدعــى عليــه اســتناد ًا‬\n\n\n‫‪247‬‬\n\f‫للقــرار الــوزاري رقــم(‪ )1900‬املبنــي علــى املــادة رقــم (‪ )112‬مــن نظــام‬\n                                                             ‫اإلجــراءات اجلزائيــة‬\n‫وقــد ورد التقريــر الكيميائــي الشــرعي رقــم (‪ 2395‬م‪/‬م س ت)‬\n‫لعام‪1433‬ه ـ الصــادر مــن مركــز مراقبــة الســموم والكيميــاء الطبيــة‬\n‫الشــرعية بصحــة ‪ ...‬ايجابيــة احلبــوب املروجــة لإلمفيتامــن املنبــه للجهــاز‬\n‫العصبــي واملتضمــن أيض ـ ًا إثبــات إيجابيــة مســتخلص عينــة الســيجارة‬\n‫املضبوطــة التــي ال يعلوهــا أثــار حــرق للحشــيش وهــو مــن املــواد املخــدرة‬\n‫وملــا أشــير إليــه أقــرر توجيــه االتهــام للمدعــى عليــه ‪ ....‬بترويــج عــدد(‪)4‬‬\n‫أربــع حبــات مــن حبــوب االمفيتامــن املنبــه للجهــاز العصبــي احملظــورة‬\n‫عــن طريــق البيــع وتعاطيــه لنوعهــا يف الســابق وبحيــازة عدد (‪ )1‬ســيجارة‬\n‫واحــدة مــن احلشــيش املخــدر بلــغ وزنها(‪950‬ملجــم) تســعمائة وخمســون‬\n‫مليجــرام بقصــد التعاطــي وتعاطيه من ذات الكمية وتعاطيه للحشــيش‬\n‫املخــدر يف الســابق وحيــث أن مــا أقــدم عليــه املدعــى عليــه املذكــور‬\n‫فعــل محــرم شــرعا ومجــرم ومعاقــب عليــه نظامــا واســتنادا للمــادة الثالثة‬\n‫الفقــرة الثالثــة فقــرة (‪ )2‬مــن نظــام مكافحــة املخــدرات رقــم ‪/39‬م يف‬\n‫‪1426/7/8‬ه ـ ممــا يتعــن معــه إحالتــه للمحكمــة اجلزئيــة اســتناد ًا‬\n‫للمادتــن (‪)126‬و(‪ )128‬مــن نظــام اإلجــراءات اجلزائيــة لطلــب مــا يلــي‪-:‬‬\n‫‪-1‬إثبــات مــا أســند إليــه ‪ -2‬احلكــم عليــه بالســجن واجللــد والغرامــة‬\n‫لقــاء مــا أســند إليــه اســتنادا للفقــرة األولــى مــن املــادة الثامنــة والثالثــن‬\n‫مــن نظــام مكافحــة املخــدرات واملؤثــرات العقليــة وإعمــا ًال مبقتضــى‬\n‫املــادة (‪ )62‬الفقــرة (‪ )1‬لتطبيــق العقوبــة األشــد مــن نظــام املشــار إليــه‬\n‫أعــاه ‪ -3‬تشــديد العقوبــة عليــه لقــاء ترويجــه للحبــوب احملظــورة التــي‬\n‫حتتــوي علــى مــادة اإلمفيتامــن املنبــه احملظــور اســتناد ًا لتعميــم صاحــب‬\n\n\n                                                                                           ‫‪248‬‬\n\f      ‫الســمو امللكــي وزيــر الداخليــة رقــم ‪ 2529/4/5/1‬وتاريــخ‬\n      ‫‪1427/02/08‬ه ـ ‪ -4‬احلكــم مبنعــه مــن الســفر خرج اململكة اســتنادا‬\n      ‫للفقــرة األولــى مــن املــادة السادســة واخلمســن مــن نظــام مكافحــة‬\n      ‫املخــدرات واملؤثــرات العقليــة املشــار إليــه ‪ -5‬احلكــم مبــا صــادرة جــوال‬\n      ‫املدعــى عليــه املضبــوط يف عمليــة التنســيق للترويــج نــوع نوكيــا يحمــل‬\n      ‫الرقــم ‪ ....‬اســتنادا للمــادة الثالثــة واخلمســن الفقــرة األولــى مــن نظــام‬\n      ‫مكافحــة املخــدرات واملؤثــرات العقليــة املشــار إليــه اعــاه ‪ -6‬احلكــم‬\n      ‫بإلغــاء شــريحة الهاتــف رقــم (‪ )....‬اســتنادا لتعميــم صاحــب الســمو‬\n      ‫امللكــي نائــب رئيــس مجلــس الــوزراء وزيــر الداخليــة رقــم‬\n      ‫(‪9798/4/5/1‬س د) يف ‪ 1428/2/10‬ه ـ هكــذا ادعــى وبســؤال‬\n      ‫املدعــى عليــه عــن الدعــوى أجــاب بقولــه صحيــح أنــه مت القبــض علــي مــن‬\n      ‫قبــل مكافحــة املخــدرات ومعــي صــاروخ حشــيش لغــرض االســتعمال‬\n      ‫والتعاطــي فأنــا أدخــن احلشــيش املخــدر منــذ فتــرة قريبــة ومــا ذكــره‬\n      ‫املدعــي العــام مــن أننــي قمــت ببيــع أربــع حبــات مبائــة ريــال فغيــر صحيــح‬\n      ‫واجلــوال املذكــور يف الدعــوى ليــس لــي وال أعــرف ملــن هكــذا أجــاب‬\n      ‫وبطلــب البينــة مــن املدعــي العــام قــال أطلــب مهلــة إلحضــار أفــراد الفرقة‬\n      ‫هكــذا قــرر ورفعــت اجللســة لذلــك ويف يــوم الثالثــاء‬\n      ‫املوافق‪1433/12/21‬ه ـ افتتحــت اجللســة وفيهــا حضــر املدعــي العــام‬\n      ‫واملدعــى عليــه وبطلــب البينــة مــن املدعــي العــام أحضــر للشــهادة و أدائها‬\n      ‫‪ ....‬ســعودي اجلنســية مبوجــب الســجل املدنــي رقــم ‪ ....‬وبســؤاله عمــا لديــه‬\n      ‫مــن شــهادة قــال أشــهد هلل بأننــي ســمعت املكاملــة التــي دارت بــن‬\n      ‫املصــدر واملــروج واتفقــا علــى شــراء حبــوب مبائــة ريــال و أن يتــم اللقــاء‬\n      ‫يف حــي ‪ ....‬خلــف محطــة ‪ ....‬وكان ذلــك يف متــام الســاعة العاشــرة مســاءا‬\n\n\n‫‪249‬‬\n\f‫تقريبــا وعندمــا حضرنــا للموقــع قمــت بتفتيــش املصــدر وأعطيتــه مائــة‬\n‫ريــال و أنزلتــه علــى الشــارع الرئيســي خلــف احملطــة فقابــل املصــدر‬\n‫املــروج وهــو هــذا احلاضــر ورأيتــه يســلمه شــيئا وأســتلم منــه املبلــغ‬\n‫فأعطيــت اإلشــارة ألعضــاء الفرقــة فتــم القبــض عليــه ووجــد معــه املبلــغ‬\n‫احلكومــي وســيجارة مخلوطــة باحلشــيش كمــا وجــدت مــع املصــدر‬\n‫أربــع حبــات وكان معــي يف الســيارة ‪ ...‬وقــد تــويف أثنــاء مداهمــة أحــد‬\n‫املروجــن هكــذا شــهد وبعــرض الشــاهد و مــا جــاء يف شــهادته علــى‬\n‫املدعــى عليــه قــال صحيــح أنــه مت القبــض علــي خلــف محطــة ‪ ...‬يف ‪...‬‬\n‫وكان بحوزتــي ســيجارة مخلوطــة باحلشــيش املخــدر ومــا ســوى ذلــك‬\n‫فغيــر صحيــح والشــاهد هــو مــن قــام بضربــي هكــذا أجــاب كمــا‬\n‫حضــر للشــهادة وأدائهــا ‪ ....‬ســعودي اجلنســية مبوجــب الســجل املدنــي‬\n‫رقــم ‪ .....‬وبســؤاله عمــا لديــه مــن شــهادة قــال أشــهد هلل بأننــي ســمعت‬\n‫املكاملــة التــي متــت بــن املصــدر واملــروج واالتفــاق علــى شــراء احلبــوب‬\n‫مببلــغ مائــة ريــال وبعدهــا اجتهنــا للموقــع املتفــق عليــه ونزلــت خلــف‬\n‫احملطــة علــى نفــس الشــارع و رأيــت املصــدر يقابــل املــروج وهــو هــذا‬\n‫احلاضــر ولكــن لــم أشــاهد عمليــة االســتالم والتســليم وبعدمــا أعطانــا‬\n‫قائــد الفرقــة اإلشــارة مت القبــض عليــه وبتفتيشــه وجــد يف جيبــه األيســر‬\n‫املبلــغ احلكومــي وقــدره مائــة ريــال كمــا وجــد يف جيبــه العلــوي علــى‬\n‫ســيجارة مخلوطــة باحلشــيش املخــدر هكــذا شــهد وبعــرض الشــاهد‬\n‫ومــا جــاء يف شــهادته علــى املدعــى عليــه قــال مــا جــاء يف شــهادته غيــر‬\n‫صحيــح ســوى حيــازة احلشــيش كمــا أن الشــاهد لــم يكــن موجــودا‬\n‫وقــت املداهمــة هكــذا أجــاب وبطلــب تزكيــة الشــاهدين حضــر كال‬\n‫مــن ‪ ....‬و‪ ...‬وشــهد كل واحــد منهمــا بقولــه أشــهد هلل بــأن الشــاهدين‬\n\n\n                                                                                   ‫‪250‬‬\n\f      ‫عــدالن ثقتــان وال نعلــم عنهمــا إال خيــرا هكــذا شــهدا وبتصفــح أوراق‬\n      ‫املعاملــة وجــدت علــى اللفــة رقــم (‪ )15،16‬حتقيقــا مــع املدعــى عليــه‬\n      ‫وعليــه توقيــع بالبصمــة منســوب إليــه وبــه إقــرار منــه ببيــع أربــع حبــات‬\n      ‫مبائــة ريــال وبعرضــه عليــه قــال صحيــح أننــي قمــت بالتبصيــم علــى هــذا‬\n      ‫احملضــر وبعــد تالوتــه علــي مــن قبــل احملقــق ولكــن كان ذلــك‬\n      ‫االعتــراف بســبب الضــرب وليــس لــدي بينــه علــى ذلــك هكــذا أجــاب ‪.‬‬\n      ‫فبنــاء علــى مــا تقــدم مــن الدعــوى واإلجابــة املتضمنــة مصادقــة املدعــى‬\n      ‫عليــه بتدخينــه للحشــيش وحيازتــه لســيجاره مخلوطــة باحلشــيش‬\n      ‫وإنــكاره ترويــج احلبــوب وبعــد االطــاع علــى التقريــر الكيمائــي املشــار‬\n      ‫إليــه و ملــا جــاء يف شــهادة الشــاهدين املعدلــن شــرعا وملــا جــاء يف إقــراره‬\n      ‫حتقيقــا ونظــرا لرجوعــه عنــه و ادعــاء اإلكــراه عليــه وليــس لديــه بينــه‬\n      ‫علــى ذلــك و ملــا قــرره ابــن قدامــه رحمــه اهلل يف املغنــي (‪ )389/10‬بقولــه‬\n      ‫(وال يقبــل رجــوع املقــر عــن إقــراره إال فيمــا كان حــدا هلل تعالــى يــدر‬\n      ‫بالشــبهات ويحتــاط إلســقاطه فأمــا حقــوق اآلدميــن وحقــوق اهلل تعالــى‬\n      ‫التــي ال تــدرأ بالشــبهات كالــزكاة والكفــارات فــا يقبــل رجوعــه‬\n      ‫عنهــا وال نعلــم يف هــذا خالفــا) أ‪.‬ه ـ وملــا جــاء يف الفقــرة األولــى مــن املــادة‬\n      ‫الثامنــة والثالثــن والفقــرة األولــى مــن املــادة السادســة واخلمســن مــن‬\n      ‫النظــام املشــار إليــه ونظــرا لقلــة الكميــة وعــدم وجــود ســوابق علــى‬\n      ‫املدعــى عليــه وملــا جــاء يف املــادة ســتني مــن النظــام املشــار إليــه والتــي‬\n      ‫جتيــز النــزول عــن احلــد األدنــى وملــا تســببه هــذه احلبــوب مــن فســاد للعقــل‬\n      ‫وإفســاد للبــاد والعبــاد وبنــاء علــى جميــع مــا تقــدم فقــد ثبــت لــدي إدانــة‬\n      ‫املدعــى عليــه بتدخينــه للحشــيش املخــدر وحيازتــه لســيجاره مخلوطــة‬\n      ‫باحلشــيش املخــدر بلــغ وزنهــا تســعمائة وخمســون ملجــم وترويجــه ألربــع‬\n\n\n‫‪251‬‬\n\f‫حبــات حتتــوي علــى مــادة االمفيتامــن وقــررت بحقــه مــا يلــي أوال جلــد‬\n‫املدعــى عليــه ثمانــن جلــدة حــد املســكر ثانيــا تعزيــر املدعــى عليــه‬\n‫بجلــده ثالثمائــة جلــدة مفرقــة علــى ســت دفعــات متســاوية بــن كل‬\n‫دفعــة والتــي تليهــا مــدة ال تقــل عــن عشــرة أيــام ثالثــا تعزيــر املدعــى عليــه‬\n‫بحبســه ملــدة ثــاث ســنوات اعتبــارا مــن تاريــخ توقيفــه علــى ذمــة القضيــة‬\n‫رابعــا تغــرمي املدعــى عليــه ألــف ريــال تــودع لصالــح اخلزينــة العامــة للدولــة‬\n‫خامســا مصــادرة جهــاز جوالــه والــذي يحمــل الرقــم (‪ )....‬من نــوع نوكيا‬\n‫وإيداعــه لصالــح اخلزينــة العامــة للدولــة سادســا إلغــاء شــريحة اجلــوال‬\n‫التــي حتمــل الرقــم (‪ )....‬ســابعا منــع املدعــى عليــه مــن الســفر خــارج‬\n‫اململكــة مــدة مماثلــه ملــدة ســجنه تبــدأ مــن تاريــخ انتهــاء محكوميتــه يف‬\n‫البنــد ثالثــا ومبــا ذكــر حكمــت فقــرر احملكــوم عليــه قناعتــه بــه ولــم‬\n‫يقنــع بــه املدعــي العــام وطلــب متييــزه مكتفيــا بالئحــة الدعــوى عــن‬\n‫الالئحــة االعتراضيــة فأجبتــه لطلبــه وســيتم بعــث كامــل أوراق املعاملــة‬\n‫حملكمــة االســتئناف لتدقيــق احلكــم حســب املتبــع وبــاهلل التوفيــق ‪،‬‬\n‫وصلــى اهلل علــى نبينــا محمــد وعلــى آلــه وصحبــه وســلم ‪ .‬حــرر يف‬\n‫‪ 1433/12/21‬احلمــد هلل وحــده وبعــد ففــي يــوم الســبت‬\n‫املوافــق‪ 1434/04/20‬ه ـ حضــر املدعــى عليــه وقــد أعيــدت املعاملــة‬\n‫بخطــاب رئيــس محكمــة االســتئناف املســاعد بتبــوك برقــم ‪ ....‬يف‬\n‫‪1434/04/07‬ه ـ وأحيلــت إلــي بخطــاب رئيــس احملكمــة اجلزئيــة رقــم‬\n‫‪ ....‬يف ‪1434/04/10‬ه ـ وقــد صــدر قــرار الدائــرة اجلزائيــة الثانيــة رقــم‬\n‫‪ .....‬يف ‪1434/04/02‬ه ـ املتضمــن حكــم فضيلتــه مبــا هــو مــدون‬\n‫ومفصــل فيــه وبدراســة القــرار وصــورة ضبطــه وأوراق املعاملــة لوحــظ‬\n‫مــا يلــي أوالً‪ :‬املدعــى عليــه ال يحمــل إثبــات هويتــه ســوى إثبــات مؤقــت‬\n\n\n                                                                                           ‫‪252‬‬\n\f      ‫علــى اللفــة (‪ )4‬وعليــه صورتــه مــع اخلتــم للجهــة املختصــة ولــم يشــر‬\n      ‫فضيلتــه لذلــك لدفــع اإليهــام بــأن مــا ذكــر مــن رقــم الســجل املدنــي‬\n      ‫حلملــه الهويــة الرســمية ثانيـاً‪ :‬ورد بالدعــوى اتهــام املدعــى عليــه بتعاطــي‬\n      ‫حبــوب االمفيتامــن احملظــورة ولــم يتضمــن احلكــم عقوبتــه علــى ذلــك‬\n      ‫كمــا لــم يتضمــن احلكــم أيضـ ًا الغــرض والقصــد مــن حيــازة ســيجارة‬\n      ‫احلشــيش مــع أنــه ذكــر بالدعــوى أنهــا بقصــد التعاطــي ثالث ـاً‪ :‬طلــب‬\n      ‫املدعــي العــام تشــديد العقوبــة لقــاء ترويــج املدعــى عليــه للحبــوب ولــم‬\n      ‫يجــر فضيلتــه شــيئ ًا حيــال ذلــك واحلكــم نــزل عــن احلــد األدنــى للعقوبــة‬\n      ‫دون التســبيب لذلــك رابع ـاً‪ :‬لــم يوضــح فضيلتــه مســتنده يف كــون‬\n      ‫الغرامــة وقيمــة مصــادرة اجلــوال تــودع لصالــح اخلزينــة العامــة للدولــة‬\n      ‫حســبما ورد يف احلكــم ويوجــد أخطــاء نحويــة وإمالئيــة معلــم عليهــا‬\n      ‫لتصحيحهــا مــع التنبيــه إلــى أنــه أشــير يف التســبيب إلــى عــدم وجــود‬\n      ‫ســوابق للمدعــى عليــه ولــم يشــر لصحيفــة ســوابقه ومضمونهــا طاملــا‬\n      ‫األمــر مــا ذكــر وأنــه حكــم باجللــد ثمانــن حــد املســكر ولــم يذكــر‬\n      ‫نــوع املســكر املقــام فيــه احلــد وإلــى أن أحــد الشــهود ذكــر أســمه ثالثيـ ًا‬\n      ‫فقــط ولــم يذكــر رباعي ـ ًا حســب هويتــه ولــم يشــر يف القــرار إلــى أن‬\n      ‫هويتــي املعدلــن مدونــة بضبطــه ملالحظــة ذلــك وإحلــاق مــا يجريــه علــى‬\n      ‫الضبــط والقــرار وصورتــه حســب التعليمــات واهلل املوفــق وبســؤال‬\n      ‫املدعــى عليــه هــل حتمــل إثبــات هويــة قــال ليــس لــدي إثبــات هويــة وإمنــا‬\n      ‫أنــا مضــاف مــع والــدي يف كــرت العائلــة هكــذا أجــاب وعليــه فــإن‬\n      ‫الســجل املدنــي املــدون أعــاه خــاص باملدعــى عليــه وفقـ ًا لإلنــاث املؤقــت‬\n      ‫املرفــق رقــم (‪ )4‬وأمــا مــا جــاء يف ثاني ـ ًا فقــد ثبــت لــدي إدانــة املدعــى‬\n      ‫عليــه بحيازتــه لســيجارة مخلوطــة باحلشــيش املخــدر بلــغ وزنهــا تســعمائة‬\n\n\n‫‪253‬‬\n\f‫وخمســن ملجــم لقصــد االســتعمال والتعاطي وأجاب أصحــاب الفضيلة‬\n‫بــأن عقابــه عــن اســتخدامه للحبــوب داخــل يف حــد املســكر وأمــا مــا‬\n‫جــاء يف ثالثـ ًا فقــد ذكــرت يف تســبيب احلكــم بــأن املدعــى عليــه ليــس‬\n‫لديــه ســوابق ولقلــة الكميــة التــي قــام ببيعهــا فهــذه األســباب التــي دعــت‬\n‫إلــى النــزول عــن احلــد األدنــى مــن العقوبــة وأمــا مــا جــاء يف رابع ـ ًا فــإن‬\n‫املســتند يف ذلــك هــو الفقــرة األولــى مــن املــادة الثالثــة واخلمســن مــن‬\n‫نظــام مكافحــة املخــدرات واملؤثــرات العقليــة وبــاهلل التوفيــق ‪ ،‬وصلــى‬\n‫اهلل علــى نبينــا محمــد وعلــى آلــه وصحبــه وســلم ‪ .‬حــرر يف‬\n                                                                   ‫‪1434/04/20‬هـ‬\n‫احلمــد هلل وحــده وبعــد فقــد اطلعن ــا نحن قـض ــاة الدائ ــرة اجلزائية الثانية‬\n‫يف محكمــة االســتئناف مبنطقــة تبــوك علــى املعاملــة الــواردة من فضيلة‬\n‫رئيــس احملكمــة اجلزائيــة بتبــوك برقــم ‪ .....‬وتاريخ‪1434/5/6‬ه ـ املرفــق‬\n‫بهــا القــرار الصــادر مــن فضيلــة القاضــي يف احملكمــة الشــيخ ‪ ....‬برقــم‬\n‫‪ ....‬وتاريــخ‪ 1433/12/22‬ه ـ اخلــاص بدعــوى املدعــي العــام ضــد املدعــى‬\n‫عليــه ‪ ......‬يف قضيــة مخــدرات واملتضمــن حكــم فضيلتــه مبــا هــو مــدون‬\n‫ومفصــل فيــه ‪ .‬وبدراســة القــرار وصــورة ضبطــه وأوراق املعاملــة ومــا‬\n‫أحلقــه فضيلتــه علــى قــرار الدائــرة رقــم ‪ .....‬وتاريــخ ‪1434/4/2‬ه ـ ‪،‬‬\n‫قررنــا املصادقــة علــى احلكــم بعــد اإلجــراء األخيــر ‪ .‬مــع تنبيــه فضيلتــه‬\n‫إلــى تصحيــح األخطــاء املطبعيــة املعلــم عليهــا بالقــرار ‪ .‬واهلل املوفــق‬\n                         ‫وصلــى اهلل علــى نبينــا محمــد وآلــه وصحبــه وســلم‪.‬‬\n\n\n\n\n                                                                                          ‫‪254‬‬\n\f","legal_articles":[],"source_id":"831db040-0b05-5921-907d-640530e541d8","source_file_id":"396a5809-4e7b-56b3-9eb0-4f45